function mergeSprintHistory(incoming?: any[]): any[] {
  const map = new Map<string, any>();
  for (const defSprint of DEFAULT_SPRINT_HISTORY) {
    map.set(defSprint.id, defSprint);
  }
  if (Array.isArray(incoming)) {
    for (const s of incoming) {
      if (s && s.id) {
        // Ignore premature Week 4 (sprint_4) records created before Week 4's Friday 11:59 PM (Nov 6, 2026 23:59 IST = 1793989740000)
        if ((s.id === 'sprint_4' || Number(s.sprintNumber) === 4) && (!s.recordedAt || Number(s.recordedAt) < 1793989740000)) {
          continue;
        }
        const existing = map.get(s.id);
        if (!existing) {
          map.set(s.id, s);
        } else {
          const mergedStandings =
            Array.isArray(s.standings) && s.standings.length > 0
              ? s.standings.map((row: any, idx: number) => {
                  const defRow = Array.isArray(existing.standings)
                    ? existing.standings.find(
                        (r: any) =>
                          r.id === row.id ||
                          r.rank === row.rank ||
                          (r.name && row.name && r.name.toLowerCase() === row.name.toLowerCase())
                      ) || existing.standings[idx]
                    : null;
                  return defRow ? { ...defRow, ...row } : row;
                })
              : existing.standings;
          map.set(s.id, { ...existing, ...s, standings: mergedStandings });
        }
      }
    }
  }
  return Array.from(map.values()).sort(
    (a, b) => (Number(b.sprintNumber) || 0) - (Number(a.sprintNumber) || 0)
  );
}

function getStartOfCurrentWeek() {
  const now = new Date();
  const day = now.getDay();
  const distanceToMonday = (day + 6) % 7;
  const monday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - distanceToMonday, 0, 0, 0, 0);
  return monday.getTime();
}

function calcPercentile(rank: number | string, totalStudents: number | string) {
  const r = Number(rank);
  const t = Number(totalStudents);
  if (!r || !t || t <= 0 || r <= 0) return 0;
  if (r > t) return 0;
  if (t === 1) return 100;
  return Math.max(0, Math.min(100, (1 - (r - 1) / t) * 100));
}

// Question breakdown calculator with accuracy percentage and partial attempt credit
function calcQuestionsDetail(
  solvedInput: number | string | { [key: string]: number | string } = 0,
  attemptedInput: number | string | { [key: string]: number | string } = 0,
  difficulty = 'mains'
) {
  let solvedCount = 0;
  let rawSolvedXp = 0;
  if (typeof solvedInput === 'object' && solvedInput !== null) {
    for (const [tierId, val] of Object.entries(solvedInput)) {
      const count = Math.max(0, Number(val) || 0);
      solvedCount += count;
      const tierObj = DIFFICULTY_TIERS.find(d => d.id === tierId) || DIFFICULTY_TIERS[1];
      rawSolvedXp += count * tierObj.mult;
    }
  } else {
    solvedCount = Math.max(0, Number(solvedInput) || 0);
    const tier = DIFFICULTY_TIERS.find(d => d.id === difficulty) || DIFFICULTY_TIERS[1];
    rawSolvedXp = solvedCount * tier.mult;
  }

  let attemptedCount = 0;
  let rawAttemptedXp = 0;
  if (typeof attemptedInput === 'object' && attemptedInput !== null) {
    for (const [tierId, val] of Object.entries(attemptedInput)) {
      const count = Math.max(0, Number(val) || 0);
      attemptedCount += count;
      const tierObj = DIFFICULTY_TIERS.find(d => d.id === tierId) || DIFFICULTY_TIERS[1];
      rawAttemptedXp += count * (tierObj.attemptMult || 0.5);
    }
  } else {
    attemptedCount = Math.max(0, Number(attemptedInput) || 0);
    const tier = DIFFICULTY_TIERS.find(d => d.id === difficulty) || DIFFICULTY_TIERS[1];
    rawAttemptedXp = attemptedCount * (tier.attemptMult || 0.5);
  }

  const totalQuestions = solvedCount + attemptedCount;
  const solveRate = totalQuestions > 0 ? Math.round((solvedCount / totalQuestions) * 100) : 0;
  const totalQuestionXp = Math.round(rawSolvedXp + rawAttemptedXp);

  return {
    solvedCount,
    solvedXp: Math.round(rawSolvedXp * 10) / 10,
    attemptedCount,
    attemptedXp: Math.round(rawAttemptedXp * 10) / 10,
    totalQuestions,
    solveRate,
    totalQuestionXp
  };
}

// Session XP calculation supporting multi-difficulty question breakdown, attempted (unsolved) questions, and task bonus override
function calcSessionXp(
  durationMins: number | string,
  questionsOrBreakdown: number | string | { [key: string]: number | string } = 0,
  difficulty = 'mains',
  sessionType = 'STUDY',
  attemptedOrBreakdown: number | string | { [key: string]: number | string } = 0
) {
  if (sessionType !== 'STUDY') return 0;
  const mins = Math.max(0, Number(durationMins) || 0);
  const timeXp = Math.round((mins / 30) * 10);

  const detail = calcQuestionsDetail(questionsOrBreakdown, attemptedOrBreakdown, difficulty);

  // Generous cap: allows high volume problem sessions with full solved and attempted credit
  const maxAllowedQXp = Math.max(45, Math.round((mins / 60) * 85) + 45);
  const cappedQXp = Math.min(detail.totalQuestionXp, maxAllowedQXp);

  return timeXp + cappedQXp;
}

function parseQuickTimeRange(inputStr: string) {
  if (!inputStr || !inputStr.includes('-')) return null;
  const parts = inputStr.split('-').map(s => s.trim());
  if (parts.length !== 2) return null;

  const parseSingleTime = (tStr: string) => {
    const clean = tStr.toLowerCase().replace(/\s+/g, '');
    const match = clean.match(/^(\d{1,2})(?::(\d{2}))?(am|pm)?$/);
    if (!match) return null;
    let hours = parseInt(match[1], 10);
    const mins = match[2] ? parseInt(match[2], 10) : 0;
    const mer = match[3];
    if (mins < 0 || mins > 59 || hours < 0 || hours > 23) return null;
    if (mer === 'pm' && hours < 12) hours += 12;
    if (mer === 'am' && hours === 12) hours = 0;
    return { hours, mins };
  };

  const start = parseSingleTime(parts[0]);
  const end = parseSingleTime(parts[1]);
  if (!start || !end) return null;

  let startTotal = start.hours * 60 + start.mins;
  let endTotal = end.hours * 60 + end.mins;
  if (endTotal <= startTotal) {
    endTotal += 12 * 60;
    if (endTotal <= startTotal) endTotal += 12 * 60;
  }
  const duration = endTotal - startTotal;
  if (duration <= 0 || duration > 1440) return null;

  const formatHHMM = (h: number, m: number) => `${String(h % 24).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
  return {
    startTime: formatHHMM(start.hours, start.mins),
    endTime: formatHHMM(Math.floor(endTotal / 60), endTotal % 60),
    duration
  };
}

// Image compression helper moved to src/utils/image.ts

function formatDuration(mins: number | string) {
  const m = Math.round(Number(mins) || 0);
  if (m <= 0) return '0m';
  const hrs = Math.floor(m / 60);
  const rem = m % 60;
  if (hrs === 0) return `${rem}m`;
  if (rem === 0) return `${hrs}h`;
  return `${hrs}h ${rem}m`;
}

function timeAgo(timestamp: number | null | undefined) {
  if (!timestamp) return 'Just now';
  const diffSec = Math.floor((Date.now() - timestamp) / 1000);
  if (diffSec < 60) return 'Just now';
  const diffMin = Math.floor(diffSec / 60);
  if (diffMin < 60) return `${diffMin}m ago`;
  const diffHr = Math.floor(diffMin / 60);
  if (diffHr < 24) return `${diffHr}h ago`;
  return `${Math.floor(diffHr / 24)}d ago`;
}

function formatFutureRelative(targetMs: number | null | undefined, nowMs: number = Date.now()): string {
  if (!targetMs) return 'Soon';
  const diffMs = targetMs - nowMs;
  if (diffMs <= 0) return 'Any moment now';
  const totalSecs = Math.floor(diffMs / 1000);
  const totalMins = Math.floor(totalSecs / 60);
  const hrs = Math.floor(totalMins / 60);
  const mins = totalMins % 60;
  if (hrs === 0) return `in ${Math.max(1, mins)}m`;
  if (mins === 0) return `in ${hrs}h`;
  return `in ${hrs}h ${mins}m`;
}

function formatExactTime(timestamp: number | null | undefined): string {
  if (!timestamp) return '';
  const d = new Date(timestamp);
  return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', month: 'short', day: 'numeric' });
}

