export interface WeeklySleeperAgentState {
  cycleNumber: number;
  weekKey: string;
  memberId: string;
  memberName: string;
  assignedAt: number;
  previousMemberIds: string[];
  revealedAtBlackout?: boolean;
}

const DEFAULT_WEEKLY_SLEEPER_AGENT: WeeklySleeperAgentState = {
  cycleNumber: 5,
  weekKey: '2026-W46',
  memberId: 'sai',
  memberName: 'Sai',
  assignedAt: 1794163000000,
  previousMemberIds: ['sai'],
  revealedAtBlackout: false
};

function pickNextWeeklySleeperAgent(
  currentSleeper: WeeklySleeperAgentState | null | undefined,
  membersList: Array<{ id: string; name: string; approvalStatus?: string }>,
  nextCycleNum: number,
  nextWeekKey: string
): WeeklySleeperAgentState {
  const eligible = membersList.filter(
    (m) => m && m.id && m.id !== 'admin' && !m.id.startsWith('teacher_') && m.approvalStatus !== 'pending' && m.approvalStatus !== 'rejected'
  );
  if (eligible.length === 0) {
    return {
      ...DEFAULT_WEEKLY_SLEEPER_AGENT,
      cycleNumber: nextCycleNum,
      weekKey: nextWeekKey,
      assignedAt: Date.now(),
      revealedAtBlackout: false
    };
  }
  const prevId = currentSleeper?.memberId || 'sai';
  const historyIds =
    Array.isArray(currentSleeper?.previousMemberIds) && currentSleeper!.previousMemberIds.length > 0
      ? currentSleeper!.previousMemberIds
      : [prevId];

  // Never pick the immediate previous week's scholar, and rotate through all scholars before repeating
  let candidates = eligible.filter((m) => !historyIds.includes(m.id) && m.id !== prevId);
  let resetPool = false;
  if (candidates.length === 0) {
    resetPool = true;
    candidates = eligible.filter((m) => m.id !== prevId);
  }
  if (candidates.length === 0) {
    candidates = eligible;
  }
  const chosen = candidates[Math.floor(Math.random() * candidates.length)];
  const nextHistory = resetPool
    ? [prevId, chosen.id]
    : Array.from(new Set([...historyIds, chosen.id]));
  return {
    cycleNumber: nextCycleNum,
    weekKey: nextWeekKey,
    memberId: chosen.id,
    memberName: chosen.name,
    assignedAt: Date.now(),
    previousMemberIds: nextHistory,
    revealedAtBlackout: false
  };
}

