  const applySandboxUpdater = <T,>(
    field: keyof Pick<GuestDemoState, 'teachers' | 'teacherAssignments' | 'teacherNotes' | 'sessions' | 'exams' | 'tasks' | 'announcements' | 'activities'>,
    realSetter: React.Dispatch<React.SetStateAction<T[]>>,
    updater: React.SetStateAction<T[]>
  ) => {
    if (isGuestMode) {
      setGuestDemoState(prev => {
        if (!prev) return prev;
        const curr = prev[field] as T[];
        const next = typeof updater === 'function' ? (updater as (p: T[]) => T[])(curr) : updater;
        return { ...prev, [field]: next };
      });
      return;
    }
    realSetter(updater);
  };

  const setTeachers = React.useCallback((u: React.SetStateAction<Teacher[]>) => applySandboxUpdater('teachers', setRealTeachers, u), [isGuestMode]);
