  const setTeacherNotes = React.useCallback((u: React.SetStateAction<TeacherNote[]>) => applySandboxUpdater('teacherNotes', setRealTeacherNotes, u), [isGuestMode]);
  const setSessions = React.useCallback((u: React.SetStateAction<any[]>) => applySandboxUpdater('sessions', setRealSessions, u), [isGuestMode]);
