  const [timerLaps, setTimerLaps] = useState<
    Array<{ id: string; lapNumber: number; splitSeconds: number; totalSeconds: number; subject: string; timestamp: string }>
  >(() => {
    try {
      const raw = localStorage.getItem('jee_arena_timer_laps');
      return raw ? JSON.parse(raw) : [];
    } catch (_e) {
      return [];
    }
  });
  const [keepScreenAwake, setKeepScreenAwake] = useState<boolean>(() => {
    return localStorage.getItem('jee_arena_timer_keep_awake') !== 'false';
  });
  const [wakeLockActive, setWakeLockActive] = useState<boolean>(false);
  const [showTimerInfoModal, setShowTimerInfoModal] = useState<boolean>(false);

  const normalizeSubject = (sub: string | undefined): string => {
    if (!sub) return 'Physics';
    const s = sub.trim().toLowerCase();
    if (s.includes('math')) return 'Math';
    if (s.includes('chem')) return 'Chemistry';
    if (s.includes('phys')) return 'Physics';
    if (s.includes('eng')) return 'English';
    if (s.includes('lr') || s.includes('logic')) return 'LR';
    return sub.trim();
  };

  const calculateCurrentTimerSeconds = (
    running: boolean,
    startTime: number | null,
    accumulated: number
  ): number => {
    const safeAcc = Math.max(0, Math.floor(Number(accumulated) || 0));
    if (!running || !startTime || startTime <= 0) return safeAcc;
    const elapsedSinceStart = Math.max(0, Math.floor((getServerSyncedNow() - startTime) / 1000));
    return safeAcc + elapsedSinceStart;
  };

  const [timerSeconds, setTimerSeconds] = useState<number>(() =>
    calculateCurrentTimerSeconds(
      initialTimerEngineState.status === 'RUNNING',
      initialTimerEngineState.segmentStartedAt,
      initialTimerEngineState.accumulatedSeconds
    )
  );

  const persistTimerEngineState = (next: {
    status: 'IDLE' | 'RUNNING' | 'PAUSED';
    segmentStartedAt: number | null;
    accumulatedSeconds: number;
    startedAtStr: string;
  }) => {
    const cleanAcc = Math.max(0, Math.floor(Number(next.accumulatedSeconds) || 0));
    const cleanStart = next.status === 'RUNNING' && next.segmentStartedAt ? next.segmentStartedAt : null;
    const normalized = {
      status: next.status,
      segmentStartedAt: cleanStart,
      accumulatedSeconds: cleanAcc,
      startedAtStr: next.startedAtStr || ''
    };
    timerEngineRef.current = normalized;

    try {
      localStorage.setItem('jee_arena_timer_v3_state', JSON.stringify(normalized));
      if (normalized.status === 'IDLE') {
        localStorage.removeItem('jee_arena_timer_running');
        localStorage.removeItem('jee_arena_timer_start_time');
        localStorage.removeItem('jee_arena_timer_accumulated_secs');
        localStorage.removeItem('jee_arena_timer_started_at_str');
      } else {
        localStorage.setItem('jee_arena_timer_running', normalized.status === 'RUNNING' ? 'true' : 'false');
        if (cleanStart) {
          localStorage.setItem('jee_arena_timer_start_time', String(cleanStart));
        } else {
          localStorage.removeItem('jee_arena_timer_start_time');
        }
        localStorage.setItem('jee_arena_timer_accumulated_secs', String(cleanAcc));
        if (normalized.startedAtStr) {
          localStorage.setItem('jee_arena_timer_started_at_str', normalized.startedAtStr);
        }
      }
    } catch (_e) {
      // Ignore storage quota errors
    }

    const totalNow = calculateCurrentTimerSeconds(
      normalized.status === 'RUNNING',
      normalized.segmentStartedAt,
      normalized.accumulatedSeconds
    );
    setTimerRunning(normalized.status === 'RUNNING');
    setTimerStartTime(normalized.segmentStartedAt);
    setTimerAccumulatedSeconds(normalized.accumulatedSeconds);
    setTimerStartedAtStr(normalized.startedAtStr);
    setTimerSeconds(totalNow);
  };

