  // Ensure notifications & background VAPID Web Push work on mobile (even when locked or when desktop is open)
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const syncPushState = () => {
      if (isGuestMode || localStorage.getItem('jee_arena_active_id') === 'guest') {
        setBlockedPushMemberIds(realMembersState.filter(m => Boolean(m.isArchived)).map(m => m.id));
        return;
      }
      setPushPermission(getNotificationPermission());
      setPushEnabled(isWebPushEnabledByUser());
      if (getNotificationPermission() === 'granted') {
        const memId = localStorage.getItem('jee_arena_active_id') || activeMemberId || '';
        const memName = INITIAL_FIRESTORE_MEMBERS.find((m: any) => m.id === memId)?.name || undefined;
        if (memId) {
          localStorage.setItem('jee_arena_active_member_id', memId);
        }
        syncWebPushSubscription(memId || undefined, memName).catch(() => {});
      }
    };
    syncPushState();
    const periodicPushVerify = setInterval(syncPushState, 90000);
    window.addEventListener('focus', syncPushState);
    window.addEventListener('visibilitychange', syncPushState);
    return () => {
      clearInterval(periodicPushVerify);
      window.removeEventListener('focus', syncPushState);
      window.removeEventListener('visibilitychange', syncPushState);
    };
  }, [activeMemberId, isGuestMode, realMembersState]);


