  const totalLogSolved = useMemo(() => {
    if (logQuestionMode === 'multi_tier') {
      return Object.values(logQuestionsByTier).reduce((acc, val) => acc + (Math.max(0, parseInt(val, 10) || 0)), 0);
    }
    return Math.max(0, parseInt(logQuestions, 10) || 0);
  }, [logQuestionMode, logQuestionsByTier, logQuestions]);

