      setGuestDemoState(prev => {
        if (!prev) return prev;
        const next = typeof updater === 'function' ? (updater as (p: ChatMessage[]) => ChatMessage[])(prev.messages as ChatMessage[]) : updater;
        return { ...prev, messages: next };
      });
