  const handleDeclineOrBreakHostagePact = async (pactId: string) => {
    if (isRaidBlackoutActive) {
      notify('Blackout Protocol Active', 'Hostage Links cannot be altered during Blackout Protocol.', 'error');
      return;
    }
    const basePath = `artifacts/${appId}/public/data`;
    const settingsRef = doc(db, basePath, 'settings', 'arenaState');
    const targetPact = (arenaSettings.hostagePacts || []).find(p => p.id === pactId);
    if (!targetPact) return;

    const updatedPacts = (arenaSettings.hostagePacts || []).filter(p => p.id !== pactId);
    setArenaSettings(prev => ({ ...prev, hostagePacts: updatedPacts }));
    if (!isGuestMode) {
      await setDoc(settingsRef, { hostagePacts: updatedPacts }, { merge: true });
    }
    notify('Pact Removed', 'Blood Pact proposal was declined.');
  };

  const settlingWarfareLockRef = useRef<boolean>(false);

  // Compute exact study minutes and XP generated by a scholar on a specific YYYY-MM-DD dateKey
  const getMemberStatsForDateKey = (memberId: string, targetDateKey: string) => {
    const matchingSessions = sessions.filter(s => {
      if (s.memberId !== memberId) return false;
      if (typeof s.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s.date)) {
        return s.date === targetDateKey;
      }
      const ts = Number(s.timestamp) || 0;
      if (ts > 0) {
        const d = new Date(ts);
        const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
        return key === targetDateKey;
      }
      return false;
    });
    const mins = matchingSessions.reduce((acc, s) => acc + (Number(s.duration) || 0), 0);
    const xp = matchingSessions.reduce((acc, s) => acc + (Number(s.xpEarned) || 0), 0);
    return { mins, xp };
  };

  // Manual or Automated Midnight Settlement for Robin Hood Ambushes & Hostage Links
  const handleSettleDailyWarfare = async (dateKeyToSettle: string, isAutoCatchUp = false) => {
    if (settlingWarfareLockRef.current || isFirestoreQuotaExceeded()) return;
    settlingWarfareLockRef.current = true;

    try {
      const basePath = `artifacts/${appId}/public/data`;
      const settingsRef = doc(db, basePath, 'settings', 'arenaState');
      const nowMs = Date.now();

      // 1. Settle Robin Hood Ambushes (for dateKeyToSettle, plus any older unsettled ambushes if triggered manually)
      const activeAmbushes = (arenaSettings.ambushes || []).filter(a =>
        a.status === 'active' && (isAutoCatchUp ? a.dateKey === dateKeyToSettle : a.dateKey <= dateKeyToSettle)
      );

      let nextAmbushes = [...(arenaSettings.ambushes || [])];
      let settledAmbushCount = 0;

      if (activeAmbushes.length > 0) {
        for (const amb of activeAmbushes) {
          const targetDayKey = amb.dateKey || dateKeyToSettle;
          const kingDay = getMemberStatsForDateKey(amb.kingId, targetDayKey);
          const ambDay = getMemberStatsForDateKey(amb.ambusherId, targetDayKey);
          const kingMins = kingDay.mins;
          const kingDailyXp = Math.max(0, kingDay.xp);
          const ambMins = ambDay.mins;

          if (ambMins > kingMins) {
            const siphonedXp = Math.max(25, Math.round(kingDailyXp * 0.2));
            await adjustMemberActiveSprintXp(amb.kingId, -siphonedXp);
            await adjustMemberActiveSprintXp(amb.ambusherId, siphonedXp + amb.entryFeeXp);
            nextAmbushes = nextAmbushes.map(item =>
              item.id === amb.id
                ? {
                    ...item,
                    status: 'ambusher_won' as const,
                    ambusherMins: ambMins,
                    kingMins: kingMins,
                    xpSiphoned: siphonedXp,
                    siphonedXp,
                    settledAt: nowMs,
                    resolvedAt: nowMs
                  }
                : item
            );
            await pushActivity(
              'ambush_won',
              `🏹 ${amb.ambusherName} overthrew The King (${amb.kingName}) in the Robin Hood Ambush!`,
              `Logged ${ambMins}m vs King's ${kingMins}m on ${targetDayKey} • Refunded 50 XP + Siphoned ${siphonedXp} XP (20% of King's daily XP)!`,
              amb.ambusherId,
              siphonedXp
            );
          } else {
            await adjustMemberActiveSprintXp(amb.kingId, amb.entryFeeXp);
            nextAmbushes = nextAmbushes.map(item =>
              item.id === amb.id
                ? {
                    ...item,
                    status: 'king_defended' as const,
                    ambusherMins: ambMins,
                    kingMins: kingMins,
                    xpSiphoned: 0,
                    siphonedXp: 0,
                    settledAt: nowMs,
                    resolvedAt: nowMs
                  }
                : item
            );
            await pushActivity(
              'ambush_lost',
              `👑 The King (${amb.kingName}) crushed ${amb.ambusherName}'s Ambush!`,
              `King logged ${kingMins}m vs ${ambMins}m on ${targetDayKey} • King collected +${amb.entryFeeXp} XP Tribute!`,
              amb.kingId,
              amb.entryFeeXp
            );
          }
          settledAmbushCount += 1;
        }
      }

      // 2. Settle Active Hostage Pacts (if not Friday Blackout)
      let nextPacts = [...(arenaSettings.hostagePacts || [])];
      let settledPactCount = 0;
      if (!isFridayBlackoutNow) {
        const activePacts = nextPacts.filter(p => p.status === 'active' && p.lastCheckedDateKey !== dateKeyToSettle);
        for (const pact of activePacts) {
          const idA = (pact.partnerAId || pact.memberAId) || '';
          const idB = (pact.partnerBId || pact.memberBId) || '';
          const nameA = (pact.partnerAName || pact.memberAName) || 'Partner A';
          const nameB = (pact.partnerBName || pact.memberBName) || 'Partner B';
          const totalDays = pact.targetDays || pact.totalDays || 5;
          const dayA = getMemberStatsForDateKey(idA, dateKeyToSettle);
          const dayB = getMemberStatsForDateKey(idB, dateKeyToSettle);
          const minsA = dayA.mins;
          const minsB = dayB.mins;

          if (minsA >= pact.dailyMinMinutes && minsB >= pact.dailyMinMinutes) {
            const nextDays = pact.daysCompleted + 1;
            const isDone = nextDays >= totalDays;
            nextPacts = nextPacts.map(p =>
              p.id === pact.id
                ? {
                    ...p,
                    daysCompleted: nextDays,
                    status: isDone ? ('completed' as const) : ('active' as const),
                    lastCheckedDateKey: dateKeyToSettle
                  }
                : p
            );
          } else {
            // Quota failed! Break multiplier, both lose 100 XP, both enter Gulag state
            const failedWho = minsA < pact.dailyMinMinutes ? nameA : nameB;
            if (idA) {
              await adjustMemberActiveSprintXp(idA, -100, {
                gulagState: true,
                gulagStartedAt: nowMs
              });
            }
            if (idB) {
              await adjustMemberActiveSprintXp(idB, -100, {
                gulagState: true,
                gulagStartedAt: nowMs
              });
            }
            nextPacts = nextPacts.map(p =>
              p.id === pact.id
                ? {
                    ...p,
                    status: 'broken' as const,
                    brokenReason: `${failedWho} missed the 2h daily study quota (${minsA}m / ${minsB}m) on ${dateKeyToSettle}.`,
                    lastCheckedDateKey: dateKeyToSettle
                  }
                : p
            );
            await pushActivity(
              'pact_broken',
              `⛓️ GULAG SENTENCE: ${nameA} & ${nameB}'s Blood Pact shattered!`,
              `${failedWho} missed the 2h quota (${minsA}m / ${minsB}m). Both lost 100 XP and entered the Gulag until a 45m penance session is logged!`,
              idA,
              -100
            );
          }
          settledPactCount += 1;
        }
      }

      if (settledAmbushCount > 0 || settledPactCount > 0 || !isAutoCatchUp) {
        setArenaSettings(prev => ({
          ...prev,
          ambushes: nextAmbushes,
          hostagePacts: nextPacts,
          lastMidnightSettlementDateKey: dateKeyToSettle
        }));
        if (!isGuestMode) {
          await setDoc(
            settingsRef,
            {
              ambushes: nextAmbushes,
              hostagePacts: nextPacts,
              lastMidnightSettlementDateKey: dateKeyToSettle
            },
            { merge: true }
          );
        }
      }

      if (!isAutoCatchUp) {
        if (settledAmbushCount > 0 || settledPactCount > 0) {
          notify(
            'Daily Warfare Settled',
            `Resolved ${settledAmbushCount} Robin Hood Ambush(es) and ${settledPactCount} Blood Pact(s).`
          );
        } else {
          notify(
            'No Pending Settlements',
            'All active Robin Hood Ambushes and Blood Pacts for this date have already been settled.'
          );
        }
      }
    } finally {
      settlingWarfareLockRef.current = false;
    }
  };

  // Automatic Midnight Catch-Up Settlement for Past-Day Active Ambushes (manual settlement only to prevent background XP shifts)
  useEffect(() => {
    if (true || isGuestMode || isFirestoreQuotaExceeded() || sessions.length === 0 || members.length === 0) return;
  }, [isGuestMode, arenaSettings.ambushes, sessions.length, members.length]);

  // Toggle Friday Blackout Simulation (Admin testing utility)
  const handleToggleFridayBlackoutSim = async (nextVal?: boolean) => {
    if (!isAdminUnlocked && activeMemberId !== 'admin') {
      notify('Admin Access Required', 'Only the Administrator can simulate or toggle blackout settings.', 'error');
      return;
    }
    const targetVal = typeof nextVal === 'boolean' ? nextVal : !arenaSettings.simulateFridayBlackout;
    const nowTs = Math.max(Date.now(), getServerSyncedNow());
    const basePath = `artifacts/${appId}/public/data`;
    const settingsRef = doc(db, basePath, 'settings', 'arenaState');
    isBlackoutActiveRef.current = targetVal;
    const simUpdates = {
      simulateFridayBlackout: targetVal,
      leaderboardHidden: targetVal,
      hiddenAt: targetVal ? nowTs : null,
      manualAdminReveal: !targetVal
    };
    setArenaSettings(prev => ({ ...prev, ...simUpdates }));
    await setDoc(settingsRef, simUpdates, { merge: true });
    notify(
      targetVal ? '🔒 Friday Blackout Active' : '☀️ Friday Blackout Lifted',
      targetVal
        ? 'Leaderboard ranks frozen & obfuscated, XP Shop & Duels locked.'
        : 'Saturday Midnight Reveal: All Friday study hours converted to live XP!'
    );
  };

  // Admin Raid Boss Configuration Handler
  const handleAdminUpdateRaidBoss = async (updates: Partial<{
    raidEnabled: boolean;
    raidOverrideSchedule: boolean;
    raidBossId: string;
    raidBossMaxHp: number;
    raidBossCurrentHp: number;
    raidFailedPenaltyActive: boolean;
  }>) => {
    const basePath = `artifacts/${appId}/public/data`;
    const settingsRef = doc(db, basePath, 'settings', 'arenaState');
    setArenaSettings(prev => ({ ...prev, ...updates }));
    try {
      await setDoc(settingsRef, updates, { merge: true });

      // If raidFailedPenaltyActive is toggled ON, mark deferredRaidDebt on any member currently in active_standing (e.g., Ved on off-week)
      if (updates.raidFailedPenaltyActive === true) {
        for (const stat of leaderboardStats) {
          if (stat.standingStatus === 'active_standing') {
            await updateDoc(doc(db, basePath, 'members', stat.id), {
              deferredRaidDebt: true
            }).catch(() => {});
          }
        }
      } else if (updates.raidFailedPenaltyActive === false) {
        for (const m of members) {
          if (m.deferredRaidDebt) {
            await updateDoc(doc(db, basePath, 'members', m.id), {
              deferredRaidDebt: false
            }).catch(() => {});
          }
        }
      }

      notify('⚔️ Raid Boss Settings Saved', 'Co-op Raid Boss configuration synced across all devices.');
    } catch (e) {
      handleFirestoreError(e, OperationType.WRITE, `${basePath}/settings/arenaState`);
    }
  };

  const handlePostLoginMobileAndNotificationSetup = () => {
    if (isGuestMode) return;
    // 1. If logging in on a MOBILE device (and not already in the installed app), prompt to install EVERY TIME. Never on desktop!
    pwa.promptMobileInstallOnLogin();
    // 2. Ensure Standalone App notification permission & Service Worker channel are active
    ensureStandaloneNotificationPermission()
      .then(() => {
        setPushPermission(getNotificationPermission());
        setPushEnabled(isWebPushEnabledByUser());
      })
      .catch(() => {});
  };

  // Countdown ticker & server status sync for brute-force lockout shield
  useEffect(() => {
    if (lockoutUntilTs <= Date.now()) {
      if (lockoutSecondsRemaining !== 0) setLockoutSecondsRemaining(0);
      return;
    }
    const updateRemaining = () => {
      const rem = Math.max(0, Math.ceil((lockoutUntilTs - Date.now()) / 1000));
      setLockoutSecondsRemaining(rem);
    };
    updateRemaining();
    const timer = setInterval(updateRemaining, 500);
    return () => clearInterval(timer);
  }, [lockoutUntilTs, lockoutSecondsRemaining]);

  useEffect(() => {
    let cancelled = false;
    fetch(`/api/auth/status?deviceId=${encodeURIComponent(deviceAuthId)}`)
      .then((r) => (r.ok ? r.json() : null))
      .then((data) => {
        if (cancelled || !data) return;
        if (data.locked && Number(data.lockoutSecondsRemaining) > 0) {
          const until = Date.now() + Number(data.lockoutSecondsRemaining) * 1000;
          setLockoutUntilTs(until);
          setLockoutSecondsRemaining(Number(data.lockoutSecondsRemaining));
          setFailedPinAttempts(Number(data.attempts) || 4);
        }
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [deviceAuthId]);

  const recordFailedPinGuess = (customMessage?: string) => {
    const now = Date.now();
    const nextAttempts = failedPinAttempts + 1;
    let cooldownSecs = 0;
    if (nextAttempts >= 8) {
      cooldownSecs = 600; // 10 minutes
    } else if (nextAttempts >= 6) {
      cooldownSecs = 120; // 2 minutes
    } else if (nextAttempts >= 4) {
      cooldownSecs = 30; // 30 seconds
    }
    const nextLockoutUntil = cooldownSecs > 0 ? now + cooldownSecs * 1000 : 0;
    setFailedPinAttempts(nextAttempts);
    if (nextLockoutUntil > 0) {
      setLockoutUntilTs(nextLockoutUntil);
      setLockoutSecondsRemaining(cooldownSecs);
    }
    try {
      localStorage.setItem(
        'jee_arena_pin_lockout_state',
        JSON.stringify({
          attempts: nextAttempts,
          lockoutUntil: nextLockoutUntil,
          lastAttemptAt: now
        })
      );
    } catch {}

    // Also report to server rate-limiter in background
    fetch('/api/auth/verify-pin', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        pin: '9999',
        category: tuitionVaultCategory,
        target: loginTarget,
        nameInput: signInNameInput,
        deviceId: deviceAuthId
      })
    }).catch(() => {});

    const triesLeft = Math.max(0, 4 - (nextAttempts % 4 === 0 ? 4 : nextAttempts % 4));
    if (cooldownSecs > 0) {
      setLoginError(`Security shield triggered after ${nextAttempts} failed tries. Keypad locked for ${cooldownSecs}s.`);
    } else {
      setLoginError(
        customMessage
          ? `${customMessage} (${triesLeft} ${triesLeft === 1 ? 'try' : 'tries'} left before security lock)`
          : `Incorrect 4-digit PIN (${triesLeft} ${triesLeft === 1 ? 'try' : 'tries'} left before security lock).`
      );
    }
  };

  const resetPinLockoutOnSuccess = (loggedInId: string) => {
    setFailedPinAttempts(0);
    setLockoutUntilTs(0);
    setLockoutSecondsRemaining(0);
    try {
      localStorage.removeItem('jee_arena_pin_lockout_state');
      sessionStorage.removeItem('jee_arena_manual_switch');
      if (loggedInId && loggedInId !== 'guest') {
        localStorage.setItem('jee_arena_trusted_device_member', loggedInId);
        localStorage.setItem('jee_arena_active_member_id', loggedInId);
        setRememberedDeviceMemberId(loggedInId);
      }
    } catch {}
  };

  const getPinStrengthIssue = (pin: string): string | undefined => {
    if (!pin || pin.length < 4) return undefined;
    const blockedWeakPins = new Set([
      '0000', '1111', '2222', '3333', '4444', '5555', '6666', '7777', '8888', '9999',
      '1234', '2345', '3456', '4567', '5678', '6789', '7890',
      '4321', '9876', '2580', '0852', '1212', '1010', '2020', '0619'
    ]);
    if (blockedWeakPins.has(pin)) {
      return 'Weak PIN detected: avoid repeating or sequential digits (like 1234 or 1111).';
    }
    if (/^(\d)\1{3}$/.test(pin)) {
      return 'All 4 digits cannot be identical.';
    }
    return undefined;
  };

  const pinStrengthHint = useMemo(() => getPinStrengthIssue(signUpPin), [signUpPin]);

  const verifyPinCode = (codeToVerify: string, target = loginTarget) => {
    if (lockoutUntilTs > Date.now() || lockoutSecondsRemaining > 0) {
      const rem = Math.max(1, Math.ceil((lockoutUntilTs - Date.now()) / 1000));
      setLoginError(`Security shield active. Please wait ${rem}s before trying again.`);
      setPinInput('');
      return false;
    }

    setLoginError('');
    setIsVerifyingPin(true);
    const trimmedName = signInNameInput.trim().toLowerCase();

    try {
      if (codeToVerify === ADMIN_PASSCODE) {
        setIsAdminUnlocked(true);
        localStorage.setItem('jee_arena_admin', 'true');
        if (tuitionVaultCategory === 'admin' || target === 'admin' || trimmedName === 'admin') {
          setActiveMemberId('admin');
          localStorage.setItem('jee_arena_active_id', 'admin');
          resetPinLockoutOnSuccess('admin');
          setActiveTab('admin');
        } else {
          const activeList = members.length > 0 ? members : DEFAULT_MEMBERS.filter(m => !m.isArchived);
          const matchedByName = trimmedName
            ? activeList.find(m => m.name.toLowerCase() === trimmedName || m.id.toLowerCase() === trimmedName)
            : null;
          if (trimmedName && !matchedByName && (trimmedName.includes('nishchit') || archivedMemberNamesSet.has(trimmedName))) {
            recordFailedPinGuess('Access Denied: Nishchit has been removed from the Arena.');
            setPinInput('');
            return false;
          }
          const resolvedId = matchedByName ? matchedByName.id : 'admin';
          setActiveMemberId(resolvedId);
          localStorage.setItem('jee_arena_active_id', resolvedId);
          resetPinLockoutOnSuccess(resolvedId);
          if (resolvedId !== 'admin') {
            setLogTargetMember(resolvedId);
            setExamMemberId(resolvedId);
            setActiveTab('arena');
          } else {
            setActiveTab('admin');
          }
        }
        setPinInput('');
        handlePostLoginMobileAndNotificationSetup();
        return true;
      }

      if (tuitionVaultCategory === 'admin' || target === 'admin') {
        recordFailedPinGuess('Invalid Administrator Passcode.');
        setPinInput('');
        return false;
      }

      if (tuitionVaultCategory === 'teachers' || target.startsWith('teacher_')) {
        const activeTeacherList = teachers.length > 0 ? teachers : DEFAULT_TEACHERS;
        const targetTeacher = trimmedName
          ? activeTeacherList.find(
              t =>
                (t.name.toLowerCase().includes(trimmedName) || t.id.toLowerCase() === trimmedName) &&
                String(t.passcode) === codeToVerify
            )
          : activeTeacherList.find(t => String(t.passcode) === codeToVerify || t.id === target);
        if (targetTeacher && (codeToVerify === String(targetTeacher.passcode) || codeToVerify === ADMIN_PASSCODE)) {
          setIsAdminUnlocked(false);
          setAdminPeekStandings(false);
          localStorage.removeItem('jee_arena_admin');
          setActiveMemberId(targetTeacher.id);
          setActiveTeacherId(targetTeacher.id);
          setSelectedTuitionSubject(targetTeacher.subject);
          localStorage.setItem('jee_arena_active_id', targetTeacher.id);
          localStorage.setItem('jee_arena_teacher_id', targetTeacher.id);
          resetPinLockoutOnSuccess(targetTeacher.id);
          setActiveTab('arena');
          setPinInput('');
          handlePostLoginMobileAndNotificationSetup();
          return true;
        }
        recordFailedPinGuess('Incorrect Faculty PIN.');
        setPinInput('');
        return false;
      }

      // Hard block removed/archived scholars (including Nishchit and his legacy PINs 2222 / 0619)
      if (
        archivedMemberIdsSet.has('nishchit') &&
        (trimmedName.includes('nishchit') ||
          target.toLowerCase().includes('nishchit') ||
          codeToVerify === '2222' ||
          codeToVerify === '0619')
      ) {
        recordFailedPinGuess('Access Denied: Nishchit has been removed from the Arena.');
        setPinInput('');
        return false;
      }

      const activeList = members.length > 0 ? members : DEFAULT_MEMBERS.filter(m => !m.isArchived);

      // Check if an archived scholar is attempting to sign in
      const archivedMatch = archivedMembers.find(
        m =>
          (trimmedName && (m.name.toLowerCase() === trimmedName || m.id.toLowerCase() === trimmedName)) ||
          (!trimmedName && String(m.passcode) === codeToVerify)
      );
      if (archivedMatch) {
        recordFailedPinGuess(`Access Denied: ${archivedMatch.name} has been removed from the Arena.`);
        setPinInput('');
        return false;
      }

      // If user typed their name, match by name + PIN
      if (trimmedName) {
        const targetMem = activeList.find(
          m => m.name.toLowerCase() === trimmedName || m.id.toLowerCase() === trimmedName
        );
        if (!targetMem) {
          recordFailedPinGuess(`No account found for "${signInNameInput.trim()}". Use Sign Up to request access.`);
          setPinInput('');
          return false;
        }
        if (targetMem.approvalStatus === 'pending') {
          setLoginError(`Account for "${targetMem.name}" is awaiting Admin approval.`);
          setPinInput('');
          return false;
        }
        if (targetMem.approvalStatus === 'rejected') {
          setLoginError(`Sign-up request for "${targetMem.name}" was declined by the Administrator.`);
          setPinInput('');
          return false;
        }
        if (codeToVerify === String(targetMem.passcode)) {
          setIsAdminUnlocked(false);
          setAdminPeekStandings(false);
          localStorage.removeItem('jee_arena_admin');
          setActiveMemberId(targetMem.id);
          localStorage.setItem('jee_arena_active_id', targetMem.id);
          resetPinLockoutOnSuccess(targetMem.id);
          setLogTargetMember(targetMem.id);
          setExamMemberId(targetMem.id);
          updateDailyStreak(targetMem);
          setActiveTab('arena');
          setPinInput('');
          setSignInNameInput('');
          handlePostLoginMobileAndNotificationSetup();
          return true;
        } else {
          recordFailedPinGuess('Incorrect 4-digit PIN.');
          setPinInput('');
          return false;
        }
      }

      // Otherwise match directly by 4-digit PIN
      const pinMatches = activeList.filter(m => String(m.passcode) === codeToVerify);
      if (pinMatches.length === 1) {
        const targetMem = pinMatches[0];
        if (targetMem.approvalStatus === 'pending') {
          setLoginError(`Account for "${targetMem.name}" is awaiting Admin approval.`);
          setPinInput('');
          return false;
        }
        if (targetMem.approvalStatus === 'rejected') {
          setLoginError(`Sign-up request for "${targetMem.name}" was declined by the Administrator.`);
          setPinInput('');
          return false;
        }
        setIsAdminUnlocked(false);
        setAdminPeekStandings(false);
        localStorage.removeItem('jee_arena_admin');
        setActiveMemberId(targetMem.id);
        localStorage.setItem('jee_arena_active_id', targetMem.id);
        resetPinLockoutOnSuccess(targetMem.id);
        setLogTargetMember(targetMem.id);
        setExamMemberId(targetMem.id);
        updateDailyStreak(targetMem);
        setActiveTab('arena');
        setPinInput('');
        handlePostLoginMobileAndNotificationSetup();
        return true;
      } else if (pinMatches.length > 1) {
        setLoginError('Multiple accounts share this PIN. Please enter your Name above.');
        setPinInput('');
        return false;
      }

      recordFailedPinGuess('Incorrect 4-digit PIN.');
      setPinInput('');
      return false;
    } finally {
      setIsVerifyingPin(false);
    }
  };

  const handlePinInputChange = (val: string) => {
    if (lockoutUntilTs > Date.now() || lockoutSecondsRemaining > 0) return;
    const clean = val.replace(/[^0-9]/g, '').slice(0, 4);
    setPinInput(clean);
    setLoginError('');
    if (clean.length === 4) {
      setTimeout(() => verifyPinCode(clean, loginTarget), 100);
    }
  };

  const handlePublicSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setSignUpError('');
    const cleanName = signUpName.trim();
    const cleanInst = signUpInstitute.trim() || 'Modulus';
    const cleanPin = signUpPin.replace(/[^0-9]/g, '');

    if (cleanName.length < 2) {
      setSignUpError('Please enter your name (at least 2 characters).');
      return;
    }
    if (cleanPin.length !== 4) {
      setSignUpError('Please set a 4-digit numeric PIN.');
      return;
    }

    const strengthIssue = getPinStrengthIssue(cleanPin);
    if (strengthIssue) {
      setSignUpError(strengthIssue);
      return;
    }

    if (
      cleanName.toLowerCase().includes('nishchit') ||
      archivedMemberNamesSet.has(cleanName.toLowerCase()) ||
      cleanPin === '2222' ||
      cleanPin === '0619'
    ) {
      setSignUpError('Access Denied: Nishchit has been removed from the Arena and cannot register.');
      return;
    }

    const activeList = members.length > 0 ? members : DEFAULT_MEMBERS.filter(m => !m.isArchived);
    const duplicate = activeList.find(m => m.name.toLowerCase() === cleanName.toLowerCase());
    if (duplicate) {
      if (duplicate.approvalStatus === 'pending') {
        setSignUpError(`"${cleanName}" already has a pending sign-up request awaiting Admin approval.`);
      } else {
        setSignUpError(`"${cleanName}" is already registered. Switch to Sign In to enter your PIN.`);
      }
      return;
    }

    setIsSigningUp(true);
    const basePath = `artifacts/${appId}/public/data`;
    const newId = cleanName.toLowerCase().replace(/[^a-z0-9]/g, '') + '_' + Date.now().toString().slice(-3);
    const today = getLocalDateString();

    const newMemberDoc: Member = {
      id: newId,
      name: cleanName,
      institute: cleanInst,
      passcode: cleanPin,
      bonusXp: 0,
      manualMinutesOffset: 0,
      isGrinding: false,
      grindingSubject: '',
      grindingStartedAt: null,
      grindingAccumulatedSeconds: 0,
      grindingLinkedTaskId: '',
      unexcusedZero: false,
      unexcusedReason: '',
      unexcusedAt: null,
      streakCount: 1,
      lastLoginDate: today,
      restTokens: 1,
      approvalStatus: 'pending',
      requestedAt: Date.now()
    };

    try {
      setMembers(prev => [...prev, newMemberDoc]);
      await setDoc(doc(db, basePath, 'members', newId), newMemberDoc);
      await pushActivity(
        'admin_adjust',
        `📝 ${cleanName} (${cleanInst}) requested to join the JEE Arena`,
        `Pending Admin approval & starting XP calibration`,
        newId,
        0
      );

      setSignUpPendingApprovalName(cleanName);
      setSignUpName('');
      setSignUpPin('');
      setSignUpError('');
      notify(
        `Sign-Up Request Sent to Admin!`,
        `${cleanName} (${cleanInst}) is now in the Admin approval queue. You can sign in once approved.`
      );
    } catch (err) {
      handleFirestoreError(err, OperationType.CREATE, `${basePath}/members/${newId}`);
      setSignUpError('Failed to submit sign-up request. Please try again.');
    } finally {
      setIsSigningUp(false);
    }
  };

  const handleAdminModalSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (lockoutUntilTs > Date.now() || lockoutSecondsRemaining > 0) {
      const rem = Math.max(1, Math.ceil((lockoutUntilTs - Date.now()) / 1000));
      setAdminModalError(`Too many attempts. Locked for ${rem}s.`);
      setAdminModalPin('');
      return;
    }
    setAdminModalError('');
    if (adminModalPin === ADMIN_PASSCODE) {
      setIsAdminUnlocked(true);
      localStorage.setItem('jee_arena_admin', 'true');
      resetPinLockoutOnSuccess(activeMemberId || 'admin');
      setShowAdminPassModal(false);
      setAdminModalPin('');
      setActiveTab('admin');
      notify('Admin Command Center Unlocked');
    } else {
      recordFailedPinGuess('Invalid Admin passcode.');
      const triesLeft = Math.max(0, 4 - ((failedPinAttempts + 1) % 4 === 0 ? 4 : (failedPinAttempts + 1) % 4));
      setAdminModalError(
        triesLeft > 0
          ? `Invalid passcode (${triesLeft} ${triesLeft === 1 ? 'try' : 'tries'} before security lock).`
          : `Too many failed attempts. Security lock activated.`
      );
      setAdminModalPin('');
    }
  };

  const handleLogout = () => {
    try {
      sessionStorage.setItem('jee_arena_manual_switch', 'true');
    } catch {}
    setActiveMemberId(null);
    setGuestDemoState(null);
    setShowGuestGuide(false);
    setIsAdminUnlocked(false);
    setAdminPeekStandings(false);
    setShowProfileMenu(false);
    setActiveTeacherId(null);
    localStorage.removeItem('jee_arena_active_id');
    localStorage.removeItem('jee_arena_admin');
    localStorage.removeItem('jee_arena_teacher_id');
    setActiveTab('arena');
    setReviewingAssignment(null);
    setReviewingStudentId(null);
    setActiveAssignmentAction(null);
    setPinInput('');
    setSignInNameInput('');
    setLoginError('');
    setSignUpError('');
  };

  const startOrResumeLiveTimer = async () => {
    const localClickTs = Date.now();
    const now = Math.max(localClickTs, getServerSyncedNow(), (lastStoppedTimerAtRef.current || 0) + 1);
    lastLocalTimerActionRef.current = localClickTs;
    const eng = timerEngineRef.current;
    if (eng.status === 'RUNNING') return;

    const bankedSeconds = Math.max(0, Math.floor(Number(eng.accumulatedSeconds) || 0));
    const startedAtFormatted =
      eng.startedAtStr || new Date(now).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    persistTimerEngineState({
      status: 'RUNNING',
      segmentStartedAt: now,
      accumulatedSeconds: bankedSeconds,
      startedAtStr: startedAtFormatted
    });

    // Activate Lock-Screen Stopwatch & OS Media Controls immediately on user gesture
    startLockScreenPresence(timerSubject, bankedSeconds);

    if (!isGuestMode) {
      localStorage.setItem('jee_arena_timer_subject', timerSubject);
      localStorage.setItem('jee_arena_timer_linked_task_id', timerLinkedTaskId);
    }

    if (keepScreenAwake) {
      requestScreenWakeLock().then(active => setWakeLockActive(active));
    }

    if (currentMember) {
      const nextPatch = {
        isGrinding: true,
        grindingSubject: timerSubject,
        grindingStartedAt: now,
        grindingAccumulatedSeconds: bankedSeconds,
        grindingLinkedTaskId: timerLinkedTaskId,
        grindingUpdatedAt: now
      };
      membersLiveRef.current = membersLiveRef.current.map(m =>
        m.id === currentMember.id ? { ...m, ...nextPatch } : m
      );
      setMembers(prev => prev.map(m => (m.id === currentMember.id ? { ...m, ...nextPatch } : m)));

      const basePath = `artifacts/${appId}/public/data`;
      const memRef = doc(db, basePath, 'members', currentMember.id);
      const isStealthActive = Boolean(currentMember.stealthUntil && currentMember.stealthUntil > now);
      try {
        if (!isGuestMode) {
          await updateDoc(memRef, nextPatch);
        }
        if (!isStealthActive && bankedSeconds === 0) {
          await pushActivity(
            'study_start',
            `🔥 ${currentMember.name} started studying ${timerSubject || 'JEE'}!`,
            `Live study stopwatch running on their ${currentMember.institute} desk.`,
            currentMember.id,
            0
          );
        }
      } catch (e) {
        console.warn('Update grinding state error:', e);
      }
    }
  };

  const pauseLiveTimer = async () => {
    const localClickTs = Date.now();
    const now = Math.max(localClickTs, getServerSyncedNow(), (lastStoppedTimerAtRef.current || 0) + 1);
    lastLocalTimerActionRef.current = localClickTs;
    const eng = timerEngineRef.current;
    if (eng.status !== 'RUNNING') return;

    const effectiveStart = eng.segmentStartedAt || now;
    const elapsedSegment = Math.max(0, Math.floor((now - effectiveStart) / 1000));
    const newBanked = Math.max(1, Math.floor(Number(eng.accumulatedSeconds) || 0) + elapsedSegment);

    persistTimerEngineState({
      status: 'PAUSED',
      segmentStartedAt: null,
      accumulatedSeconds: newBanked,
      startedAtStr: eng.startedAtStr
    });

    pauseLockScreenPresence(newBanked, timerSubject);
    releaseScreenWakeLock();
    setWakeLockActive(false);
    document.title = 'JEE Grind Arena (Paused)';

    if (currentMember) {
      const nextPatch = {
        isGrinding: false,
        grindingStartedAt: null,
        grindingAccumulatedSeconds: newBanked,
        grindingUpdatedAt: now
      };
      membersLiveRef.current = membersLiveRef.current.map(m =>
        m.id === currentMember.id ? { ...m, ...nextPatch } : m
      );
      setMembers(prev => prev.map(m => (m.id === currentMember.id ? { ...m, ...nextPatch } : m)));

      if (!isGuestMode) {
        const basePath = `artifacts/${appId}/public/data`;
        const memRef = doc(db, basePath, 'members', currentMember.id);
        try {
          await updateDoc(memRef, nextPatch);
        } catch (e) {
          console.warn('Update grinding state error:', e);
        }
      }
    }
  };

  const toggleLiveTimer = async () => {
    if (timerEngineRef.current.status === 'RUNNING') {
      await pauseLiveTimer();
    } else {
      await startOrResumeLiveTimer();
    }
  };

  const adjustLiveTimerSeconds = (deltaSeconds: number) => {
    const localClickTs = Date.now();
    const now = getServerSyncedNow();
    lastLocalTimerActionRef.current = localClickTs;
    const eng = timerEngineRef.current;
    const currentTotal = calculateCurrentTimerSeconds(
      eng.status === 'RUNNING',
      eng.segmentStartedAt,
      eng.accumulatedSeconds
    );
    const nextTotal = Math.max(0, currentTotal + deltaSeconds);

    if (eng.status === 'RUNNING') {
      persistTimerEngineState({
        status: 'RUNNING',
        segmentStartedAt: now,
        accumulatedSeconds: nextTotal,
        startedAtStr: eng.startedAtStr || new Date(now).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      });
      updateLockScreenTime(nextTotal, timerSubject);
      if (currentMember) {
        const nextPatch = {
          isGrinding: true,
          grindingStartedAt: now,
          grindingAccumulatedSeconds: nextTotal,
          grindingUpdatedAt: now
        };
        membersLiveRef.current = membersLiveRef.current.map(m =>
          m.id === currentMember.id ? { ...m, ...nextPatch } : m
        );
        setMembers(prev => prev.map(m => (m.id === currentMember.id ? { ...m, ...nextPatch } : m)));
        if (!isGuestMode) {
          const basePath = `artifacts/${appId}/public/data`;
          updateDoc(doc(db, basePath, 'members', currentMember.id), nextPatch).catch(() => {});
        }
      }
    } else if (nextTotal > 0) {
      persistTimerEngineState({
        status: 'PAUSED',
        segmentStartedAt: null,
        accumulatedSeconds: nextTotal,
        startedAtStr: eng.startedAtStr || new Date(now).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      });
      pauseLockScreenPresence(nextTotal, timerSubject);
      if (currentMember) {
        const nextPatch = {
          isGrinding: false,
          grindingStartedAt: null,
          grindingAccumulatedSeconds: nextTotal,
          grindingUpdatedAt: now
        };
        membersLiveRef.current = membersLiveRef.current.map(m =>
          m.id === currentMember.id ? { ...m, ...nextPatch } : m
        );
        setMembers(prev => prev.map(m => (m.id === currentMember.id ? { ...m, ...nextPatch } : m)));
        if (!isGuestMode) {
          const basePath = `artifacts/${appId}/public/data`;
          updateDoc(doc(db, basePath, 'members', currentMember.id), nextPatch).catch(() => {});
        }
      }
    } else {
      persistTimerEngineState({
        status: 'IDLE',
        segmentStartedAt: null,
        accumulatedSeconds: 0,
        startedAtStr: ''
      });
      stopLockScreenPresence();
      if (currentMember) {
        const nextPatch = {
          isGrinding: false,
          grindingStartedAt: null,
          grindingAccumulatedSeconds: 0,
          grindingUpdatedAt: now
        };
        membersLiveRef.current = membersLiveRef.current.map(m =>
          m.id === currentMember.id ? { ...m, ...nextPatch } : m
        );
        setMembers(prev => prev.map(m => (m.id === currentMember.id ? { ...m, ...nextPatch } : m)));
        if (!isGuestMode) {
          const basePath = `artifacts/${appId}/public/data`;
          updateDoc(doc(db, basePath, 'members', currentMember.id), nextPatch).catch(() => {});
        }
      }
    }
  };

  const recordTimerLap = () => {
    const eng = timerEngineRef.current;
    const totalNow = calculateCurrentTimerSeconds(
      eng.status === 'RUNNING',
      eng.segmentStartedAt,
      eng.accumulatedSeconds
    );
    if (totalNow <= 0) return;

    setTimerLaps(prev => {
      const lastTotal = prev.length > 0 ? prev[0].totalSeconds : 0;
      const splitSeconds = Math.max(1, totalNow - lastTotal);
      const nextLap = {
        id: `lap_${Date.now()}`,
        lapNumber: prev.length + 1,
        splitSeconds,
        totalSeconds: totalNow,
        subject: timerSubject,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
      };
      const updated = [nextLap, ...prev].slice(0, 25);
      if (!isGuestMode) {
        try {
          localStorage.setItem('jee_arena_timer_laps', JSON.stringify(updated));
        } catch (_e) {
          // Ignore storage error
        }
      }
      return updated;
    });
  };

  const resetLiveTimer = async () => {
    const now = recordTimerStoppedStamp(
      Math.max(
        Number(timerEngineRef.current?.segmentStartedAt) || 0,
        Number(currentMember?.grindingStartedAt) || 0,
        Number(currentMember?.grindingUpdatedAt) || 0
      )
    );
    persistTimerEngineState({
      status: 'IDLE',
      segmentStartedAt: null,
      accumulatedSeconds: 0,
      startedAtStr: ''
    });
    setTimerSeconds(0);
    setTimerLaps([]);
    resetTimerMilestones();
    stopLockScreenPresence();
    releaseScreenWakeLock();
    setWakeLockActive(false);
    document.title = 'JEE Grind Arena';

    if (!isGuestMode) {
      localStorage.removeItem('jee_arena_timer_laps');
      localStorage.removeItem('jee_arena_timer_linked_task_id');
    }

    if (arenaSettings.combinedStudyRoom?.sharedBlockStartedAt || (arenaSettings.combinedStudyRoom?.selectedMemberIds?.length || 0) > 0) {
      handleUpdateCombinedStudyRoom({
        sharedBlockStartedAt: null,
        sharedTimerStatus: 'IDLE',
        sharedAccumulatedSeconds: 0,
        selectedMemberIds: []
      }).catch(() => {});
    }

    if (currentMember) {
      const nextPatch = {
        isGrinding: false,
        grindingSubject: '',
        grindingStartedAt: null,
        grindingAccumulatedSeconds: 0,
        grindingLinkedTaskId: '',
        grindingUpdatedAt: now
      };
      membersLiveRef.current = membersLiveRef.current.map(m =>
        m.id === currentMember.id ? { ...m, ...nextPatch } : m
      );
      setMembers(prev => prev.map(m => (m.id === currentMember.id ? { ...m, ...nextPatch } : m)));

      if (!isGuestMode) {
        const basePath = `artifacts/${appId}/public/data`;
        try {
          await updateDoc(doc(db, basePath, 'members', currentMember.id), nextPatch);
        } catch (e) {
          console.warn('Reset grinding state error:', e);
        }
      }
    }
  };

  const finishLiveTimerAndOpenLogger = async () => {
    const eng = timerEngineRef.current;
    const finalSeconds = calculateCurrentTimerSeconds(
      eng.status === 'RUNNING',
      eng.segmentStartedAt,
      eng.accumulatedSeconds
    );
    const mins = Math.max(1, Math.round(finalSeconds / 60));
    const now = recordTimerStoppedStamp(
      Math.max(
        Number(eng.segmentStartedAt) || 0,
        Number(currentMember?.grindingStartedAt) || 0,
        Number(currentMember?.grindingUpdatedAt) || 0
      )
    );

    persistTimerEngineState({
      status: 'IDLE',
      segmentStartedAt: null,
      accumulatedSeconds: 0,
      startedAtStr: ''
    });
    setTimerSeconds(0);
    setTimerLaps([]);
    resetTimerMilestones();
    stopLockScreenPresence();
    releaseScreenWakeLock();
    setWakeLockActive(false);
    document.title = 'JEE Grind Arena';

    if (!isGuestMode) {
      localStorage.removeItem('jee_arena_timer_laps');
    }

    const isCurrentInRoom = Boolean(
      currentMember &&
      Array.isArray(arenaSettings.combinedStudyRoom?.selectedMemberIds) &&
      arenaSettings.combinedStudyRoom.selectedMemberIds.includes(currentMember.id)
    );
    if (isCurrentInRoom && (arenaSettings.combinedStudyRoom?.sharedBlockStartedAt || (arenaSettings.combinedStudyRoom?.selectedMemberIds?.length || 0) > 0)) {
      handleUpdateCombinedStudyRoom({
        sharedBlockStartedAt: null,
        sharedTimerStatus: 'IDLE',
        sharedAccumulatedSeconds: 0,
        selectedMemberIds: []
      }).catch(() => {});
    }

    // Immediately populate and open the Session Logger modal before network roundtrips
    if (!savingSessionLockRef.current) setIsSavingSession(false);
    setLogSessionType('STUDY');
    setLogInputMethod('DURATION_ONLY');
    setLogSubject(timerSubject);
    setLogDate(getLocalDateString());
    setLogDuration(String(mins));
    setLogQuestions('');
    setLogAttemptedQuestions('');
    setLogQuestionsByTier({ easy: '', mains: '', hard: '', adv: '' });
    setLogAttemptedByTier({ easy: '', mains: '', hard: '', adv: '' });
    setLogLinkedTaskIds(timerLinkedTaskId ? [timerLinkedTaskId] : []);
    setLogTargetMember(currentMember ? currentMember.id : (members[0]?.id || 'sai'));
    setShowLogModal(true);

    if (currentMember) {
      const basePath = `artifacts/${appId}/public/data`;
      // Detonate armed Sound Horn on timer completion!
      const hornArmed = Boolean(currentMember.soundHornPending);
      if (hornArmed) {
        playObnoxiousAirhorn();
        notify(
          `📯 AIRHORN DETONATED BY ${(currentMember.soundHornBy || 'A RIVAL').toUpperCase()}!`,
          'You just got blasted by an XP Shop Sound Horn trap on timer completion!',
          'error'
        );
      }
      const nextPatch = {
        isGrinding: false,
        grindingSubject: '',
        grindingStartedAt: null,
        grindingAccumulatedSeconds: 0,
        grindingLinkedTaskId: '',
        grindingUpdatedAt: now,
        ...(hornArmed ? { soundHornPending: false, soundHornBy: null } : {})
      };
      membersLiveRef.current = membersLiveRef.current.map(m =>
        m.id === currentMember.id ? { ...m, ...nextPatch } : m
      );
      setMembers(prev => prev.map(m => (m.id === currentMember.id ? { ...m, ...nextPatch } : m)));

      if (!isGuestMode) {
        updateDoc(doc(db, basePath, 'members', currentMember.id), nextPatch).catch((e) => {
          console.warn('Clear grinding state error:', e);
        });
      }
    }
  };

  const handleUpdateCombinedStudyRoom = async (nextPartial: Partial<CombinedStudyRoomState>) => {
    const basePath = `artifacts/${appId}/public/data`;
    const currentRoom: CombinedStudyRoomState = arenaSettings.combinedStudyRoom || {
      active: true,
      roomTitle: 'Squad Combined Focus Lounge',
      mode: 'POMODORO_50',
      sharedBlockStartedAt: null,
      sharedBlockDurationMins: 50,
      participantGoals: {},
      recentPings: []
    };
    const updatedRoom: CombinedStudyRoomState = {
      ...currentRoom,
      ...nextPartial
    };
    setArenaSettings(prev => ({
      ...prev,
      combinedStudyRoom: updatedRoom
    }));
    if (!isGuestMode) {
      try {
        await setDoc(
          doc(db, basePath, 'settings', 'arenaState'),
          { combinedStudyRoom: updatedRoom },
          { merge: true }
        );
      } catch (e) {
        console.warn('Update combined study room error:', e);
      }
    }
  };

  const handleBroadcastCombinedStudyInvite = async (roomTitle: string, modeLabel: string) => {
    const callerName = currentMember?.name || 'A Scholar';
    notify(
      '🔔 Squad Summoned to Combined Study!',
      `${callerName} invited everyone to join "${roomTitle}" (${modeLabel}).`
    );
    await pushActivity(
      'session_log',
      `🤝 ${callerName} opened the Combined Study & Challenge Hub (${modeLabel})`,
      `Click "Study Together" in the top bar to join the shared timer, log your own subject/questions, or throw a live challenge!`,
      currentMember?.id || 'sai',
      0
    );
  };

  const handleSaveCombinedMultiSession = async (payload: CombinedSessionSettlementPayload) => {
    if (savingSessionLockRef.current) return;
    if (!payload.participants || payload.participants.length === 0) return;

    const basePath = `artifacts/${appId}/public/data`;
    const durationMins = Math.max(1, Math.round(Number(payload.durationMins) || 1));
    const nowSessionMs = Math.max(Date.now(), getServerSyncedNow(), (Number(arenaSettings.currentCycleStartMs) || 0) + 1000);

    // Prevent accidental rapid duplicate logs within 6 seconds
    const participantKey = payload.participants.map(p => `${p.memberId}:${p.subject}:${p.solvedQuestions}:${p.attemptedQuestions}`).join('|');
    const sessionFingerprint = `combined_${durationMins}_${participantKey}`;
    if (
      lastSavedSessionFingerprintRef.current.key === sessionFingerprint &&
      nowSessionMs - lastSavedSessionFingerprintRef.current.ts < 6000
    ) {
      setShowCombinedStudyModal(false);
      setShowLogModal(false);
      return;
    }

    savingSessionLockRef.current = true;
    setIsSavingSession(true);
    lastSavedSessionFingerprintRef.current = { key: sessionFingerprint, ts: nowSessionMs };

    try {
      const dateStr = getLocalDateString();
      const scholarNames = payload.participants.map(p => p.memberName);
      const winnerId = payload.challenge.enabled ? payload.challenge.winnerMemberId : null;
      const winnerParticipant = winnerId ? payload.participants.find(p => p.memberId === winnerId) : null;

      const createdSessions: Array<{
        id: string;
        docRef: ReturnType<typeof doc> | null;
        raw: any;
        targetMem: Member;
        overclockMult: number;
      }> = [];
      let totalRaidDamage = 0;
      let primaryUserXp = 0;
      let primaryUserQuestions = 0;

      for (let idx = 0; idx < payload.participants.length; idx++) {
        const p = payload.participants[idx];
        const targetMem =
          membersLiveRef.current.find(m => m.id === p.memberId) ||
          members.find(m => m.id === p.memberId) ||
          (!isGuestMode ? DEFAULT_MEMBERS.find(m => m.id === p.memberId) : undefined);
        if (!targetMem) continue;

        const solvedCount = Math.max(0, Number(p.solvedQuestions) || 0);
        const attemptedCount = Math.max(0, Number(p.attemptedQuestions) || 0);
        const totalQ = solvedCount + attemptedCount;
        const solveRate = totalQ > 0 ? Math.round((solvedCount / totalQ) * 100) : 100;

        const baseSessionXp = calcSessionXp(durationMins, solvedCount, p.difficulty, 'STUDY', attemptedCount);
        const qDetail = calcQuestionsDetail(solvedCount, attemptedCount, p.difficulty);

        const memberStat = leaderboardStats.find(m => m.id === targetMem.id);
        const hasUnderdogBuff = Boolean(memberStat?.isUnderdogBuffActive);
        const liveTargetMem = membersLiveRef.current.find(m => m.id === targetMem.id) || targetMem;
        const overclockMult = Math.max(
          Number((liveTargetMem as any)?.nextSessionMultiplier) || 1,
          Number((targetMem as any)?.nextSessionMultiplier) || 1
        );
        const hasActiveHostagePact = (arenaSettings.hostagePacts || []).some(
          pact =>
            pact.status === 'active' &&
            ((pact.partnerAId || pact.memberAId) === targetMem.id ||
              (pact.partnerBId || pact.memberBId) === targetMem.id)
        );
        const bloodPactMult = hasActiveHostagePact ? 1.5 : 1;
        const combinedMult = (hasUnderdogBuff ? 1.25 : 1) * (overclockMult > 1 ? overclockMult : 1) * bloodPactMult;

        let challengeDeltaXp = 0;
        if (payload.challenge.enabled && winnerId) {
          if (p.memberId === winnerId) {
            challengeDeltaXp = payload.challenge.wagerMode
              ? payload.challenge.bonusXp * Math.max(1, payload.participants.length - 1)
              : payload.challenge.bonusXp;
          } else if (payload.challenge.wagerMode) {
            challengeDeltaXp = -payload.challenge.bonusXp;
          }
        }

        const finalXpEarned = Math.max(0, Math.round(baseSessionXp * combinedMult) + challengeDeltaXp);
        const coScholars = scholarNames.filter(n => n !== targetMem.name);
        const challengeTag =
          payload.challenge.enabled && winnerId
            ? p.memberId === winnerId
              ? ` • 🏆 Won "${payload.challenge.title}" (+${challengeDeltaXp} XP)`
              : payload.challenge.wagerMode
                ? ` • ⚔️ Lost Wager (-${payload.challenge.bonusXp} XP to ${winnerParticipant?.memberName || 'Winner'})`
                : ` • ⚔️ Challenge w/ ${winnerParticipant?.memberName || 'Squad'}`
            : '';
        const combinedPrefix =
          coScholars.length > 0
            ? `[🤝 Combined Study w/ ${coScholars.join(', ')}${challengeTag}]`
            : `[🤝 Combined Study${challengeTag}]`;

        const combinedNotes = p.notes ? `${combinedPrefix} ${p.notes}` : combinedPrefix;
        const isStealthActive = Boolean(targetMem.stealthUntil && targetMem.stealthUntil > nowSessionMs);
        const stealthHideUntilMs = isStealthActive ? targetMem.stealthUntil! : 0;

        const newSession = {
          memberId: targetMem.id,
          memberName: targetMem.name,
          sessionType: 'STUDY' as const,
          inputMethod: 'DURATION_ONLY' as const,
          subject: p.subject,
          date: dateStr,
          duration: durationMins,
          startTime: '',
          endTime: '',
          questions: totalQ,
          solvedQuestions: solvedCount,
          attemptedQuestions: attemptedCount,
          solveRate,
          difficulty: p.difficulty,
          difficultyBreakdown: solvedCount > 0 ? { [p.difficulty]: solvedCount } : {},
          attemptedBreakdown: attemptedCount > 0 ? { [p.difficulty]: attemptedCount } : {},
          questionXp: qDetail.totalQuestionXp,
          linkedTaskIds: [],
          tasksBonusXp: Math.max(0, challengeDeltaXp),
          notes: combinedNotes,
          xpEarned: finalXpEarned,
          underdogBoosted: hasUnderdogBuff,
          overclockBoosted: overclockMult > 1,
          overclockMultiplier: overclockMult > 1 ? overclockMult : 1,
          bloodPactBoosted: bloodPactMult > 1,
          stealthLogged: isStealthActive,
          stealthHideUntil: stealthHideUntilMs,
          timestamp: nowSessionMs + idx
        };

        const sessionDocRef = !isGuestMode ? doc(collection(db, basePath, 'sessions')) : null;
        const sessionDocId = sessionDocRef ? sessionDocRef.id : `demo_${nowSessionMs}_${idx}`;
        createdSessions.push({ id: sessionDocId, docRef: sessionDocRef, raw: newSession, targetMem, overclockMult });
        totalRaidDamage += Math.max(1, durationMins + totalQ * 3);

        if (targetMem.id === currentMember?.id || idx === 0) {
          primaryUserXp = finalXpEarned;
          primaryUserQuestions = totalQ;
        }
      }

      if (createdSessions.length === 0) {
        notify('Select Scholars', 'No valid scholar profile found to log combined session.', 'error');
        return;
      }

      const combinedStopStamp = recordTimerStoppedStamp(
        Math.max(
          Number(timerEngineRef.current?.segmentStartedAt) || 0,
          Number(currentMember?.grindingStartedAt) || 0,
          Number(currentMember?.grindingUpdatedAt) || 0
        )
      );

      if (!isGuestMode) {
        for (const item of createdSessions) {
          const memberAfterSessionUpdates = {
            isGrinding: false,
            grindingSubject: '',
            grindingStartedAt: null,
            grindingAccumulatedSeconds: 0,
            grindingLinkedTaskId: '',
            grindingUpdatedAt: combinedStopStamp,
            ...(item.overclockMult > 1 ? { nextSessionMultiplier: null } : {})
          };
          await setDoc(item.docRef!, item.raw);
          await updateDoc(doc(db, basePath, 'members', item.targetMem.id), memberAfterSessionUpdates);
        }
      }

      setShowCombinedStudyModal(false);
      setShowLogModal(false);

      persistTimerEngineState({
        status: 'IDLE',
        segmentStartedAt: null,
        accumulatedSeconds: 0,
        startedAtStr: ''
      });
      setTimerRunning(false);
      setTimerStartTime(null);
      setTimerAccumulatedSeconds(0);
      setTimerSeconds(0);
      setTimerLaps([]);
      setTimerLinkedTaskId('');
      setTimerStartedAtStr('');
      resetTimerMilestones();
      if (!isGuestMode) {
        localStorage.removeItem('jee_arena_timer_running');
        localStorage.removeItem('jee_arena_timer_start_time');
        localStorage.removeItem('jee_arena_timer_accumulated_secs');
        localStorage.removeItem('jee_arena_timer_linked_task_id');
        localStorage.removeItem('jee_arena_timer_started_at_str');
        localStorage.removeItem('jee_arena_timer_laps');
      }
      stopLockScreenPresence();
      releaseScreenWakeLock();
      setWakeLockActive(false);
      document.title = 'JEE Grind Arena';

      const participantIdsSet = new Set(createdSessions.map(c => c.targetMem.id));
      const memberTimerClear = {
        isGrinding: false,
        grindingSubject: '',
        grindingStartedAt: null,
        grindingAccumulatedSeconds: 0,
        grindingLinkedTaskId: '',
        grindingUpdatedAt: combinedStopStamp
      };
      membersLiveRef.current = membersLiveRef.current.map(m =>
        participantIdsSet.has(m.id) ? { ...m, ...memberTimerClear } : m
      );
      setMembers(prev =>
        prev.map(m =>
          participantIdsSet.has(m.id) ? { ...m, ...memberTimerClear } : m
        )
      );

      if (arenaSettings.combinedStudyRoom?.sharedBlockStartedAt || (arenaSettings.combinedStudyRoom?.selectedMemberIds?.length || 0) > 0) {
        handleUpdateCombinedStudyRoom({
          sharedBlockStartedAt: null,
          sharedTimerStatus: 'IDLE',
          sharedAccumulatedSeconds: 0,
          selectedMemberIds: []
        }).catch(() => {});
      }

      const savedObjects = createdSessions.map(item => ({ id: item.id, ...item.raw }));
      setSessions(prev => {
        const existingIds = new Set(prev.map(s => s.id));
        const toAdd = savedObjects.filter(s => !existingIds.has(s.id));
        return toAdd.length > 0 ? [...toAdd, ...prev] : prev;
      });

      playArpeggioUp();
      const squadSummaryLabel = scholarNames.join(' & ');
      notify(
        winnerParticipant
          ? `🏆 Combined Study Logged • ${winnerParticipant.memberName} Won the Challenge!`
          : `🤝 Combined Study Logged (${squadSummaryLabel})`,
        `${createdSessions.length} scholars logged ${durationMins}m together! ${
          winnerParticipant
            ? `${winnerParticipant.memberName} claimed +${
                payload.challenge.wagerMode
                  ? payload.challenge.bonusXp * Math.max(1, payload.participants.length - 1)
                  : payload.challenge.bonusXp
              } Challenge XP!`
            : `-${totalRaidDamage} Boss DMG dealt!`
        }`
      );

      setStudyLogSuccessData({
        memberName: squadSummaryLabel,
        xpEarned: primaryUserXp,
        durationMins,
        totalQCount: primaryUserQuestions,
        tasksCount: payload.challenge.enabled && winnerParticipant ? 1 : 0,
        streakCount: currentMember ? computeMemberStreak(currentMember, [...savedObjects, ...sessions]) : 0
      });

      for (const item of createdSessions) {
        await updateDailyStreak(item.targetMem, [{ id: item.id, ...item.raw }]);
      }

      if (arenaSettings.raidEnabled && totalRaidDamage > 0) {
        const nextBossHp = Math.max(0, (Number(arenaSettings.raidBossCurrentHp) || 0) - totalRaidDamage);
        const raidPatch = {
          raidBossCurrentHp: nextBossHp,
          lastRaidDamageHit: {
            attackerName: squadSummaryLabel,
            damage: totalRaidDamage,
            timestamp: Date.now()
          }
        };
        if (isGuestMode) {
          setArenaSettings(prev => ({ ...prev, ...raidPatch }));
        } else {
          await setDoc(doc(db, basePath, 'settings', 'arenaState'), raidPatch, { merge: true }).catch(() => {});
        }
      }

      const perScholarDetails = payload.participants
        .map(p => `${p.memberName}: ${p.subject} (${p.solvedQuestions} solved / ${p.attemptedQuestions} att)`)
        .join(' • ');
      const challengeSummary =
        payload.challenge.enabled && winnerParticipant
          ? ` • 🏆 ${winnerParticipant.memberName} won "${payload.challenge.title}" (+${
              payload.challenge.wagerMode
                ? payload.challenge.bonusXp * Math.max(1, payload.participants.length - 1)
                : payload.challenge.bonusXp
            } XP)`
          : '';

      await pushActivity(
        'session_log',
        `🤝 Combined Study (${durationMins}m): ${squadSummaryLabel}${challengeSummary}`,
        `${perScholarDetails} • -${totalRaidDamage} Boss DMG`,
        currentMember?.id || payload.participants[0].memberId,
        primaryUserXp
      );
    } catch (err) {
      lastSavedSessionFingerprintRef.current = { key: '', ts: 0 };
      handleFirestoreError(err, OperationType.CREATE, `${basePath}/sessions`);
      notify(
        'Failed to Log Combined Session',
        err instanceof Error ? err.message : 'Unable to save combined session. Please try again.',
        'error'
      );
    } finally {
      savingSessionLockRef.current = false;
      setIsSavingSession(false);
    }
  };

  const isMemberOnlineNow = (m: Member): boolean => {
    if (!m) return false;
    if (m.id === currentMember?.id) return true;
    const isGrindingVisible = Boolean(m.isGrinding && !(m.stealthUntil && m.stealthUntil > Date.now()));
    if (isGrindingVisible) return true;
    if (m.lastActiveAt && Date.now() - m.lastActiveAt < 3 * 60 * 1000) return true;
    return false;
  };

  const combinedStudyMembers = useMemo(() => {
    return members.map(m => ({
      id: m.id,
      name: m.name,
      institute: m.institute,
      isGrinding: Boolean(m.isGrinding && !(m.stealthUntil && m.stealthUntil > Date.now())),
      grindingSubject: m.grindingSubject || 'Physics',
      grindingStartedAt: m.grindingStartedAt || null,
      grindingAccumulatedSeconds: Number(m.grindingAccumulatedSeconds) || 0,
      isOnline: isMemberOnlineNow(m),
      lastActiveAt: m.lastActiveAt || null
    }));
  }, [members, currentMember?.id]);

  const handleSendCombinedStudyInvite = async (
    targetMemberId: string,
    durationMins: number,
    subject: string,
    challenge: { enabled: boolean; title: string; bonusXp: number }
  ) => {
    if (!currentMember) return;
    const target = members.find(m => m.id === targetMemberId);
    if (!target) return;

    if (!isMemberOnlineNow(target)) {
      notify('Target Offline', `${target.name} is currently offline and cannot receive study invites right now.`);
      return;
    }

    const currentRoom: CombinedStudyRoomState = arenaSettings.combinedStudyRoom || {
      active: true,
      roomTitle: 'Squad Combined Focus Lounge',
      mode: 'POMODORO_50',
      sharedBlockStartedAt: null,
      sharedBlockDurationMins: 50,
      participantGoals: {},
      recentPings: []
    };

    const newInvite: CombinedStudyInvite = {
      id: `cs_invite_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
      fromMemberId: currentMember.id,
      fromMemberName: currentMember.name,
      fromInstitute: currentMember.institute,
      targetMemberId: target.id,
      targetMemberName: target.name,
      roomTitle: currentRoom.roomTitle || `${currentMember.name} and ${target.name} Study Sprint`,
      mode: currentRoom.mode || 'POMODORO_50',
      durationMins: durationMins || currentRoom.sharedBlockDurationMins || 50,
      subject: subject || 'Physics',
      challengeEnabled: Boolean(challenge?.enabled),
      challengeTitle: challenge?.title || 'Study Sprint Challenge',
      challengeBonusXp: challenge?.bonusXp || 25,
      status: 'pending',
      createdAt: Date.now()
    };

    const existingInvites = (currentRoom.invites || []).filter(
      inv => inv.status === 'pending' && Date.now() - inv.createdAt < 15 * 60 * 1000
    );

    const updatedInvites = [...existingInvites, newInvite];
    await handleUpdateCombinedStudyRoom({ invites: updatedInvites });

    notify(
      'Study Request Sent',
      `Synchronized study invite dispatched to ${target.name}. Waiting for them to accept!`
    );

    await pushActivity(
      'session_log',
      `🤝 ${currentMember.name} invited ${target.name} to Combined Study (${newInvite.durationMins}m)`,
      `Shared timer will synchronize hardware clocks as soon as ${target.name} accepts.`,
      currentMember.id,
      0
    );
  };

  const handleCancelCombinedStudyInvite = async (inviteId: string) => {
    const currentRoom = arenaSettings.combinedStudyRoom;
    if (!currentRoom) return;
    const updatedInvites = (currentRoom.invites || []).map(inv =>
      inv.id === inviteId ? { ...inv, status: 'cancelled' as const } : inv
    );
    await handleUpdateCombinedStudyRoom({ invites: updatedInvites });
    notify('Invite Cancelled', 'Study session invitation was cancelled.');
  };

  const handleDeclineCombinedStudyInvite = async (inviteId: string) => {
    const currentRoom = arenaSettings.combinedStudyRoom;
    if (!currentRoom) return;
    const targetInvite = (currentRoom.invites || []).find(inv => inv.id === inviteId);
    const updatedInvites = (currentRoom.invites || []).map(inv =>
      inv.id === inviteId ? { ...inv, status: 'declined' as const } : inv
    );
    await handleUpdateCombinedStudyRoom({ invites: updatedInvites });
    if (targetInvite && currentMember) {
      await pushActivity(
        'session_log',
        `👋 ${currentMember.name} was unable to join ${targetInvite.fromMemberName}'s study invite right now`,
        'Busy with solo study or active tasks.',
        currentMember.id,
        0
      );
    }
  };

  const executeAcceptCombinedStudyInvite = async (invite: CombinedStudyInvite) => {
    if (!currentMember) return;
    const currentRoom: CombinedStudyRoomState = arenaSettings.combinedStudyRoom || {
      active: true,
      roomTitle: 'Squad Combined Focus Lounge',
      mode: 'POMODORO_50',
      sharedBlockStartedAt: null,
      sharedBlockDurationMins: 50,
      participantGoals: {},
      recentPings: []
    };

    const syncedStartedAt = getServerSyncedNow();
    const updatedInvites = (currentRoom.invites || []).map(inv =>
      inv.id === invite.id
        ? { ...inv, status: 'accepted' as const, sharedStartedAt: syncedStartedAt }
        : inv
    );

    const activeExistingIds =
      currentRoom.sharedTimerStatus === 'RUNNING' &&
      currentRoom.sharedBlockStartedAt &&
      currentRoom.sharedBlockStartedAt !== 1793539644377
        ? currentRoom.selectedMemberIds || []
        : [];
    const mergedSelectedMembers = Array.from(
      new Set([...activeExistingIds, invite.fromMemberId, currentMember.id])
    );

    await handleUpdateCombinedStudyRoom({
      active: true,
      roomTitle: invite.roomTitle || `${invite.fromMemberName} and ${currentMember.name} Study Sprint`,
      mode: invite.mode || 'POMODORO_50',
      sharedBlockStartedAt: syncedStartedAt,
      sharedBlockDurationMins: invite.durationMins || 50,
      sharedTimerStatus: 'RUNNING',
      selectedMemberIds: mergedSelectedMembers,
      invites: updatedInvites,
      challengeEnabled: Boolean(invite.challengeEnabled),
      challengeTitle: invite.challengeTitle || 'Study Sprint Challenge',
      challengeBonusXp: invite.challengeBonusXp || 25
    });

    // Synchronize hardware local timer AND Firestore member grinding state with the accepted session
    const subj = invite.subject || 'Physics';
    lastLocalTimerActionRef.current = Date.now();
    lastAcceptedSyncedStartRef.current = syncedStartedAt;
    setTimerSubject(subj);
    if (!isGuestMode) {
      localStorage.setItem('jee_arena_timer_subject', subj);
    }
    persistTimerEngineState({
      status: 'RUNNING',
      segmentStartedAt: syncedStartedAt,
      accumulatedSeconds: 0,
      startedAtStr: new Date(syncedStartedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    startLockScreenPresence(subj, 0);

    const basePath = `artifacts/${appId}/public/data`;
    const myPatch = {
      isGrinding: true,
      grindingSubject: subj,
      grindingStartedAt: syncedStartedAt,
      grindingAccumulatedSeconds: 0,
      grindingUpdatedAt: syncedStartedAt
    };
    const hostPatch = {
      isGrinding: true,
      grindingStartedAt: syncedStartedAt,
      grindingAccumulatedSeconds: 0,
      grindingUpdatedAt: syncedStartedAt
    };
    setMembers(prev =>
      prev.map(m =>
        m.id === currentMember.id
          ? { ...m, ...myPatch }
          : m.id === invite.fromMemberId
          ? { ...m, ...hostPatch }
          : m
      )
    );
    if (!isGuestMode) {
      updateDoc(doc(db, basePath, 'members', currentMember.id), myPatch).catch(() => {});
      updateDoc(doc(db, basePath, 'members', invite.fromMemberId), hostPatch).catch(() => {});
    }

    setShowCombinedStudyModal(true);
    setIsCombinedStudyMinimized(false);
    setUnsavedTimerInvitePrompt(null);

    notify(
      'Study Invite Accepted',
      `Synchronized timer started with ${invite.fromMemberName}! Both devices are now locked in.`
    );

    await pushActivity(
      'session_log',
      `🤝 ${currentMember.name} accepted ${invite.fromMemberName}'s study invite!`,
      `Both devices synchronized for a ${invite.durationMins}m focus sprint in ${invite.subject}.`,
      currentMember.id,
      0
    );
  };

  // Register OS Lock-Screen Stopwatch & Media Controls (Play/Resume, Pause, Stop/Settle, Next Track = Lap, Seek +/-1m)
  useEffect(() => {
    registerLockScreenCallbacks({
      onPlay: () => {
        startOrResumeLiveTimer();
      },
      onPause: () => {
        pauseLiveTimer();
      },
      onStop: () => {
        finishLiveTimerAndOpenLogger();
      },
      onLap: () => {
        recordTimerLap();
      },
      onSeekDelta: (deltaSecs) => {
        adjustLiveTimerSeconds(deltaSecs);
      }
    });
  });

  // Handle QR-Code Instant Pairing URL ("?joinStudyRoom=...") when scanned by phone camera
  useEffect(() => {
    if (typeof window === 'undefined' || isGuestMode) return;
    const params = new URLSearchParams(window.location.search);
    const joinCode = params.get('joinStudyRoom');
    if (!joinCode || !currentMember) return;

    const hostId = params.get('hostId') || 'sai';
    const startTsParam = Number(params.get('startTs')) || getServerSyncedNow();
    const durParam = Number(params.get('dur')) || 50;

    // Clean URL parameter so refreshing doesn't re-trigger
    const cleanUrl = window.location.pathname + window.location.hash;
    window.history.replaceState({}, document.title, cleanUrl);

    const syncedStart = startTsParam > 0 ? startTsParam : getServerSyncedNow();
    lastLocalTimerActionRef.current = Date.now();
    lastAcceptedSyncedStartRef.current = syncedStart;

    persistTimerEngineState({
      status: 'RUNNING',
      segmentStartedAt: syncedStart,
      accumulatedSeconds: 0,
      startedAtStr: new Date(syncedStart).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    startLockScreenPresence(timerSubject, calculateCurrentTimerSeconds(true, syncedStart, 0));

    const mergedIds = Array.from(new Set([hostId, currentMember.id]));
    handleUpdateCombinedStudyRoom({
      active: true,
      pairingCode: joinCode,
      selectedMemberIds: mergedIds,
      sharedBlockStartedAt: syncedStart,
      sharedBlockDurationMins: durParam,
      sharedTimerStatus: 'RUNNING'
    }).catch(() => {});

    sendWebRTCSignal({
      type: 'qr_instant_join',
      fromId: currentMember.id,
      fromName: currentMember.name,
      memberId: currentMember.id,
      pairingCode: joinCode,
      sharedStartedAt: syncedStart
    }).catch(() => {});

    setShowCombinedStudyModal(true);
    setIsCombinedStudyMinimized(false);
    playArpeggioUp();
    notify('📲 QR Study Room Paired!', `Your timer is now locked in with Room ${joinCode}!`);
  }, [currentMember?.id]);

  const handleAcceptCombinedStudyInvite = async (invite: CombinedStudyInvite) => {
    if (!currentMember) return;
    const hasUnsavedWork = timerRunning || timerSeconds >= 45 || Boolean(currentMember.isGrinding);
    if (hasUnsavedWork) {
      setUnsavedTimerInvitePrompt(invite);
      return;
    }
    await executeAcceptCombinedStudyInvite(invite);
  };

  const handleQuickParserChange = (val: string) => {
    setLogQuickParser(val);
    const parsed = parseQuickTimeRange(val);
    if (parsed) {
      setLogStartTime(parsed.startTime);
      setLogEndTime(parsed.endTime);
      setLogDuration(String(parsed.duration));
    }
  };

  const handleStartEndChange = (newStart: string, newEnd: string) => {
    setLogStartTime(newStart);
    setLogEndTime(newEnd);
    if (newStart && newEnd) {
      const [sh, sm] = newStart.split(':').map(Number);
      const [eh, em] = newEnd.split(':').map(Number);
      let diff = (eh * 60 + em) - (sh * 60 + sm);
      if (diff < 0) diff += 24 * 60;
      if (diff === 0) {
        setLogDuration('0');
      } else if (diff > 0 && diff <= 1440) {
        setLogDuration(String(diff));
      }
    }
  };

  const openLogSessionModal = (targetMemberOverride?: string) => {
    if (!savingSessionLockRef.current) {
      setIsSavingSession(false);
    }
    const resolvedId =
      targetMemberOverride ||
      ((isAdminUnlocked || activeMemberId === 'admin')
        ? (logTargetMember || members[0]?.id || 'sai')
        : (currentMember?.id || members[0]?.id || (isGuestMode ? '' : 'sai')));
    setLogTargetMember(resolvedId);
    setLogDate(getLocalDateString());
    setShowLogModal(true);
  };

  const openLogExamModal = (targetMemberOverride?: string) => {
    const resolvedId =
      targetMemberOverride ||
      ((isAdminUnlocked || activeMemberId === 'admin')
        ? (examMemberId || members[0]?.id || 'sai')
        : (currentMember?.id || members[0]?.id || (isGuestMode ? '' : 'sai')));
    setExamMemberId(resolvedId);
    const curDate = getLocalDateString();
    setExamDate(curDate);
    setBatchExamEntries(prev =>
      prev.map((row, idx) => (idx === 0 && !row.overallRank && !row.totalStudents ? { ...row, date: curDate } : row))
    );
    setShowExamModal(true);
  };

  const handleSaveSession = async (e: React.FormEvent) => {
    e.preventDefault();
    if (savingSessionLockRef.current) return;

    const basePath = `artifacts/${appId}/public/data`;
    const targetId = ((isAdminUnlocked || activeMemberId === 'admin') && logTargetMember)
      ? logTargetMember
      : (currentMember?.id || members[0]?.id || (isGuestMode ? '' : 'sai'));
    const targetMem =
      membersLiveRef.current.find(m => m.id === targetId) ||
      members.find(m => m.id === targetId) ||
      (!isGuestMode ? DEFAULT_MEMBERS.find(m => m.id === targetId) : undefined);

    if (!targetMem) {
      notify('Select a Scholar', 'Please sign in or choose a scholar profile before logging.', 'error');
      return;
    }

    const rawDurationMins = Math.round(Number(logDuration) || 0);
    if (rawDurationMins < 1 || rawDurationMins > 1440) {
      notify(
        'Invalid Study Duration',
        'Duration must be between 1 and 1440 minutes. Adjust the Start/End time or enter minutes.',
        'error'
      );
      return;
    }
    const durationMins = rawDurationMins;
    const trimmedNotes = logNotes.trim();
    const currentTodayStr = getLocalDateString();
    const effectiveDateStr = logDate && /^\d{4}-\d{2}-\d{2}$/.test(logDate) ? logDate : currentTodayStr;

    // Prevent accidental rapid duplicate logs of the exact same session within 8 seconds
    const sessionFingerprint = `${targetMem.id}_${logSessionType}_${logSubject}_${effectiveDateStr}_${durationMins}_${totalLogQuestions}_${trimmedNotes}`;
    const nowCheckMs = Date.now();
    if (
      lastSavedSessionFingerprintRef.current.key === sessionFingerprint &&
      nowCheckMs - lastSavedSessionFingerprintRef.current.ts < 8000
    ) {
      setShowLogModal(false);
      return;
    }

    savingSessionLockRef.current = true;
    setIsSavingSession(true);
    lastSavedSessionFingerprintRef.current = { key: sessionFingerprint, ts: nowCheckMs };

    try {
      const linkedTaskIdsSnapshot = [...logLinkedTaskIds];
      const taskCompletionStatusSnapshot = { ...logTaskCompletionStatus };

      const solvedBreakdownNums: { [k: string]: number } = {};
      for (const [k, v] of Object.entries(logQuestionsByTier)) {
        const n = Math.max(0, parseInt(v, 10) || 0);
        if (n > 0) solvedBreakdownNums[k] = n;
      }
      const attemptedBreakdownNums: { [k: string]: number } = {};
      for (const [k, v] of Object.entries(logAttemptedByTier)) {
        const n = Math.max(0, parseInt(v, 10) || 0);
        if (n > 0) attemptedBreakdownNums[k] = n;
      }

      const solvedInput = logQuestionMode === 'multi_tier' && Object.keys(solvedBreakdownNums).length > 0
        ? solvedBreakdownNums
        : totalLogSolved;
      const attemptedInput = logQuestionMode === 'multi_tier' && Object.keys(attemptedBreakdownNums).length > 0
        ? attemptedBreakdownNums
        : totalLogAttempted;
      const totalQCount = totalLogQuestions;
      const questionsBreakdownNums = solvedBreakdownNums;

      const tasksBonusXp = linkedTaskIdsSnapshot.reduce((sum, taskId) => {
        const isTaskDone = (taskCompletionStatusSnapshot[taskId] || 'completed') === 'completed';
        if (!isTaskDone) return sum;

        if (taskId.startsWith('asg_')) {
          const asgId = taskId.replace('asg_', '');
          const asg = teacherAssignments.find(a => a.id === asgId);
          return sum + (asg && asg.xpReward !== undefined ? Number(asg.xpReward) : 40);
        }
        return sum + 0;
      }, 0);

      const baseSessionXp = calcSessionXp(durationMins, solvedInput, logDifficulty, logSessionType, attemptedInput);
      const qDetail = calcQuestionsDetail(solvedInput, attemptedInput, logDifficulty);

      const memberStat = leaderboardStats.find(m => m.id === targetMem.id);
      const hasUnderdogBuff = Boolean(memberStat?.isUnderdogBuffActive);
      const liveTargetMem = membersLiveRef.current.find(m => m.id === targetMem.id) || targetMem;
      const overclockMult = Math.max(
        Number((liveTargetMem as any)?.nextSessionMultiplier) || 1,
        Number((targetMem as any)?.nextSessionMultiplier) || 1
      );
      const hasActiveHostagePact = (arenaSettings.hostagePacts || []).some(
        p =>
          p.status === 'active' &&
          ((p.partnerAId || p.memberAId) === targetMem.id ||
            (p.partnerBId || p.memberBId) === targetMem.id)
      );
      const bloodPactMult = hasActiveHostagePact && logSessionType === 'STUDY' ? 1.5 : 1;
      const combinedMult = (hasUnderdogBuff ? 1.25 : 1) * (overclockMult > 1 ? overclockMult : 1) * bloodPactMult;
      const xpEarned = Math.round(baseSessionXp * combinedMult);

      const activeTierKeys = Array.from(new Set([...Object.keys(solvedBreakdownNums), ...Object.keys(attemptedBreakdownNums)]));
      const difficultyLabel = activeTierKeys.length > 1 ? 'mixed' : (activeTierKeys[0] || logDifficulty);

      const isStealthActive = Boolean(targetMem.stealthUntil && targetMem.stealthUntil > Date.now());
      const stealthHideUntilMs = isStealthActive ? targetMem.stealthUntil! : 0;

      let nowSessionMs = Math.max(Date.now(), getServerSyncedNow(), (Number(arenaSettings.currentCycleStartMs) || 0) + 1000);
      if (effectiveDateStr !== currentTodayStr) {
        const timePart = (logInputMethod === 'TIME_RANGE' && logEndTime) ? `${logEndTime}:00` : '12:00:00';
        const parsedBackdate = new Date(`${effectiveDateStr}T${timePart}`).getTime();
        if (Number.isFinite(parsedBackdate) && parsedBackdate > 0) {
          nowSessionMs = parsedBackdate;
        }
      }

      const cleanseUpdates: Record<string, any> = {};
      if (logSessionType === 'STUDY') {
        if (targetMem.hijackedUntil && targetMem.hijackedUntil > nowSessionMs && durationMins >= 60) {
          cleanseUpdates.hijackedTitle = null;
          cleanseUpdates.hijackedUntil = null;
          cleanseUpdates.hijackedBy = null;
        }
        if (targetMem.curseUntil && targetMem.curseUntil > nowSessionMs) {
          const curseStart = Number(targetMem.curseStartedAt) || (targetMem.curseUntil - 24 * 3600 * 1000);
          const priorMinsSinceCurse = sessions
            .filter(s => s.memberId === targetMem.id && s.sessionType === 'STUDY' && (Number(s.timestamp) || 0) >= curseStart)
            .reduce((acc, s) => acc + (Number(s.duration) || 0), 0);
          if (priorMinsSinceCurse + durationMins >= 45) {
            cleanseUpdates.curseUntil = null;
            cleanseUpdates.curseStartedAt = null;
            cleanseUpdates.curseBy = null;
          }
        }
        if (targetMem.gulagState && durationMins >= 45) {
          cleanseUpdates.gulagState = false;
          cleanseUpdates.gulagStartedAt = null;
        }
        if (targetMem.soundHornPending) {
          playObnoxiousAirhorn();
          cleanseUpdates.soundHornPending = false;
          cleanseUpdates.soundHornBy = null;
        }
      }

      const newSession = {
        memberId: targetMem.id,
        memberName: targetMem.name,
        sessionType: logSessionType,
        inputMethod: logInputMethod,
        subject: logSubject,
        date: effectiveDateStr,
        duration: durationMins,
        startTime: logInputMethod === 'TIME_RANGE' ? logStartTime : '',
        endTime: logInputMethod === 'TIME_RANGE' ? logEndTime : '',
        questions: totalLogQuestions,
        solvedQuestions: totalLogSolved,
        attemptedQuestions: totalLogAttempted,
        solveRate: logSolveRate,
        difficulty: difficultyLabel,
        difficultyBreakdown: solvedBreakdownNums,
        attemptedBreakdown: attemptedBreakdownNums,
        questionXp: qDetail.totalQuestionXp,
        linkedTaskIds: linkedTaskIdsSnapshot,
        tasksBonusXp,
        notes: trimmedNotes,
        xpEarned,
        underdogBoosted: hasUnderdogBuff,
        overclockBoosted: overclockMult > 1,
        overclockMultiplier: overclockMult > 1 ? overclockMult : 1,
        bloodPactBoosted: bloodPactMult > 1,
        stealthLogged: isStealthActive,
        stealthHideUntil: stealthHideUntilMs,
        timestamp: nowSessionMs
      };

      const stopStamp = recordTimerStoppedStamp(
        Math.max(
          Number(timerEngineRef.current?.segmentStartedAt) || 0,
          Number(targetMem.grindingStartedAt) || 0,
          Number(targetMem.grindingUpdatedAt) || 0
        )
      );

      const memberAfterSessionUpdates = {
        isGrinding: false,
        grindingSubject: '',
        grindingStartedAt: null,
        grindingAccumulatedSeconds: 0,
        grindingLinkedTaskId: '',
        grindingUpdatedAt: stopStamp,
        ...(overclockMult > 1 ? { nextSessionMultiplier: null } : {}),
        ...cleanseUpdates
      };

      const preallocatedSessionRef = !isGuestMode ? doc(collection(db, basePath, 'sessions')) : null;
      const sessionDocId = preallocatedSessionRef ? preallocatedSessionRef.id : `demo_${nowSessionMs}_${Math.random().toString(36).slice(2, 6)}`;
      const savedSessionObj = { id: sessionDocId, ...newSession };

      if (!isGuestMode) {
        await updateDoc(doc(db, basePath, 'members', targetMem.id), memberAfterSessionUpdates);
        await setDoc(preallocatedSessionRef!, newSession);
      }

      const prevRank = leaderboardStats.findIndex(m => m.id === targetMem.id) + 1;
      const rivalAhead = prevRank > 1 ? leaderboardStats[prevRank - 2] : null;
      const currentLeaderboardMem = leaderboardStats.find(m => m.id === targetMem.id);
      const currentWeeklyXp = currentLeaderboardMem ? currentLeaderboardMem.weeklyXp : 0;

      playArpeggioUp();
      setSessions(prev => (prev.some(s => s.id === sessionDocId) ? prev : [savedSessionObj, ...prev]));
      setLogQuestions('');
      setLogAttemptedQuestions('');
      setLogQuestionsByTier({ easy: '', mains: '', hard: '', adv: '' });
      setLogAttemptedByTier({ easy: '', mains: '', hard: '', adv: '' });
      setLogNotes('');
      setLogQuickParser('');
      setLogLinkedTaskIds([]);
      setLogTaskCompletionStatus({});
      setShowLogModal(false);

      if (targetMem.id === currentMember?.id || targetMem.id === activeMemberId) {
        persistTimerEngineState({
          status: 'IDLE',
          segmentStartedAt: null,
          accumulatedSeconds: 0,
          startedAtStr: ''
        });
        setTimerRunning(false);
        setTimerStartTime(null);
        setTimerAccumulatedSeconds(0);
        setTimerSeconds(0);
        setTimerLaps([]);
        setTimerLinkedTaskId('');
        setTimerStartedAtStr('');
        resetTimerMilestones();
        if (!isGuestMode) {
          localStorage.removeItem('jee_arena_timer_running');
          localStorage.removeItem('jee_arena_timer_start_time');
          localStorage.removeItem('jee_arena_timer_accumulated_secs');
          localStorage.removeItem('jee_arena_timer_linked_task_id');
          localStorage.removeItem('jee_arena_timer_started_at_str');
          localStorage.removeItem('jee_arena_timer_laps');
        }
        stopLockScreenPresence();
        releaseScreenWakeLock();
        setWakeLockActive(false);
        document.title = 'JEE Grind Arena';
      }

      const isParticipantInCombinedRoom = Boolean(
        Array.isArray(arenaSettings.combinedStudyRoom?.selectedMemberIds) &&
        arenaSettings.combinedStudyRoom!.selectedMemberIds!.includes(targetMem.id)
      );
      if (isParticipantInCombinedRoom && (arenaSettings.combinedStudyRoom?.sharedBlockStartedAt || (arenaSettings.combinedStudyRoom?.selectedMemberIds?.length || 0) > 0)) {
        handleUpdateCombinedStudyRoom({
          sharedBlockStartedAt: null,
          sharedTimerStatus: 'IDLE',
          sharedAccumulatedSeconds: 0,
          selectedMemberIds: []
        }).catch(() => {});
      }

      membersLiveRef.current = membersLiveRef.current.map(m =>
        m.id === targetMem.id ? { ...m, ...memberAfterSessionUpdates } : m
      );
      setMembers(prev => prev.map(m => (m.id === targetMem.id ? { ...m, ...memberAfterSessionUpdates } : m)));

      const currentStreak = computeMemberStreak({ ...targetMem, lastLoginDate: effectiveDateStr === currentTodayStr ? currentTodayStr : targetMem.lastLoginDate }, [savedSessionObj, ...sessions]);
      const isTargetSleeperNow = Boolean(targetMem.id === activeSleeperMemberId && isSleeperDecoyActiveNow);
      const decoySessionMins = Math.max(1, Math.round(durationMins * 0.10));
      const decoySessionXp = Math.max(1, Math.round(xpEarned * 0.10));
      notify(
        isStealthActive
          ? '🌿 Bush Ambush Cloak Active (12h)'
          : isTargetSleeperNow
          ? `🕵️‍♂️ 10% Sleeper Log Saved (+${xpEarned} Real XP)`
          : 'Session Logged',
        isStealthActive
          ? `Session & +${xpEarned} XP hidden from the log and leaderboard for 12 hours! Will drop suddenly when timer expires.`
          : isTargetSleeperNow
          ? `Your true +${xpEarned} XP (${durationMins}m) is safely banked! Everyone else only sees +${decoySessionXp} XP (${decoySessionMins}m) until Blackout starts!`
          : `+${xpEarned} XP ${!isRaidBlackoutActive && hasUnderdogBuff ? '(⚡ 1.25x Underdog Buff) ' : ''}${overclockMult > 1 ? `(${overclockMult >= 2 ? '🔥' : '⚡'} ${overclockMult.toFixed(1)}x Overclock) ` : ''}${bloodPactMult > 1 ? '(🩸 1.5x Blood Pact) ' : ''}added to ${targetMem.name} & -${durationMins + totalQCount * 3} Boss DMG!`
      );

      setStudyLogSuccessData({
        memberName: targetMem.name,
        xpEarned,
        durationMins,
        totalQCount,
        tasksCount: linkedTaskIdsSnapshot.length,
        streakCount: currentStreak
      });

      if (logSessionType === 'STUDY' && durationMins >= 90) {
        const dropPayload = {
          memberId: targetMem.id,
          memberName: targetMem.name,
          durationMins,
          grantedAt: Date.now()
        };
        setUnclaimedVaultDrop(dropPayload);
        if (!isGuestMode) {
          try {
            localStorage.setItem('jee_arena_unclaimed_vault_drop', JSON.stringify(dropPayload));
          } catch {}
        }
        setTimeout(() => {
          setLootCrateDropData({
            memberId: targetMem.id,
            memberName: targetMem.name,
            durationMins
          });
        }, 2800);
      }

      if (!isStealthActive && !isRaidBlackoutActive && rivalAhead && (currentWeeklyXp + xpEarned) > rivalAhead.weeklyXp) {
        setTimeout(() => {
          setArenaOvertakeData({
            challengerName: targetMem.name,
            rivalName: rivalAhead.name,
            oldRank: prevRank,
            newRank: Math.max(1, prevRank - 1),
            differenceXp: xpEarned
          });
        }, 3500);
      }

      // Deal damage to Co-op Raid Boss (1 HP per study minute + 3 HP per solved problem)
      if (logSessionType === 'STUDY' && arenaSettings.raidEnabled && !isStealthActive) {
        const damageDealt = Math.max(1, durationMins + totalQCount * 3);
        const nextBossHp = Math.max(0, (Number(arenaSettings.raidBossCurrentHp) || 0) - damageDealt);
        const raidPatch = {
          raidBossCurrentHp: nextBossHp,
          lastRaidDamageHit: {
            attackerName: targetMem.name,
            damage: damageDealt,
            timestamp: Date.now()
          }
        };
        if (isGuestMode) {
          setArenaSettings(prev => ({ ...prev, ...raidPatch }));
        } else {
          const settingsRef = doc(db, basePath, 'settings', 'arenaState');
          await setDoc(settingsRef, raidPatch, { merge: true }).catch(e => {
            console.warn('Raid boss damage update error:', e);
          });
        }
      }

      let taskRequiringProof: any = null;
      for (const tId of linkedTaskIdsSnapshot) {
        const isTaskDone = (taskCompletionStatusSnapshot[tId] || 'completed') === 'completed';

        if (tId.startsWith('asg_')) {
          const asgId = tId.replace('asg_', '');
          const asg = teacherAssignments.find(a => a.id === asgId);
          if (!asg) continue;

          if (isTaskDone) {
            const updatedSubs = { ...(asg.submissions || {}) };
            if (!updatedSubs[targetMem.id] || updatedSubs[targetMem.id].status !== 'graded') {
              updatedSubs[targetMem.id] = {
                submittedAt: Date.now(),
                attachedFiles: [],
                note: trimmedNotes || `Completed during ${durationMins}m study session.`,
                status: 'pending',
                xpAwarded: asg.xpReward
              };
              if (isGuestMode) {
                setTeacherAssignments(prev => prev.map(a => a.id === asg.id ? { ...a, submissions: updatedSubs } : a));
                if (!isStealthActive) {
                  await pushActivity(
                    'task_complete',
                    `📸 ${targetMem.name} completed homework "${asg.title}" via study session`,
                    `Ready for ${asg.teacherName} review (+${asg.xpReward} XP pending) • ${durationMins}m, ${totalQCount} Qs`,
                    targetMem.id,
                    0
                  );
                }
              } else {
                try {
                  await updateDoc(doc(db, basePath, 'teacher_assignments', asg.id), {
                    submissions: updatedSubs
                  });
                  if (!isStealthActive) {
                    await pushActivity(
                      'task_complete',
                      `📸 ${targetMem.name} completed homework "${asg.title}" via study session`,
                      `Ready for ${asg.teacherName} review (+${asg.xpReward} XP pending) • ${durationMins}m, ${totalQCount} Qs`,
                      targetMem.id,
                      0
                    );
                  }
                } catch (e) {
                  console.error(e);
                }
              }
            }
          }
          continue;
        }

        const taskObj = tasks.find(t => t.id === tId);
        if (!taskObj) continue;

        const prevTimeMap = taskObj.timeSpentByMember || {};
        const updatedTimeMap = {
          ...prevTimeMap,
          [targetMem.id]: (Number(prevTimeMap[targetMem.id]) || 0) + durationMins
        };

        if (!isTaskDone) {
          if (isGuestMode) {
            setTasks(prev => prev.map(t => t.id === taskObj.id ? { ...t, timeSpentByMember: updatedTimeMap } : t));
          } else {
            await updateDoc(doc(db, basePath, 'tasks', taskObj.id), {
              timeSpentByMember: updatedTimeMap
            }).catch(e => console.error(e));
          }
          continue;
        }

        const completions = { ...(taskObj.completions || {}) };
        const existingComp = completions[targetMem.id];

        if (!existingComp || existingComp.status !== 'verified') {
          if (taskObj.requireProof) {
            if (isGuestMode) {
              setTasks(prev => prev.map(t => t.id === taskObj.id ? { ...t, timeSpentByMember: updatedTimeMap } : t));
            } else {
              await updateDoc(doc(db, basePath, 'tasks', taskObj.id), {
                timeSpentByMember: updatedTimeMap
              }).catch(e => console.error(e));
            }
            taskRequiringProof = taskObj;
          } else {
            const anyoneVerifiedYet = Object.values(completions).some((c: any) => c && c.status === 'verified');
            const isFirstBlood = !taskObj.isPersonal && taskObj.doubleXpFirst && !anyoneVerifiedYet;
            const taskBaseXp = taskObj.xp !== undefined && taskObj.xp !== null ? Math.max(0, Number(taskObj.xp)) : 25;
            const awardedXp = isFirstBlood ? taskBaseXp * 2 : taskBaseXp;

            completions[targetMem.id] = {
              status: 'verified',
              completedAt: nowSessionMs,
              xpAwarded: awardedXp,
              isFirstBlood,
              proofImages: [],
              note: trimmedNotes || 'Completed via study session log'
            };

            if (isGuestMode) {
              setTasks(prev => prev.map(t => t.id === taskObj.id ? { ...t, timeSpentByMember: updatedTimeMap, completions } : t));
            } else {
              await updateDoc(doc(db, basePath, 'tasks', taskObj.id), {
                timeSpentByMember: updatedTimeMap,
                completions
              }).catch(e => console.error(e));
            }

            if (!isStealthActive) {
              await pushActivity(
                'task_complete',
                `${isFirstBlood ? '⚡ FIRST BLOOD! ' : '✓ '}${targetMem.name} completed "${taskObj.title}"`,
                `Task XP: +${awardedXp} XP ${isFirstBlood ? '(2x Speed Bonus)' : ''} • Session: ${durationMins}m, ${totalQCount} Qs`,
                targetMem.id,
                awardedXp
              );
            }
          }
        } else {
          if (isGuestMode) {
            setTasks(prev => prev.map(t => t.id === taskObj.id ? { ...t, timeSpentByMember: updatedTimeMap } : t));
          } else {
            await updateDoc(doc(db, basePath, 'tasks', taskObj.id), {
              timeSpentByMember: updatedTimeMap
            }).catch(e => console.error(e));
          }
        }
      }

      const breakdownStr = Object.entries(questionsBreakdownNums).map(([k, count]) => `${count} ${k.toUpperCase()}`).join(', ');
      if (!isStealthActive) {
        const boostBadges: string[] = [];
        if (hasUnderdogBuff) boostBadges.push('⚡ 1.25x Underdog Boost!');
        if (overclockMult > 1) boostBadges.push(`${overclockMult >= 2 ? '🔥' : '⚡'} ${overclockMult.toFixed(1)}x Overclock!`);
        const isSleeperBroadcast = Boolean(targetMem.id === activeSleeperMemberId && isSleeperDecoyActiveNow);
        const pubDuration = isSleeperBroadcast ? Math.max(1, Math.round(durationMins * 0.10)) : durationMins;
        const pubXp = isSleeperBroadcast ? Math.max(1, Math.round(xpEarned * 0.10)) : xpEarned;
        const pubQs = isSleeperBroadcast ? Math.round(totalQCount * 0.10) : totalQCount;
        await pushActivity(
          'session_log',
          `${targetMem.name} logged ${formatDuration(pubDuration)} of ${logSubject}${boostBadges.length > 0 && !isSleeperBroadcast ? ` (${boostBadges.join(' • ')})` : ''}`,
          `${pubQs > 0 ? `${pubQs} Qs${breakdownStr && !isSleeperBroadcast ? ` (${breakdownStr})` : ''} • ` : ''}-${pubDuration + pubQs * 3} Boss HP • +${pubXp} XP${trimmedNotes ? ` - "${trimmedNotes}"` : ''}`,
          targetMem.id,
          pubXp
        );
      }

      await updateDailyStreak(targetMem, [savedSessionObj]);

      if (taskRequiringProof) {
        setProofTaskModal(taskRequiringProof);
      }

      if (pendingSyncInviteAfterLogRef.current) {
        const inviteToExecute = pendingSyncInviteAfterLogRef.current;
        pendingSyncInviteAfterLogRef.current = null;
        setTimeout(() => {
          executeAcceptCombinedStudyInvite(inviteToExecute);
        }, 500);
      }
    } catch (err) {
      lastSavedSessionFingerprintRef.current = { key: '', ts: 0 };
      handleFirestoreError(err, OperationType.CREATE, `${basePath}/sessions`);
      notify(
        'Could Not Log Session',
        err instanceof Error ? err.message : 'Unable to reach server to save your session. Please try again.',
        'error'
      );
    } finally {
      savingSessionLockRef.current = false;
      setIsSavingSession(false);
    }
  };

  const handleCreatePersonalTask = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!myTaskTitle.trim()) return;
    const basePath = `artifacts/${appId}/public/data`;
    const owner = currentMember || members[0] || (!isGuestMode ? DEFAULT_MEMBERS[0] : undefined);
    if (!owner) return;
    const safeXp = 0; // Tasks no longer award special XP per user request

    const newTask = {
      title: myTaskTitle.trim(),
      subject: myTaskSubject,
      xp: safeXp,
      questionsText: myTaskNotes.trim(),
      linkUrl: myTaskLink.trim(),
      doubleXpFirst: false,
      requireProof: false,
      assignedTo: [owner.id],
      isPersonal: true,
      ownerId: owner.id,
      createdBy: owner.name,
      referenceImages: [],
      completions: {},
      timeSpentByMember: {},
      createdAt: Date.now()
    };

    if (isGuestMode) {
      setTasks(prev => [{ id: `demo_task_${Date.now()}`, ...newTask }, ...prev]);
    } else {
      try {
        await addDoc(collection(db, basePath, 'tasks'), newTask);
        // Personal task creation is private to the owner - no public broadcast sent here
      } catch (err) {
        handleFirestoreError(err, OperationType.CREATE, `${basePath}/tasks`);
      }
    }

    setMyTaskTitle('');
    setMyTaskNotes('');
    setMyTaskLink('');
    setShowPersonalTaskModal(false);
    notify('Personal Task Added', `"${newTask.title}" added to your checklist. (0 XP Honor Challenge)`);
  };

  const handleInlineAddPersonalTask = async () => {
    if (!inlineNewTaskTitle.trim()) return;
    const basePath = `artifacts/${appId}/public/data`;
    const owner = currentMember || members[0] || (!isGuestMode ? DEFAULT_MEMBERS[0] : undefined);
    if (!owner) return;
    const newTask = {
      title: inlineNewTaskTitle.trim(),
      subject: logSubject,
      xp: 0,
      questionsText: '',
      linkUrl: '',
      doubleXpFirst: false,
      requireProof: false,
      assignedTo: [owner.id],
      isPersonal: true,
      ownerId: owner.id,
      createdBy: owner.name,
      referenceImages: [],
      completions: {},
      timeSpentByMember: {},
      createdAt: Date.now()
    };
    if (isGuestMode) {
      const demoId = `demo_task_${Date.now()}`;
      setTasks(prev => [{ id: demoId, ...newTask }, ...prev]);
      setLogLinkedTaskIds(prev => [...prev, demoId]);
      setInlineNewTaskTitle('');
      notify('Task Linked', 'Personal task created and linked to this session.');
      return;
    }
    try {
      const docRef = await addDoc(collection(db, basePath, 'tasks'), newTask);
      setLogLinkedTaskIds(prev => [...prev, docRef.id]);
      setInlineNewTaskTitle('');
      notify('Task Linked', 'Personal task created and linked to this session.');
    } catch (e) {
      handleFirestoreError(e, OperationType.CREATE, `${basePath}/tasks`);
    }
  };

  const handleCompleteTaskClick = (task: any) => {
    // Directly redirect to StudyFlow Session Logger with Time Range, time frame and pre-linked task!
    setLogSessionType('STUDY');
    setLogInputMethod('TIME_RANGE');
    setLogSubject(task.subject || 'Physics');
    setLogLinkedTaskIds([task.id]);
    setLogNotes(`Completed task: ${task.title}`);

    // Pre-calculate realistic timing window (last 45 mins)
    const now = new Date();
    const endH = String(now.getHours()).padStart(2, '0');
    const endM = String(now.getMinutes()).padStart(2, '0');
    const startObj = new Date(now.getTime() - 45 * 60000);
    const startH = String(startObj.getHours()).padStart(2, '0');
    const startM = String(startObj.getMinutes()).padStart(2, '0');
    setLogStartTime(`${startH}:${startM}`);
    setLogEndTime(`${endH}:${endM}`);
    setLogDuration('45');
    setLogQuestions('');
    setLogAttemptedQuestions('');
    setLogQuestionsByTier({ easy: '', mains: '', hard: '', adv: '' });
    setLogAttemptedByTier({ easy: '', mains: '', hard: '', adv: '' });

    const targetId = (activeMemberId && activeMemberId !== 'admin' && activeMemberId !== 'guest' && !activeMemberId.startsWith('teacher_'))
      ? activeMemberId
      : (currentMember?.id || members[0]?.id || (isGuestMode ? '' : 'sai'));
    openLogSessionModal(targetId);
    notify(
      'Redirected to Study Session Logger',
      `Log your timings range & questions solved for "${task.title}". XP will be awarded based on your questions & time!`
    );
  };

  const handleCommitTaskCompletion = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!completeTaskModal) return;
    const task = completeTaskModal;
    const basePath = `artifacts/${appId}/public/data`;
    const targetMem = currentMember || members[0] || (!isGuestMode ? DEFAULT_MEMBERS[0] : undefined);
    if (!targetMem) {
      notify('Select a Scholar', 'Please sign in or choose a scholar profile before logging.', 'error');
      return;
    }

    // Task completion alone is capped at 30 XP max
    const taskRawXp = Number(task.xp) !== undefined && task.xp !== null ? Number(task.xp) : 25;
    const taskBaseXp = Math.min(30, Math.max(0, taskRawXp));

    const qCount = Math.max(0, Number(completeTaskQuestions) || 0);
    const durationMins = Math.max(1, Number(completeTaskDuration) || 30);

    let tierMult = 1.5;
    if (completeTaskDifficulty === 'easy') tierMult = 1.0;
    if (completeTaskDifficulty === 'mains' || completeTaskDifficulty === 'medium') tierMult = 1.5;
    if (completeTaskDifficulty === 'hard') tierMult = 2.0;
    if (completeTaskDifficulty === 'advanced') tierMult = 2.5;

    const questionsXp = Math.round(qCount * tierMult);

    const completions = { ...(task.completions || {}) };
    const anyoneVerifiedYet = Object.values(completions).some((c: any) => c && c.status === 'verified');
    const isFirstBlood = !task.isPersonal && task.doubleXpFirst && !anyoneVerifiedYet;

    const finalTaskBaseXp = 0; // ALL special task completion XP removed per user request
    const totalEarnedXp = questionsXp; // Only question XP is counted, no special task XP bonus.

    const isStealthActive = Boolean(targetMem.stealthUntil && targetMem.stealthUntil > Date.now());
    const stealthHideUntilMs = isStealthActive ? targetMem.stealthUntil! : 0;
    const nowDateStr = getLocalDateString();

    // Save Study Session Record
    const newSession = {
      memberId: targetMem.id,
      memberName: targetMem.name,
      sessionType: 'STUDY',
      subject: task.subject || 'Physics',
      duration: durationMins,
      questions: qCount,
      solvedQuestions: qCount,
      attemptedQuestions: 0,
      difficulty: completeTaskDifficulty,
      xpEarned: questionsXp,
      notes: completeTaskNotes.trim() || `Task Completed: "${task.title}"`,
      date: nowDateStr,
      stealthLogged: isStealthActive,
      stealthHideUntil: stealthHideUntilMs,
      timestamp: Math.max(Date.now(), getServerSyncedNow(), (Number(arenaSettings.currentCycleStartMs) || 0) + 1000)
    };

    try {
      const sessRef = !isGuestMode ? doc(collection(db, basePath, 'sessions')) : null;
      const sessId = sessRef ? sessRef.id : `demo_sess_${Date.now()}`;
      const savedSess = { id: sessId, ...newSession };

      if (isGuestMode) {
        setSessions(prev => [savedSess, ...prev]);
      } else {
        await setDoc(sessRef!, newSession);
        setSessions(prev => (prev.some(s => s.id === sessId) ? prev : [savedSess, ...prev]));
      }

      completions[targetMem.id] = {
        status: task.requireProof && completeTaskProofImages.length === 0 ? 'pending_review' : 'verified',
        completedAt: Math.max(Date.now(), getServerSyncedNow(), (Number(arenaSettings.currentCycleStartMs) || 0) + 1000),
        xpAwarded: totalEarnedXp,
        isFirstBlood,
        proofImages: completeTaskProofImages,
        note: completeTaskNotes.trim() || 'Completed with questions log'
      };

      const prevTimeMap = task.timeSpentByMember || {};
      const updatedTimeMap = {
        ...prevTimeMap,
        [targetMem.id]: (Number(prevTimeMap[targetMem.id]) || 0) + durationMins
      };

      if (isGuestMode) {
        setTasks(prev =>
          prev.map(t =>
            t.id === task.id ? { ...t, completions, timeSpentByMember: updatedTimeMap } : t
          )
        );
      } else {
        await updateDoc(doc(db, basePath, 'tasks', task.id), {
          completions,
          timeSpentByMember: updatedTimeMap
        });
      }

      if (!isStealthActive) {
        await pushActivity(
          'task_complete',
          `${isFirstBlood ? '⚡ ' : '✓ '}${targetMem.name} finished "${task.title}" (+${totalEarnedXp} XP)`,
          `Session Log: ${durationMins}m • ${qCount} Qs: +${questionsXp} XP`,
          targetMem.id,
          totalEarnedXp
        );
      }

      await updateDailyStreak(targetMem, [savedSess]);

      setCompleteTaskModal(null);
      notify(
        'Task Completed & Session Logged!',
        `Earned +${totalEarnedXp} XP (Study Session & Questions Log)`
      );
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/tasks/${task.id}`);
      notify(
        'Failed to Log Task',
        err instanceof Error ? err.message : 'Unable to save task completion to server.',
        'error'
      );
    }
  };

  const handleDeleteTask = async (task: any) => {
    const basePath = `artifacts/${appId}/public/data`;
    setTasks(prev => prev.filter(t => t.id !== task.id));
    if (isGuestMode) {
      notify('Task Removed (Demo)', `"${task.title}" removed from demo checklist.`);
      return;
    }
    try {
      await deleteDoc(doc(db, basePath, 'tasks', task.id));
      notify('Task Removed', `"${task.title}" was deleted.`);
    } catch (err) {
      handleFirestoreError(err, OperationType.DELETE, `${basePath}/tasks/${task.id}`);
    }
  };

  const handleExamTypeSwitch = (newType: string) => {
    setExamType(newType);
    const tpl = EXAM_TEMPLATES[newType] || EXAM_TEMPLATES['JEE Mains'];
    setExamMaxMarks(String(tpl.totalMax));
    setExamSubjects(tpl.subjects.map(s => ({ ...s, marks: '', rank: '' })));
  };

  const handleSaveExam = async (e: React.FormEvent) => {
    e.preventDefault();
    const basePath = `artifacts/${appId}/public/data`;
    const targetId = ((isAdminUnlocked || activeMemberId === 'admin') && examMemberId)
      ? examMemberId
      : (currentMember?.id || members[0]?.id || (isGuestMode ? '' : 'sai'));
    const targetMem =
      membersLiveRef.current.find(m => m.id === targetId) ||
      members.find(m => m.id === targetId) ||
      (!isGuestMode ? DEFAULT_MEMBERS.find(m => m.id === targetId) : undefined);
    if (!targetMem) {
      notify('Select a Scholar', 'Please choose which scholar this mock exam belongs to.', 'error');
      return;
    }

    const totalCandidates = Number(examTotalStudents);
    const overallRankNum = Number(examRank);
    const maxSubjRank = examSubjects
      .filter(s => s.enabled)
      .reduce((max, s) => Math.max(max, Number(s.rank) || 0), 0);
    const highestEnteredRank = Math.max(overallRankNum, maxSubjRank);

    if (!totalCandidates || totalCandidates <= 0 || !overallRankNum || overallRankNum <= 0) {
      notify('Invalid Rank or Total', 'Please enter both Rank and Total Students.', 'error');
      return;
    }

    if (totalCandidates < highestEnteredRank) {
      notify(
        'Total Students Smaller Than Rank',
        `Total Students (${totalCandidates}) cannot be less than your Rank (#${highestEnteredRank}). Check if a digit is missing (e.g. 473 or 560).`,
        'error'
      );
      return;
    }

    const overallPct = calcPercentile(overallRankNum, totalCandidates);

    const processedSubjects = examSubjects
      .filter(s => s.enabled)
      .map(s => {
        const sRank = Number(s.rank) || overallRankNum;
        return {
          name: s.name,
          marks: Number(s.marks) || 0,
          maxMarks: Number(s.maxMarks) || 100,
          rank: sRank,
          percentile: Number(calcPercentile(sRank, totalCandidates).toFixed(2))
        };
      });

    const currentTodayStr = getLocalDateString();
    const effectiveExamDate = examDate && /^\d{4}-\d{2}-\d{2}$/.test(examDate) ? examDate : currentTodayStr;
    const syncedExamNow = Math.max(Date.now(), getServerSyncedNow(), (Number(arenaSettings.currentCycleStartMs) || 0) + 1000);
    const parsedExamDateMs = new Date(`${effectiveExamDate}T12:00:00`).getTime();
    const examTimestamp = effectiveExamDate === currentTodayStr
      ? syncedExamNow
      : (Number.isFinite(parsedExamDateMs) ? parsedExamDateMs : syncedExamNow);

    const examDoc = {
      memberId: targetMem.id,
      memberName: targetMem.name,
      institute: targetMem.institute,
      examType,
      title: examTitle.trim() || `${examType} Test`,
      date: effectiveExamDate,
      totalStudents: totalCandidates,
      overallMarks: Number(examMarks) || 0,
      overallMaxMarks: Number(examMaxMarks) || 300,
      overallRank: overallRankNum,
      overallPercentile: Number(overallPct.toFixed(2)),
      subjects: processedSubjects,
      timestamp: examTimestamp
    };

    if (isGuestMode) {
      const demoExamDoc = { id: `demo_exam_${Date.now()}`, ...examDoc };
      setExams(prev => [demoExamDoc, ...prev]);
      if (targetMem.unexcusedZero) {
        setMembers(prev =>
          prev.map(m =>
            m.id === targetMem.id
              ? { ...m, unexcusedZero: false, unexcusedReason: '', unexcusedAt: null }
              : m
          )
        );
      }
      await pushActivity(
        'exam_log',
        `🏆 ${targetMem.name} logged ${examDoc.title}`,
        `Rank #${overallRankNum}/${totalCandidates} (${overallPct.toFixed(1)}%ile) • Date: ${effectiveExamDate} • ${examDoc.overallMarks}/${examDoc.overallMaxMarks}`,
        targetMem.id,
        Math.round(overallPct * 3)
      );
      setExamTitle('');
      setExamTotalStudents('');
      setExamMarks('');
      setExamRank('');
      setExamDate(getLocalDateString());
      setShowExamModal(false);
      notify('Exam Logged (Demo)', `${overallPct.toFixed(1)}%ile recorded for ${targetMem.name}`);
      fetchAiDiagnosticSummary(targetMem.id, [demoExamDoc, ...exams.filter(ex => ex.memberId === targetMem.id)]);
      return;
    }

    try {
      const newExamRef = doc(collection(db, basePath, 'exams'));
      const savedExamObj = { id: newExamRef.id, ...examDoc };
      await setDoc(newExamRef, examDoc);
      setExams(prev => (prev.some(ex => ex.id === newExamRef.id) ? prev : [savedExamObj, ...prev]));

      if (targetMem.unexcusedZero) {
        await updateDoc(doc(db, basePath, 'members', targetMem.id), {
          unexcusedZero: false,
          unexcusedReason: '',
          unexcusedAt: null
        });
      }

      await pushActivity(
        'exam_log',
        `🏆 ${targetMem.name} logged ${examDoc.title}`,
        `Rank #${overallRankNum}/${totalCandidates} (${overallPct.toFixed(1)}%ile) • Date: ${effectiveExamDate} • ${examDoc.overallMarks}/${examDoc.overallMaxMarks}`,
        targetMem.id,
        Math.round(overallPct * 3)
      );

      setExamTitle('');
      setExamTotalStudents('');
      setExamMarks('');
      setExamRank('');
      setExamDate(getLocalDateString());
      setShowExamModal(false);
      notify('Exam Logged', `${overallPct.toFixed(1)}%ile recorded for ${targetMem.name}`);

      fetchAiDiagnosticSummary(targetMem.id, [savedExamObj, ...exams.filter(ex => ex.memberId === targetMem.id)]);
    } catch (err) {
      handleFirestoreError(err, OperationType.CREATE, `${basePath}/exams`);
      notify(
        'Failed to Log Exam',
        err instanceof Error ? err.message : 'Unable to save exam result to server. Please try again.',
        'error'
      );
    }
  };

  // Batch Multi-Test Logger (Logs past or current multiple tests at once)
  const handleBatchSaveExams = async (e: React.FormEvent) => {
    e.preventDefault();
    const basePath = `artifacts/${appId}/public/data`;
    const targetId = ((isAdminUnlocked || activeMemberId === 'admin') && examMemberId)
      ? examMemberId
      : (currentMember?.id || members[0]?.id || (isGuestMode ? '' : 'sai'));
    const targetMem =
      membersLiveRef.current.find(m => m.id === targetId) ||
      members.find(m => m.id === targetId) ||
      (!isGuestMode ? DEFAULT_MEMBERS.find(m => m.id === targetId) : undefined);
    if (!targetMem) {
      notify('Select a Scholar', 'Please choose which scholar these exams belong to.', 'error');
      return;
    }

    const validEntries = batchExamEntries.filter(b => {
      const r = Number(b.overallRank);
      const t = Number(b.totalStudents);
      return r > 0 && t > 0 && t >= r;
    });

    if (validEntries.length === 0) {
      notify('Incomplete Test Entries', 'Please enter Rank and Batch Total (>= Rank) for at least one test.', 'error');
      return;
    }

    try {
      const currentTodayStr = getLocalDateString();
      const newExamsList: any[] = [];
      for (let idx = 0; idx < validEntries.length; idx++) {
        const entry = validEntries[idx];
        const r = Number(entry.overallRank);
        const t = Number(entry.totalStudents);
        const pct = calcPercentile(r, t);
        const eDate = entry.date || currentTodayStr;
        const eTimestamp = eDate === currentTodayStr
          ? Math.max(Date.now(), getServerSyncedNow(), (Number(arenaSettings.currentCycleStartMs) || 0) + 1000) + idx
          : new Date(`${eDate}T12:00:00`).getTime();

        const docData = {
          memberId: targetMem.id,
          memberName: targetMem.name,
          institute: targetMem.institute,
          examType: entry.examType || 'JEE Mains',
          title: entry.title.trim() || `${entry.examType || 'Mock'} Test`,
          date: eDate,
          totalStudents: t,
          overallMarks: Number(entry.overallMarks) || 0,
          overallMaxMarks: Number(entry.overallMaxMarks) || 300,
          overallRank: r,
          overallPercentile: Number(pct.toFixed(2)),
          subjects: [],
          timestamp: eTimestamp
        };
        if (isGuestMode) {
          newExamsList.push({ id: `demo_exam_${Date.now()}_${idx}`, ...docData });
        } else {
          const ref = doc(collection(db, basePath, 'exams'));
          await setDoc(ref, docData);
          newExamsList.push({ id: ref.id, ...docData });
        }
      }

      setExams(prev => {
        const seen = new Set(prev.map(x => x.id));
        return [...newExamsList.filter(x => !seen.has(x.id)), ...prev];
      });

      if (isGuestMode) {
        if (targetMem.unexcusedZero) {
          setMembers(prev =>
            prev.map(m =>
              m.id === targetMem.id
                ? { ...m, unexcusedZero: false, unexcusedReason: '', unexcusedAt: null }
                : m
            )
          );
        }
      } else if (targetMem.unexcusedZero) {
        await updateDoc(doc(db, basePath, 'members', targetMem.id), {
          unexcusedZero: false,
          unexcusedReason: '',
          unexcusedAt: null
        });
      }

      await pushActivity(
        'exam_log',
        `🏆 ${targetMem.name} batch-logged ${validEntries.length} tests`,
        `Committed ${validEntries.length} mock tests into career records.`,
        targetMem.id,
        0
      );

      setShowExamModal(false);
      setExamEntryMode('single');
      setBatchExamEntries([
        {
          id: 'batch_1',
          examType: 'JEE Mains',
          title: 'Mock Test 1',
          date: getLocalDateString(),
          overallMarks: '',
          overallMaxMarks: '300',
          overallRank: '',
          totalStudents: ''
        }
      ]);
      notify('Batch Exams Logged!', `Recorded ${validEntries.length} tests for ${targetMem.name}`);
      if (newExamsList.length > 0) {
        fetchAiDiagnosticSummary(targetMem.id, [...newExamsList, ...exams.filter(ex => ex.memberId === targetMem.id)]);
      }
    } catch (err) {
      handleFirestoreError(err, OperationType.CREATE, `${basePath}/exams`);
      notify(
        'Failed to Batch Log Exams',
        err instanceof Error ? err.message : 'Unable to save batch exam entries to server.',
        'error'
      );
    }
  };

  // The "Active Standing" Rule: Admin Unexcused Zero (0 XP) Toggle
  const handleToggleUnexcusedZero = async (memberId: string, currentStatus: boolean, reason?: string) => {
    const basePath = `artifacts/${appId}/public/data`;
    const mem = members.find(m => m.id === memberId) || DEFAULT_MEMBERS.find(m => m.id === memberId);
    if (!mem) return;

    const newStatus = !currentStatus;
    const finalReason = newStatus ? (reason?.trim() || unexcusedReasonMap[memberId]?.trim() || 'Unexcused test absence (bunked test)') : '';

    const unexcusedUpdates = {
      unexcusedZero: newStatus,
      unexcusedReason: finalReason,
      unexcusedAt: newStatus ? Date.now() : null
    };
    membersLiveRef.current = membersLiveRef.current.map(m => m.id === memberId ? { ...m, ...unexcusedUpdates } : m);
    setMembers(prev => prev.map(m => m.id === memberId ? { ...m, ...unexcusedUpdates } : m));

    try {
      await updateDoc(doc(db, basePath, 'members', memberId), unexcusedUpdates);

      if (newStatus) {
        await pushActivity(
          'penalty',
          `⚠️ Admin issued Unexcused Zero (0 XP) penalty to ${mem.name}`,
          finalReason,
          mem.id,
          0
        );
        notify('Unexcused Zero Applied', `${mem.name} received 0 XP for test standing this week.`);
      } else {
        await pushActivity(
          'admin_adjust',
          `🛡️ Admin restored Active Standing for ${mem.name}`,
          'Excused absence / off-week: latest active percentile restored.',
          mem.id,
          0
        );
        notify('Active Standing Restored', `${mem.name}'s latest exam percentile is now active.`);
      }
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/members/${memberId}`);
    }
  };

  // Tuition Teacher AI Chatbot Handler
  const handleSendTeacherChat = async (e?: React.FormEvent, customQuestion?: string) => {
    if (e) e.preventDefault();
    const query = customQuestion || teacherChatInput.trim();
    if (!query || isTeacherChatSending) return;

    setTeacherChatMessages(prev => [...prev, { sender: 'teacher', text: query, timestamp: Date.now() }]);
    setTeacherChatInput('');
    setIsTeacherChatSending(true);

    const activeList = members.length > 0 ? members : DEFAULT_MEMBERS;
    const curTeacher = teachers.find(t => t.id === activeTeacherId) || DEFAULT_TEACHERS.find(t => t.subject === selectedTuitionSubject) || DEFAULT_TEACHERS[0];

    const studentsTelemetry = activeList.map(m => {
      const memSessions = sessions.filter(s => s.memberId === m.id && s.subject === selectedTuitionSubject && (s.timestamp || 0) >= weekStartMs);
      const weeklyMinutes = memSessions.reduce((acc, s) => acc + (Number(s.duration) || 0), 0);
      const weeklyQuestions = memSessions.reduce((acc, s) => acc + (Number(s.questions) || 0), 0);
      
      const memExams = exams.filter(e => e.memberId === m.id);
      const recentExams = memExams.slice(0, 3).map(ex => {
        const sub = (ex.subjects || []).find((s: any) => s.name.toLowerCase() === selectedTuitionSubject.toLowerCase());
        return {
          title: ex.title,
          marks: sub?.marks ?? ex.overallMarks,
          maxMarks: sub?.maxMarks ?? ex.overallMaxMarks,
          percentile: sub?.percentile ?? ex.overallPercentile,
          rank: sub?.rank ?? ex.overallRank
        };
      });

      const studentStat = leaderboardStats.find(s => s.id === m.id);
      const completedAssignments = teacherAssignments.filter(a => a.subject === selectedTuitionSubject && a.submissions?.[m.id]?.status === 'graded');
      const excusedAssignments = teacherAssignments.filter(a => a.subject === selectedTuitionSubject && a.submissions?.[m.id]?.status === 'graded' && a.submissions?.[m.id]?.marksAwarded === 0);

      return {
        name: m.name,
        institute: m.institute,
        weeklyMinutes,
        weeklyQuestions,
        sessionCount: memSessions.length,
        recentExams,
        completedAssignmentsCount: completedAssignments.length,
        excusedAssignmentsCount: excusedAssignments.length,
        standingStatus: studentStat?.standingDetail || 'Active'
      };
    });

    try {
      const res = await fetch('/api/teacher-chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          teacherName: curTeacher?.name || 'Tuition Faculty',
          subject: selectedTuitionSubject,
          question: query,
          studentFilter: teacherChatStudentFocus,
          students: studentsTelemetry
        })
      });

      if (res.ok) {
        const data = await res.json();
        if (data.answer) {
          setTeacherChatMessages(prev => [...prev, { sender: 'ai', text: data.answer, timestamp: Date.now() }]);
          return;
        }
      }
      throw new Error('Local fallback');
    } catch {
      const focusTarget = activeList.find(m => m.name.toLowerCase() === teacherChatStudentFocus.toLowerCase());
      const reply = focusTarget
        ? `Telemetry for **${focusTarget.name}** in **${selectedTuitionSubject}**:\n• **Weekly Time:** ${formatDuration(sessions.filter(s => s.memberId === focusTarget.id && s.subject === selectedTuitionSubject).reduce((a, b) => a + (Number(b.duration) || 0), 0))}\n• **Problems Solved:** ${sessions.filter(s => s.memberId === focusTarget.id && s.subject === selectedTuitionSubject).reduce((a, b) => a + (Number(b.questions) || 0), 0)} Qs\n• **Pedagogical Advice:** Keep drilling high-yield JEE Advanced numericals. Assign timed sets to maintain exam readiness.`
        : `**Squad Summary in ${selectedTuitionSubject}:**\nThe squad is putting in consistent work. Check individual assignments and mock exam percentiles in the dashboard below.`;
      setTeacherChatMessages(prev => [...prev, { sender: 'ai', text: reply, timestamp: Date.now() }]);
    } finally {
      setIsTeacherChatSending(false);
    }
  };

  // Tuition Teacher AI Deep Diagnostic Report Fetcher
  const fetchTeacherAiReport = async (subject = selectedTuitionSubject) => {
    setIsLoadingTeacherAi(true);
    const activeList = members.length > 0 ? members : DEFAULT_MEMBERS;
    const curTeacher = teachers.find(t => t.id === activeTeacherId) || DEFAULT_TEACHERS.find(t => t.subject === subject) || DEFAULT_TEACHERS[0];

    const studentsTelemetry = activeList.map(m => {
      const memSessions = sessions.filter(s => s.memberId === m.id && s.subject === subject && (s.timestamp || 0) >= weekStartMs);
      const weeklyMinutes = memSessions.reduce((acc, s) => acc + (Number(s.duration) || 0), 0);
      const weeklyQuestions = memSessions.reduce((acc, s) => acc + (Number(s.questions) || 0), 0);
      
      const memExams = exams.filter(e => e.memberId === m.id);
      const recentExams = memExams.slice(0, 3).map(ex => {
        const sub = (ex.subjects || []).find((s: any) => s.name.toLowerCase() === subject.toLowerCase());
        return {
          title: ex.title,
          marks: sub?.marks ?? ex.overallMarks,
          maxMarks: sub?.maxMarks ?? ex.overallMaxMarks,
          percentile: sub?.percentile ?? ex.overallPercentile,
          rank: sub?.rank ?? ex.overallRank
        };
      });

      return {
        name: m.name,
        institute: m.institute,
        weeklyMinutes,
        weeklyQuestions,
        sessionCount: memSessions.length,
        recentExams,
        assignmentsCount: teacherAssignments.filter(a => a.subject === subject && a.submissions?.[m.id]?.status === 'graded').length
      };
    });

    try {
      const res = await fetch('/api/teacher-ai-analysis', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          teacherName: curTeacher?.name || 'Tuition Faculty',
          subject,
          tuitionName: curTeacher?.institute || 'Tuition Academy',
          students: studentsTelemetry
        })
      });

      if (res.ok) {
        const data = await res.json();
        if (data.analysis) {
          setTeacherAiReport(data.analysis);
          return;
        }
      }
      generateLocalTeacherAiReport(subject, studentsTelemetry);
    } catch (e) {
      console.warn('Teacher AI report fetch error:', e);
      generateLocalTeacherAiReport(subject, studentsTelemetry);
    } finally {
      setIsLoadingTeacherAi(false);
    }
  };

  const generateLocalTeacherAiReport = (subject: string, telemetry: any[]) => {
    const totalMins = telemetry.reduce((a, b) => a + (Number(b.weeklyMinutes) || 0), 0);
    const totalQs = telemetry.reduce((a, b) => a + (Number(b.weeklyQuestions) || 0), 0);
    const hrs = (totalMins / 60).toFixed(1);

    const students = telemetry.map(s => {
      const mins = Number(s.weeklyMinutes) || 0;
      const qs = Number(s.weeklyQuestions) || 0;
      let rating = 'Consistent';
      if (mins >= 360 || qs >= 90) rating = 'High Grind';
      else if (mins < 120 && qs < 30) rating = 'Needs Push';

      return {
        name: s.name,
        effortRating: rating,
        effortVerdict: `${s.name} logged ${(mins / 60).toFixed(1)} hrs and ${qs} practice problems in ${subject} this week.`,
        academicTrajectory: (s.recentExams && s.recentExams.length > 0)
          ? `Maintained strong standing (${s.recentExams[0].percentile || 90}%ile) in recent ${subject} mock tests.`
          : `Consistent effort logged; ready for a dedicated ${subject} timed test drill.`,
        tuitionFocus: `Focus on problem-solving speed and numerical calculation accuracy in ${subject}.`
      };
    });

    setTeacherAiReport({
      overallEffortSummary: `The squad logged a total of ${hrs} hours and solved ${totalQs} questions in ${subject} this week. Overall commitment is strong across the board.`,
      collectiveStatus: Number(hrs) >= 12 ? 'Strong Momentum' : 'Moderate Grind',
      students,
      suggestedAssignments: [
        {
          title: `${subject} Advanced Mixed Problem Set`,
          topic: 'High-Weightage Chapters',
          questionsCount: 25,
          recommendedXp: 50,
          rationale: 'Calibrates formula application under 3-minute-per-question constraints.'
        },
        {
          title: `${subject} Past Years Speed Drill`,
          topic: 'Timed Practice',
          questionsCount: 20,
          recommendedXp: 40,
          rationale: 'Reinforces speed and accuracy under test conditions.'
        }
      ],
      tuitionLessonFocus: `Focus next session on high-yield ${subject} numerical problems and calculation speed.`
    });
  };

  // Tuition Assignment Handlers
  const handleCreateTeacherAssignment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!assignTitle.trim()) {
      notify('Title Required', 'Please enter a title for the homework assignment.', 'error');
      return;
    }
    const effectiveDueDate = assignDueDate.trim() || new Date(Date.now() + 2 * 86400000).toISOString().split('T')[0];
    const basePath = `artifacts/${appId}/public/data`;
    const effectiveSubject = assignSubject === 'ALL' ? 'Math' : assignSubject;
    const fallbackTeacher = {
      id: 'teacher_' + effectiveSubject.toLowerCase(),
      name: `${effectiveSubject} Faculty`,
      subject: effectiveSubject
    };
    const curTeacher =
      currentTeacher ||
      teachers.find(t => t.id === activeTeacherId) ||
      teachers.find(t => t.subject === effectiveSubject) ||
      teachers[0] ||
      fallbackTeacher;
    const newId = 'asg_' + Date.now();
    const finalXp = assignXp.trim() === '' ? 0 : Math.max(0, Number(assignXp));
    const finalQuestions = assignHasQuestions ? (Number(assignQuestions) || 20) : 0;

    const rawNewAsg: TeacherAssignment = {
      id: newId,
      teacherId: curTeacher.id,
      teacherName: curTeacher.name,
      subject: effectiveSubject,
      title: assignTitle.trim(),
      description: assignDesc.trim(),
      hasQuestions: Boolean(assignHasQuestions),
      questionsCount: finalQuestions,
      ...(assignHasQuestions ? { questionDifficulty: assignQuestionDifficulty || 'medium' } : {}),
      xpReward: finalXp,
      doubleXpFullComplete: Boolean(assignDoubleXpFullComplete),
      dueDate: effectiveDueDate,
      assignedTo: assignTarget && assignTarget.length > 0 ? assignTarget : ['ALL'],
      requireProof: Boolean(assignRequireProof),
      refLink: assignRefLink.trim() || '',
      attachedFiles: (assignAttachedFiles || []).map(f => ({
        name: f.name || 'Attachment',
        type: f.type || 'file',
        url: f.url || '',
        size: f.size || 'File'
      })),
      archived: false,
      submissions: {},
      createdAt: Date.now()
    };

    const sanitizedAsg = JSON.parse(JSON.stringify(rawNewAsg));

    try {
      setTeacherAssignments(prev => [sanitizedAsg, ...prev]);
      await setDoc(doc(db, basePath, 'teacher_assignments', newId), sanitizedAsg, { merge: true });
      await pushActivity(
        'teacher_assign',
        `👨‍🏫 ${curTeacher.name} assigned "${sanitizedAsg.title}"`,
        `${sanitizedAsg.subject} • ${finalQuestions > 0 ? `${finalQuestions} Qs (${assignQuestionDifficulty}) • ` : ''}+${sanitizedAsg.xpReward} XP${sanitizedAsg.doubleXpFullComplete ? ' (2X Speed Bonus)' : ''} • Due: ${sanitizedAsg.dueDate}`,
        curTeacher.id,
        sanitizedAsg.xpReward
      );
      setAssignTitle('');
      setAssignDesc('');
      setAssignRefLink('');
      setAssignAttachedFiles([]);
      setAssignDueDate('');
      setAssignHasQuestions(true);
      setAssignDoubleXpFullComplete(false);
      setShowCreateAssignmentModal(false);
      notify('Homework Dispatched ✅', `Assigned "${sanitizedAsg.title}" (${sanitizedAsg.subject}) to squad.`);
    } catch (err) {
      handleFirestoreError(err, OperationType.CREATE, `${basePath}/teacher_assignments/${newId}`);
    }
  };

  const handleStartEditAssignment = (asg: TeacherAssignment) => {
    setEditingAssignmentId(asg.id);
    setEditAssignmentForm({
      id: asg.id,
      title: asg.title || '',
      subject: asg.subject || (selectedTuitionSubject === 'ALL' ? 'Math' : selectedTuitionSubject),
      description: asg.description || '',
      questionsCount: String(asg.questionsCount || 20),
      xpReward: String(asg.xpReward ?? 50),
      dueDate: asg.dueDate || new Date().toISOString().split('T')[0],
      assignedTo: asg.assignedTo || ['ALL'],
      requireProof: Boolean(asg.requireProof),
      refLink: asg.refLink || ''
    });
  };

  const handleSaveAssignmentEdit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingAssignmentId || !editAssignmentForm) return;
    const basePath = `artifacts/${appId}/public/data`;
    const updates = JSON.parse(JSON.stringify({
      title: (editAssignmentForm.title || '').trim() || 'Homework Assignment',
      subject: editAssignmentForm.subject || 'Math',
      description: (editAssignmentForm.description || '').trim(),
      questionsCount: Number(editAssignmentForm.questionsCount) || 20,
      xpReward: Number(editAssignmentForm.xpReward) || 0,
      dueDate: editAssignmentForm.dueDate || new Date().toISOString().split('T')[0],
      assignedTo: editAssignmentForm.assignedTo || ['ALL'],
      requireProof: Boolean(editAssignmentForm.requireProof),
      refLink: (editAssignmentForm.refLink || '').trim()
    }));
    try {
      setTeacherAssignments(prev =>
        prev.map(a => (a.id === editingAssignmentId ? { ...a, ...updates } : a))
      );
      await setDoc(doc(db, basePath, 'teacher_assignments', editingAssignmentId), updates, { merge: true });
      await pushActivity(
        'teacher_assign',
        `✏️ Updated Assignment: "${updates.title}"`,
        `${updates.subject} • ${updates.questionsCount} Qs • ${updates.xpReward} XP`,
        'teacher',
        0
      );
      setEditingAssignmentId(null);
      setEditAssignmentForm(null);
      notify('Assignment Updated', `Modified homework "${updates.title}".`);
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/teacher_assignments/${editingAssignmentId}`);
    }
  };

  const handleDeleteTeacherAssignment = async (asgId: string, title: string) => {
    const basePath = `artifacts/${appId}/public/data`;
    try {
      setTeacherAssignments(prev => prev.filter(a => a.id !== asgId));
      await deleteDoc(doc(db, basePath, 'teacher_assignments', asgId));
      await pushActivity(
        'admin_adjust',
        `🗑️ Teacher removed assignment "${title}"`,
        `Deleted from tuition homework desk`,
        'teacher',
        0
      );
      notify('Assignment Removed', `Deleted "${title}".`);
    } catch (err) {
      handleFirestoreError(err, OperationType.DELETE, `${basePath}/teacher_assignments/${asgId}`);
    }
  };

  const getCurrentChatIdentity = () => {
    if (activeMemberId === 'admin') {
      return { id: 'admin', name: 'Admin', type: 'admin' as const };
    }
    if (currentTeacher) {
      return { id: currentTeacher.id, name: currentTeacher.name, type: 'teacher' as const };
    }
    if (currentMember) {
      return { id: currentMember.id, name: currentMember.name, type: 'student' as const };
    }
    if (activeMemberId === 'guest') {
      return {
        id: members[0]?.id || 'demo_aarav',
        name: members[0]?.name || 'Demo Scholar',
        type: 'student' as const
      };
    }
    const fallbackMem = (members.length > 0 ? members : DEFAULT_MEMBERS).find(m => m.id === activeMemberId);
    if (fallbackMem) {
      return { id: fallbackMem.id, name: fallbackMem.name, type: 'student' as const };
    }
    return { id: activeMemberId || members[0]?.id || 'sai', name: members[0]?.name || 'Scholar', type: 'student' as const };
  };

  // Keep this device's Web Push subscription strictly bound to the currently signed-in account
  useEffect(() => {
    const resolvedId =
      activeMemberId && activeMemberId !== 'guest'
        ? activeMemberId
        : activeTeacherId || '';
    const resolvedName = currentMember?.name || currentTeacher?.name || (activeMemberId === 'admin' ? 'Admin' : '');
    if (resolvedId) {
      localStorage.setItem('jee_arena_active_member_id', resolvedId);
      if (resolvedName) {
        localStorage.setItem('jee_arena_active_member_name', resolvedName);
      }
      syncWebPushSubscription(resolvedId, resolvedName).catch(() => {});
    }
  }, [activeMemberId, activeTeacherId, currentMember?.name, currentTeacher?.name]);

  // Real-time incoming DM & Squad Chat notifications (strictly excludes sender and unrelated DM recipients)
  useEffect(() => {
    if (isGuestMode || chatMessages.length === 0) return;
    if (!activeMemberId && !activeTeacherId && !isAdminUnlocked) return;
    const myIdentity = getCurrentChatIdentity();
    const storedActiveId = localStorage.getItem('jee_arena_active_id') || localStorage.getItem('jee_arena_active_member_id') || '';
    const newest = chatMessages[chatMessages.length - 1];
    if (!newest || !newest.id) return;

    if (lastMessageIdRef.current === null) {
      chatMessages.forEach(m => notifiedChatIdsRef.current.add(m.id));
      lastMessageIdRef.current = newest.id;
      return;
    }

    if (
      lastMessageIdRef.current !== newest.id &&
      !notifiedChatIdsRef.current.has(newest.id) &&
      Date.now() - (newest.timestamp || 0) < 45000
    ) {
      notifiedChatIdsRef.current.add(newest.id);
      lastMessageIdRef.current = newest.id;

      const isFromMe =
        newest.senderId === myIdentity.id ||
        (Boolean(storedActiveId) && newest.senderId === storedActiveId) ||
        (Boolean(activeMemberId) && newest.senderId === activeMemberId) ||
        (Boolean(myIdentity.name) && newest.senderName === myIdentity.name);
      const isForMe =
        !newest.recipientId ||
        newest.recipientId === 'ALL' ||
        newest.recipientId === myIdentity.id ||
        (Boolean(storedActiveId) && newest.recipientId === storedActiveId) ||
        (isAdminUnlocked && newest.recipientId === 'admin');

      if (!isFromMe && isForMe) {
        const titlePrefix =
          !newest.recipientId || newest.recipientId === 'ALL'
            ? `💬 ${newest.senderName}`
            : `✉️ DM from ${newest.senderName}`;
        sendWebPushNotification(titlePrefix, {
          body: newest.text,
          tag: 'chat-' + newest.id
        });
        if (!showChatDrawer) {
          setToast({
            title: titlePrefix,
            detail: newest.text,
            type: 'info'
          });
          setTimeout(() => setToast(null), 4500);
        }
      }
    } else {
      lastMessageIdRef.current = newest.id;
    }
  }, [chatMessages, activeMemberId, activeTeacherId, isAdminUnlocked, showChatDrawer]);

  const handleSendRichChatMessage = async (payload: {
    text: string;
    recipientId: string;
    channelTag?: 'general' | 'doubts' | 'warfare';
    replyTo?: ChatReplyPreview | null;
    doubtSubject?: 'Physics' | 'Chemistry' | 'Math' | null;
    doubtDifficulty?: DoubtDifficulty | null;
    doubtBountyXp?: number | null;
    doubtImageUrl?: string | null;
    doubtWhatITried?: string | null;
    doubtSolutionPayload?: DoubtSolutionPayload | null;
    cardPayload?: ChatCardPayload | null;
  }) => {
    const trimmed = (payload.text || '').trim();
    if (!trimmed) return;
    const basePath = `artifacts/${appId}/public/data`;

    const identity = getCurrentChatIdentity();
    const senderId = identity.id;
    const senderName = identity.name;
    const senderType = identity.type;

    let recipientId = payload.recipientId || chatActiveChannel;
    if (recipientId === 'DMS') {
      const myDms = chatMessages.filter(
        m => m.recipientId !== 'ALL' && (m.senderId === senderId || m.recipientId === senderId)
      );
      const lastDm = myDms[myDms.length - 1];
      if (lastDm) {
        recipientId = lastDm.senderId === senderId ? lastDm.recipientId : lastDm.senderId;
      } else {
        const firstOther = (members.length > 0 ? members : DEFAULT_MEMBERS).find(m => m.id !== senderId);
        recipientId = firstOther ? firstOther.id : 'ALL';
      }
      setChatActiveChannel(recipientId);
    }

    let recipientName = 'Everyone';
    if (recipientId !== 'ALL') {
      const activeMems = members.length > 0 ? members : DEFAULT_MEMBERS;
      const activeTeachs = teachers.length > 0 ? teachers : DEFAULT_TEACHERS;
      const targetMem = activeMems.find(m => m.id === recipientId);
      const targetTeach = activeTeachs.find(t => t.id === recipientId);
      if (targetMem) recipientName = targetMem.name;
      else if (targetTeach) recipientName = targetTeach.name;
      else if (recipientId === 'admin') recipientName = 'Admin';
    }

    const nowTs = Date.now();
    const msgId = `msg_${nowTs}_${Math.random().toString(36).slice(2, 7)}`;
    notifiedChatIdsRef.current.add(msgId);

    const parsedBountyXp = payload.doubtSubject
      ? Math.min(10, Math.max(1, Math.round(Number(payload.doubtBountyXp) || 5)))
      : null;

    const msgObj: Omit<ChatMessage, 'id'> = {
      senderId,
      senderName,
      senderType,
      recipientId,
      recipientName,
      text: trimmed,
      timestamp: nowTs,
      channelTag: payload.channelTag || (payload.doubtSubject || payload.doubtSolutionPayload ? 'doubts' : 'general'),
      replyTo: payload.replyTo || null,
      reactions: {},
      pinned: false,
      editedAt: null,
      doubtSubject: payload.doubtSubject || null,
      doubtDifficulty: payload.doubtSubject ? (payload.doubtDifficulty || 'medium') : null,
      doubtBountyXp: parsedBountyXp,
      doubtImageUrl: payload.doubtImageUrl || null,
      doubtWhatITried: payload.doubtWhatITried || null,
      doubtResolved: false,
      doubtResolvedBy: null,
      doubtResolvedById: null,
      doubtAwardedXp: null,
      doubtSolutionMsgId: null,
      doubtSolutionPayload: payload.doubtSolutionPayload || null,
      cardPayload: payload.cardPayload || null
    };

    const fullMsg: ChatMessage = { id: msgId, ...msgObj };
    setChatMessages(prev => {
      const exists = prev.some(m => m.id === msgId);
      return exists ? prev : [...prev, fullMsg];
    });

    try {
      if (!isGuestMode) {
        await setDoc(doc(db, basePath, 'messages', msgId), msgObj);
      }
      if (recipientId === 'ALL') {
        if (payload.doubtSolutionPayload) {
          await pushActivity(
            'doubt_solution',
            `🧠 ${senderName} posted an Organic Peer Solution for ${payload.doubtSolutionPayload.doubtSenderName}'s ${payload.doubtSolutionPayload.subject} Doubt (+${payload.doubtSolutionPayload.bountyXp} XP Bounty)`,
            payload.doubtSolutionPayload.handwrittenImageUrl
              ? '✍️ Verified with Handwritten Notebook Photo • Zero AI'
              : `💡 Core Trick: "${payload.doubtSolutionPayload.coreTrick.slice(0, 80)}"`,
            senderId,
            0
          );
          notify(
            '🧠 Organic Solution Posted!',
            `Ready for ${payload.doubtSolutionPayload.doubtSenderName} to accept & award +${payload.doubtSolutionPayload.bountyXp} XP.`
          );
        } else if (payload.doubtSubject) {
          const diffCfg = DOUBT_DIFFICULTY_CONFIG[payload.doubtDifficulty || 'medium'];
          await pushActivity(
            'doubt_posted',
            `❓ ${senderName} posted a ${diffCfg.shortLabel} ${payload.doubtSubject} Doubt (+${parsedBountyXp} XP Bounty)`,
            `"${msgObj.text.slice(0, 90)}"`,
            senderId,
            0
          );
          notify(
            `❓ ${payload.doubtSubject} Doubt Live (+${parsedBountyXp} XP)`,
            'Squadmates can now solve it organically in #doubts for XP!'
          );
        }
      } else {
        notify('Direct Message Sent', `Delivered to ${recipientName}`);
      }
    } catch (err) {
      handleFirestoreError(err, OperationType.CREATE, `${basePath}/messages/${msgId}`);
    }
  };

  const handleDeleteChatMessage = async (msgId: string) => {
    const basePath = `artifacts/${appId}/public/data`;
    setChatMessages(prev => prev.filter(m => m.id !== msgId));
    if (isGuestMode) return;
    try {
      await deleteDoc(doc(db, basePath, 'messages', msgId));
    } catch (err) {
      handleFirestoreError(err, OperationType.DELETE, `${basePath}/messages/${msgId}`);
    }
  };

  const handleEditChatMessage = async (msgId: string, newText: string) => {
    const basePath = `artifacts/${appId}/public/data`;
    const editedAt = Date.now();
    setChatMessages(prev =>
      prev.map(m => (m.id === msgId ? { ...m, text: newText, editedAt } : m))
    );
    if (isGuestMode) return;
    try {
      await updateDoc(doc(db, basePath, 'messages', msgId), { text: newText, editedAt });
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/messages/${msgId}`);
    }
  };

  const handleToggleChatReaction = async (msgId: string, emoji: string) => {
    const basePath = `artifacts/${appId}/public/data`;
    const userId = getCurrentChatIdentity().id;
    const targetMsg = chatMessages.find(m => m.id === msgId);
    if (!targetMsg) return;

    const currentReactions = { ...(targetMsg.reactions || {}) };
    const existingList = Array.isArray(currentReactions[emoji]) ? [...currentReactions[emoji]] : [];
    const nextList = existingList.includes(userId)
      ? existingList.filter(id => id !== userId)
      : [...existingList, userId];

    if (nextList.length === 0) {
      delete currentReactions[emoji];
    } else {
      currentReactions[emoji] = nextList;
    }

    setChatMessages(prev =>
      prev.map(m => (m.id === msgId ? { ...m, reactions: currentReactions } : m))
    );
    if (isGuestMode) return;
    try {
      await updateDoc(doc(db, basePath, 'messages', msgId), { reactions: currentReactions });
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/messages/${msgId}`);
    }
  };

  const handleTogglePinChatMessage = async (msgId: string, nextPinned: boolean) => {
    const basePath = `artifacts/${appId}/public/data`;
    setChatMessages(prev =>
      prev.map(m => (m.id === msgId ? { ...m, pinned: nextPinned } : m))
    );
    if (isGuestMode) {
      notify(nextPinned ? '📌 Message Pinned' : 'Message Unpinned', nextPinned ? 'Added to channel pinned banner.' : 'Removed from pinned banner.');
      return;
    }
    try {
      await updateDoc(doc(db, basePath, 'messages', msgId), { pinned: nextPinned });
      notify(nextPinned ? '📌 Message Pinned' : 'Message Unpinned', nextPinned ? 'Added to channel pinned banner.' : 'Removed from pinned banner.');
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/messages/${msgId}`);
    }
  };

  const handleToggleDoubtResolved = async (
    msgId: string,
    nextResolved: boolean,
    options?: ResolveDoubtAwardOptions
  ) => {
    const basePath = `artifacts/${appId}/public/data`;
    const targetDoubt = chatMessages.find(m => m.id === msgId);
    if (!targetDoubt) return;

    const identity = getCurrentChatIdentity();
    const activeList = membersLiveRef.current.length > 0 ? membersLiveRef.current : (isGuestMode ? members : DEFAULT_MEMBERS);

    if (nextResolved) {
      // Prevent double-awarding if already resolved
      if (targetDoubt.doubtResolved) return;

      const rawSolverId = options?.resolverMemberId || null;
      const isSelfSolved = !rawSolverId || rawSolverId === targetDoubt.senderId;
      const solverMember = rawSolverId ? activeList.find(m => m.id === rawSolverId) : null;
      const resolverName =
        options?.resolverName ||
        solverMember?.name ||
        (isSelfSolved ? `${targetDoubt.senderName} (Self)` : identity.name);

      const clampedXp =
        !isSelfSolved && solverMember
          ? Math.min(10, Math.max(1, Math.round(Number(options?.xpReward ?? targetDoubt.doubtBountyXp ?? 5))))
          : 0;

      const solutionMsgId = options?.solutionMsgId || null;

      setChatMessages(prev =>
        prev.map(m =>
          m.id === msgId
            ? {
                ...m,
                doubtResolved: true,
                doubtResolvedBy: resolverName,
                doubtResolvedById: solverMember ? solverMember.id : null,
                doubtAwardedXp: clampedXp,
                doubtSolutionMsgId: solutionMsgId
              }
            : m
        )
      );

      try {
        if (!isGuestMode) {
          await updateDoc(doc(db, basePath, 'messages', msgId), {
            doubtResolved: true,
            doubtResolvedBy: resolverName,
            doubtResolvedById: solverMember ? solverMember.id : null,
            doubtAwardedXp: clampedXp,
            doubtSolutionMsgId: solutionMsgId
          });
        }

        if (solverMember && clampedXp > 0) {
          const nextCount = (Number(solverMember.doubtsResolvedCount) || 0) + 1;
          const nextEarned = (Number(solverMember.doubtXpEarned) || 0) + clampedXp;
          await adjustMemberActiveSprintXp(solverMember.id, clampedXp, {
            doubtsResolvedCount: nextCount,
            doubtXpEarned: nextEarned
          });

          const diffLabel =
            DOUBT_DIFFICULTY_CONFIG[targetDoubt.doubtDifficulty || 'medium']?.shortLabel || 'Peer';
          await pushActivity(
            'doubt_resolved',
            `🧠 ${solverMember.name} resolved ${targetDoubt.senderName}'s ${diffLabel} ${targetDoubt.doubtSubject || 'PCM'} Doubt (+${clampedXp} XP)`,
            `Organic Peer Solution Verified (No AI) • Total Doubts Solved: ${nextCount}`,
            solverMember.id,
            clampedXp
          );

          notify(
            `🧠 Doubt Resolved! +${clampedXp} XP to ${solverMember.name}`,
            `Credited +${clampedXp} XP for resolving ${targetDoubt.senderName}'s ${targetDoubt.doubtSubject || ''} doubt organically.`
          );
        } else {
          notify('Doubt Marked Resolved', 'Closed without XP payout (self-resolved).');
        }
      } catch (err) {
        handleFirestoreError(err, OperationType.UPDATE, `${basePath}/messages/${msgId}`);
      }
    } else {
      // Un-resolving a doubt reverses any previously awarded XP so it cannot be farmed
      const prevSolverId = targetDoubt.doubtResolvedById;
      const prevAwardedXp = Number(targetDoubt.doubtAwardedXp) || 0;

      setChatMessages(prev =>
        prev.map(m =>
          m.id === msgId
            ? {
                ...m,
                doubtResolved: false,
                doubtResolvedBy: null,
                doubtResolvedById: null,
                doubtAwardedXp: null,
                doubtSolutionMsgId: null
              }
            : m
        )
      );

      try {
        if (!isGuestMode) {
          await updateDoc(doc(db, basePath, 'messages', msgId), {
            doubtResolved: false,
            doubtResolvedBy: null,
            doubtResolvedById: null,
            doubtAwardedXp: null,
            doubtSolutionMsgId: null
          });
        }

        if (prevSolverId && prevAwardedXp > 0) {
          const prevSolver = activeList.find(m => m.id === prevSolverId);
          if (prevSolver) {
            const nextCount = Math.max(0, (Number(prevSolver.doubtsResolvedCount) || 1) - 1);
            const nextEarned = Math.max(0, (Number(prevSolver.doubtXpEarned) || prevAwardedXp) - prevAwardedXp);
            await adjustMemberActiveSprintXp(prevSolver.id, -prevAwardedXp, {
              doubtsResolvedCount: nextCount,
              doubtXpEarned: nextEarned
            });
          }
        }
        notify('Doubt Re-Opened', 'Doubt marked unresolved.');
      } catch (err) {
        handleFirestoreError(err, OperationType.UPDATE, `${basePath}/messages/${msgId}`);
      }
    }
  };

  const handleTeacherAdjustStudentXp = async (e: React.FormEvent) => {
    e.preventDefault();
    const basePath = `artifacts/${appId}/public/data`;
    const activeList = members.length > 0 ? members : DEFAULT_MEMBERS;
    const targetStudent = activeList.find(m => m.id === teacherXpTargetStudentId);
    if (!targetStudent) return;

    const rawVal = Math.abs(Number(teacherXpAmount) || 0);
    if (rawVal === 0) return;
    const delta = teacherXpIsDeduction ? -rawVal : rawVal;
    const currentBonus = isCycle5Active
      ? (Number(targetStudent.cycle5BonusXp) || 0)
      : isCycle4Active
      ? (Number(targetStudent.cycle4BonusXp) || 0)
      : (Number(targetStudent.bonusXp) || 0);
    const newBonus = currentBonus + delta;

    const curTeacher = currentTeacher || teachers.find(t => t.id === activeTeacherId);
    const teacherName = curTeacher?.name || 'Tuition Teacher';

    try {
      const bonusUpdates = isCycle5Active
        ? { cycle5BonusXp: newBonus }
        : isCycle4Active
        ? { cycle4BonusXp: newBonus }
        : { bonusXp: newBonus };
      membersLiveRef.current = membersLiveRef.current.map(m => m.id === targetStudent.id ? { ...m, ...bonusUpdates } : m);
      setMembers(prev => prev.map(m => m.id === targetStudent.id ? { ...m, ...bonusUpdates } : m));
      await updateDoc(doc(db, basePath, 'members', targetStudent.id), bonusUpdates);
      await pushActivity(
        delta > 0 ? 'admin_adjust' : 'penalty',
        `👨‍🏫 ${teacherName} ${delta > 0 ? `awarded +${delta}` : `deducted ${delta}`} XP (${targetStudent.name})`,
        teacherXpReason.trim() || `${selectedTuitionSubject} Tuition Evaluation`,
        targetStudent.id,
        delta
      );
      setShowTeacherXpModal(false);
      setTeacherXpAmount('25');
      setTeacherXpReason('');
      notify(delta > 0 ? 'XP Awarded' : 'XP Deducted', `${delta > 0 ? '+' : ''}${delta} XP for ${targetStudent.name}.`);
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/members/${targetStudent.id}`);
    }
  };

  const handleOpenStudentSubmission = (asg: TeacherAssignment, mode: 'submit_solution' | 'submit_excuse' = 'submit_solution') => {
    setActiveAssignmentAction(asg);
    setAssignmentActionMode(mode);
    setSubmissionInputTab('all');
    const myId = (activeMemberId && activeMemberId !== 'admin' && !activeMemberId.startsWith('teacher_'))
      ? activeMemberId
      : (currentMember?.id || 'sai');
    const mySub = asg.submissions?.[myId];
    if (mySub) {
      setStudentHomeworkAttachedFiles(mySub.attachedFiles || []);
      setStudentHomeworkProofImages(mySub.proofImages || []);
      setStudentHomeworkResourceLinks((mySub as any).resourceLinks || []);
      setStudentHomeworkNote(mySub.note?.replace(/^(Incomplete )?Excuse:\s*/i, '') || '');
      if (mode === 'submit_excuse' && mySub.note) {
        setStudentExcuseReason(mySub.note.replace(/^(Incomplete )?Excuse:\s*/i, ''));
      }
    } else {
      setStudentHomeworkAttachedFiles([]);
      setStudentHomeworkProofImages([]);
      setStudentHomeworkResourceLinks([]);
      setStudentHomeworkNote('');
      setStudentExcuseReason('');
    }
    setNewResourceLinkInput('');
  };

  const handleAddResourceLink = () => {
    if (!newResourceLinkInput.trim()) return;
    let url = newResourceLinkInput.trim();
    if (!url.startsWith('http://') && !url.startsWith('https://')) {
      url = 'https://' + url;
    }
    setStudentHomeworkResourceLinks(prev => (prev.includes(url) ? prev : [...prev, url]));
    setNewResourceLinkInput('');
  };

  const handleRemoveResourceLink = (idx: number) => {
    setStudentHomeworkResourceLinks(prev => prev.filter((_, i) => i !== idx));
  };

  const handleStudentSubmitHomework = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (isSubmittingAssignmentAction) return;

    const studentId = (activeMemberId && activeMemberId !== 'admin' && !activeMemberId.startsWith('teacher_'))
      ? activeMemberId
      : (currentMember?.id || 'sai');

    if (!activeAssignmentAction) {
      notify('No Assignment Selected', 'Please select an active homework assignment.', 'error');
      return;
    }

    setIsSubmittingAssignmentAction(true);

    try {
      // Auto-include typed link if user filled input but didn't click "+ Add Link"
      const finalLinks = [...studentHomeworkResourceLinks];
      if (newResourceLinkInput.trim()) {
        let url = newResourceLinkInput.trim();
        if (!url.startsWith('http://') && !url.startsWith('https://')) {
          url = 'https://' + url;
        }
        if (!finalLinks.includes(url)) {
          finalLinks.push(url);
        }
        setNewResourceLinkInput('');
      }

      // Separate any 'link' type items added inside AssignmentAttachmentUploader into finalLinks as well
      for (const f of studentHomeworkAttachedFiles) {
        if (f.type === 'link' && f.url && !finalLinks.includes(f.url)) {
          finalLinks.push(f.url);
        }
      }

      // Compress any image attachments and proof URLs to prevent Firestore 1MB document limit
      const compressedFiles = await Promise.all(
        studentHomeworkAttachedFiles.map(async (f) => {
          let fileUrl = f.url || '';
          if (f.type === 'image' && fileUrl.startsWith('data:image')) {
            try {
              fileUrl = await compressDataUrl(fileUrl, 800, 0.55);
            } catch (compErr) {
              console.warn('Image compression fallback:', compErr);
            }
          }
          return {
            name: f.name || 'Homework_Attachment',
            type: f.type || 'file',
            url: fileUrl,
            size: f.size || 'Attachment'
          };
        })
      );

      const compressedProofs = await Promise.all(
        studentHomeworkProofImages.map(async (imgUrl) => {
          if (imgUrl && imgUrl.startsWith('data:image')) {
            try {
              return await compressDataUrl(imgUrl, 800, 0.55);
            } catch {
              return imgUrl;
            }
          }
          return imgUrl || '';
        })
      );

      const basePath = `artifacts/${appId}/public/data`;
      const asg = activeAssignmentAction;
      const updatedSubs: Record<string, any> = { ...(asg.submissions || {}) };
      const activeList = members.length > 0 ? members : DEFAULT_MEMBERS;
      const targetMem =
        activeList.find(m => m.id === studentId) ||
        DEFAULT_MEMBERS.find(m => m.id === studentId) || {
          id: studentId,
          name: studentId === 'sai' ? 'Sai' : studentId === 'utham_940' ? 'Utham' : 'Ved'
        };

      const existingSub = updatedSubs[studentId];
      const summaryParts: string[] = [];
      if (studentHomeworkNote.trim()) summaryParts.push('Typed response');
      if (compressedFiles.length + compressedProofs.length > 0) {
        summaryParts.push(`${compressedFiles.length + compressedProofs.length} file(s)`);
      }
      if (finalLinks.length > 0) {
        summaryParts.push(`${finalLinks.length} link(s)`);
      }

      const defaultNoteText =
        summaryParts.length > 0
          ? `Submitted ${summaryParts.join(', ')} for faculty review.`
          : 'Completed homework and submitted for faculty review.';

      updatedSubs[studentId] = {
        submittedAt: Date.now(),
        proofImages: compressedProofs,
        attachedFiles: compressedFiles,
        resourceLinks: finalLinks,
        note: studentHomeworkNote.trim() || defaultNoteText,
        status: existingSub?.status === 'graded' ? 'graded' : 'pending',
        marksAwarded: existingSub?.marksAwarded ?? 0,
        maxMarks: existingSub?.maxMarks ?? (Number(asg.questionsCount) || 20),
        xpAwarded: existingSub?.xpAwarded ?? 0,
        feedback:
          existingSub?.status === 'graded'
            ? (existingSub.feedback || 'Resubmitted updated solution.')
            : 'Submitted to Faculty Queue. Awaiting teacher review & grading.'
      };

      // Payload safety guard: ensures Firestore document write NEVER fails even with large PDFs/files
      const serializedCheck = JSON.stringify(updatedSubs);
      if (serializedCheck.length > 800000) {
        updatedSubs[studentId].attachedFiles = compressedFiles.map(f => {
          if (f.url && f.url.length > 200000 && f.type !== 'image') {
            return { ...f, url: '', size: `${f.size} (Stored Locally)` };
          }
          return f;
        });
      }

      const cleanSubmissions = JSON.parse(JSON.stringify(updatedSubs));
      const fullAssignmentDoc = JSON.parse(
        JSON.stringify({
          ...asg,
          submissions: cleanSubmissions
        })
      );

      // Immediately update local React state so UI reflects the submission right away
      setTeacherAssignments(prev => {
        const exists = prev.some(item => item.id === asg.id);
        if (exists) {
          return prev.map(item => (item.id === asg.id ? { ...item, submissions: cleanSubmissions } : item));
        }
        return [fullAssignmentDoc, ...prev];
      });

      // Persist to Firestore using setDoc with merge: true so it never fails even if doc wasn't created yet
      await setDoc(doc(db, basePath, 'teacher_assignments', asg.id), fullAssignmentDoc, { merge: true });

      await pushActivity(
        'task_complete',
        `📤 ${targetMem.name} submitted solution for "${asg.title}" (${asg.subject})`,
        `${summaryParts.length > 0 ? summaryParts.join(' • ') : 'Solution submitted'} - Awaiting faculty grading`,
        targetMem.id,
        0
      );

      setActiveAssignmentAction(null);
      setStudentHomeworkProofImages([]);
      setStudentHomeworkAttachedFiles([]);
      setStudentHomeworkResourceLinks([]);
      setNewResourceLinkInput('');
      setStudentHomeworkNote('');
      notify(
        'Homework Submitted to Faculty! ✅',
        `Your ${asg.subject} solution (${summaryParts.join(', ') || 'complete'}) is now in the teacher review queue.`
      );
    } catch (err) {
      console.error('Homework submission error:', err);
      handleFirestoreError(err, OperationType.UPDATE, `artifacts/${appId}/public/data/teacher_assignments/${activeAssignmentAction.id}`);
    } finally {
      setIsSubmittingAssignmentAction(false);
    }
  };

  const handleStudentSubmitExcuse = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (isSubmittingAssignmentAction) return;

    const studentId = (activeMemberId && activeMemberId !== 'admin' && !activeMemberId.startsWith('teacher_'))
      ? activeMemberId
      : (currentMember?.id || 'sai');

    if (!activeAssignmentAction || !studentExcuseReason.trim()) {
      notify('Excuse Reason Required', 'Please enter a valid reason for incompletion.', 'error');
      return;
    }

    setIsSubmittingAssignmentAction(true);

    const basePath = `artifacts/${appId}/public/data`;
    const asg = activeAssignmentAction;
    const updatedSubs: Record<string, any> = { ...(asg.submissions || {}) };
    const activeList = members.length > 0 ? members : DEFAULT_MEMBERS;
    const targetMem =
      activeList.find(m => m.id === studentId) ||
      DEFAULT_MEMBERS.find(m => m.id === studentId) || {
        id: studentId,
        name: studentId === 'sai' ? 'Sai' : studentId === 'utham_940' ? 'Utham' : 'Ved'
      };

    updatedSubs[studentId] = {
      submittedAt: Date.now(),
      note: `Incomplete Excuse: ${studentExcuseReason.trim()}`,
      status: 'pending',
      feedback: `Reason: "${studentExcuseReason.trim()}" (Awaiting teacher review)`,
      xpAwarded: 0
    };

    const cleanSubmissions = JSON.parse(JSON.stringify(updatedSubs));
    const fullAssignmentDoc = JSON.parse(
      JSON.stringify({
        ...asg,
        submissions: cleanSubmissions
      })
    );

    try {
      setTeacherAssignments(prev =>
        prev.map(item => (item.id === asg.id ? { ...item, submissions: cleanSubmissions } : item))
      );
      await setDoc(doc(db, basePath, 'teacher_assignments', asg.id), fullAssignmentDoc, { merge: true });
      await pushActivity(
        'penalty',
        `⚠️ ${targetMem.name} filed excuse for "${asg.title}"`,
        `Reason: "${studentExcuseReason.trim()}" (Teacher must approve to waive penalty)`,
        targetMem.id,
        0
      );
      setActiveAssignmentAction(null);
      setStudentExcuseReason('');
      notify('Excuse Submitted', 'Tuition teacher will review to approve or choose XP penalty.');
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/teacher_assignments/${asg.id}`);
    } finally {
      setIsSubmittingAssignmentAction(false);
    }
  };

  const handleTeacherReviewExcuse = async (assignmentId: string, studentId: string, approve: boolean, penaltyXp: number, feedback: string) => {
    const basePath = `artifacts/${appId}/public/data`;
    const asg = teacherAssignments.find(a => a.id === assignmentId);
    const student = members.find(m => m.id === studentId) || DEFAULT_MEMBERS.find(m => m.id === studentId);
    if (!asg || !student) return;

    const updatedSubs: Record<string, any> = { ...(asg.submissions || {}) };
    const curSub = updatedSubs[studentId] || { submittedAt: Date.now() };

    if (approve) {
      updatedSubs[studentId] = {
        ...curSub,
        status: 'graded',
        feedback: feedback.trim() || 'Teacher approved absence/excuse. Protected from XP penalty.',
        marksAwarded: 0,
        maxMarks: Number(asg.questionsCount) || 20,
        xpAwarded: 0
      };
      const cleanSubmissions = JSON.parse(JSON.stringify(updatedSubs));
      try {
        setTeacherAssignments(prev =>
          prev.map(item => (item.id === asg.id ? { ...item, submissions: cleanSubmissions } : item))
        );
        await setDoc(doc(db, basePath, 'teacher_assignments', asg.id), { submissions: cleanSubmissions }, { merge: true });
        await pushActivity(
          'admin_adjust',
          `✅ ${asg.teacherName} approved excuse for ${student.name}`,
          `Excused from "${asg.title}" without penalty.`,
          student.id,
          0
        );
        setReviewingAssignment(null);
        setReviewingStudentId(null);
        notify('Excuse Approved', `${student.name} is excused without penalty.`);
      } catch (err) {
        handleFirestoreError(err, OperationType.UPDATE, `${basePath}/teacher_assignments/${asg.id}`);
      }
    } else {
      const deduction = Math.max(0, penaltyXp);
      updatedSubs[studentId] = {
        ...curSub,
        status: 'overdue_penalized',
        feedback: `Rejected: Unexcused homework incompletion (-${deduction} XP penalty applied). ${feedback.trim()}`,
        marksAwarded: 0,
        maxMarks: Number(asg.questionsCount) || 20,
        xpAwarded: -deduction
      };
      const cleanSubmissions = JSON.parse(JSON.stringify(updatedSubs));
      try {
        setTeacherAssignments(prev =>
          prev.map(item => (item.id === asg.id ? { ...item, submissions: cleanSubmissions } : item))
        );
        await setDoc(doc(db, basePath, 'teacher_assignments', asg.id), { submissions: cleanSubmissions }, { merge: true });
        if (deduction > 0) {
          const currentBonus = isCycle5Active
            ? (Number(student.cycle5BonusXp) || 0)
            : isCycle4Active
            ? (Number(student.cycle4BonusXp) || 0)
            : (Number(student.bonusXp) || 0);
          const bonusUpdates = isCycle5Active
            ? { cycle5BonusXp: currentBonus - deduction }
            : isCycle4Active
            ? { cycle4BonusXp: currentBonus - deduction }
            : { bonusXp: currentBonus - deduction };
          membersLiveRef.current = membersLiveRef.current.map(m => m.id === student.id ? { ...m, ...bonusUpdates } : m);
          setMembers(prev => prev.map(m => m.id === student.id ? { ...m, ...bonusUpdates } : m));
          await updateDoc(doc(db, basePath, 'members', student.id), bonusUpdates);
        }
        await pushActivity(
          'penalty',
          `🚫 ${asg.teacherName} rejected excuse & penalized ${student.name} (-${deduction} XP)`,
          `Unexcused failure to complete "${asg.title}". Feedback: ${feedback.trim() || 'Incomplete work'}`,
          student.id,
          -deduction
        );
        setReviewingAssignment(null);
        setReviewingStudentId(null);
        notify('Penalty Applied', `Deducted ${deduction} XP from ${student.name}.`);
      } catch (err) {
        handleFirestoreError(err, OperationType.UPDATE, `${basePath}/teacher_assignments/${asg.id}`);
      }
    }
  };

  const handleTeacherGradeHomework = async (
    assignmentId: string,
    studentId: string,
    marks: number,
    maxMarks: number,
    xp: number,
    feedback: string,
    questionsAttempted?: number,
    questionsCorrect?: number,
    isCompleted?: boolean
  ) => {
    const basePath = `artifacts/${appId}/public/data`;
    const asg = teacherAssignments.find(a => a.id === assignmentId);
    const student = members.find(m => m.id === studentId) || DEFAULT_MEMBERS.find(m => m.id === studentId);
    if (!asg || !student) return;

    const updatedSubs: Record<string, any> = { ...(asg.submissions || {}) };
    const curSub = updatedSubs[studentId] || { submittedAt: Date.now() };
    const previousXp = Number(curSub.xpAwarded) || 0;
    const deltaXp = xp - previousXp;
    const curTeacher = currentTeacher || teachers.find(t => t.id === activeTeacherId);
    const teacherLabel = curTeacher ? curTeacher.name : (isAdminUnlocked || activeMemberId === 'admin' ? 'Faculty Admin' : 'Tuition Teacher');

    updatedSubs[studentId] = {
      ...curSub,
      status: 'graded',
      gradedBy: teacherLabel,
      marksAwarded: Number(marks) || 0,
      maxMarks: Number(maxMarks) || Number(asg.questionsCount) || 20,
      xpAwarded: Number(xp) || 0,
      feedback: feedback.trim() || `Verified by ${teacherLabel}. Scored ${marks}/${maxMarks}.`,
      questionsAttempted: questionsAttempted !== undefined ? Number(questionsAttempted) : (Number(asg.questionsCount) || 0),
      questionsCorrect: questionsCorrect !== undefined ? Number(questionsCorrect) : (Number(marks) || 0),
      isTaskFullyCompleted: isCompleted !== undefined ? Boolean(isCompleted) : true
    };

    const cleanSubmissions = JSON.parse(JSON.stringify(updatedSubs));

    try {
      setTeacherAssignments(prev =>
        prev.map(item => (item.id === asg.id ? { ...item, submissions: cleanSubmissions } : item))
      );
      await setDoc(doc(db, basePath, 'teacher_assignments', asg.id), { submissions: cleanSubmissions }, { merge: true });
      if (deltaXp !== 0) {
        const currentBonus = isCycle5Active
          ? (Number(student.cycle5BonusXp) || 0)
          : isCycle4Active
          ? (Number(student.cycle4BonusXp) || 0)
          : (Number(student.bonusXp) || 0);
        const bonusUpdates = isCycle5Active
          ? { cycle5BonusXp: currentBonus + deltaXp }
          : isCycle4Active
          ? { cycle4BonusXp: currentBonus + deltaXp }
          : { bonusXp: currentBonus + deltaXp };
        membersLiveRef.current = membersLiveRef.current.map(m => m.id === student.id ? { ...m, ...bonusUpdates } : m);
        setMembers(prev => prev.map(m => m.id === student.id ? { ...m, ...bonusUpdates } : m));
        await updateDoc(doc(db, basePath, 'members', student.id), bonusUpdates);
      }
      await pushActivity(
        'task_complete',
        `👨‍🏫 ${teacherLabel} graded ${student.name}'s homework for "${asg.title}" (${xp >= 0 ? `+${xp}` : xp} XP)`,
        `Scored ${marks}/${maxMarks} marks • Feedback: "${feedback.trim() || 'Reviewed'}"`,
        student.id,
        xp
      );
      setReviewingAssignment(null);
      setReviewingStudentId(null);
      notify('Grade Saved & Feedback Sent! ✅', `${xp >= 0 ? `Awarded +${xp}` : `Deducted ${xp}`} XP for ${student.name}.`);
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/teacher_assignments/${asg.id}`);
    }
  };

