  // Admin Roster & Details
  const handleStartEditMember = (m: Member) => {
    setEditingMemberId(m.id);
    setEditMemberForm({
      name: m.name,
      institute: m.institute || 'Modulus',
      passcode: String(m.passcode || '1111'),
      bonusXp: isCycle5Active
        ? (Number(m.cycle5BonusXp) || 0)
        : isCycle4Active
        ? (Number(m.cycle4BonusXp) || 0)
        : (Number(m.bonusXp) || 0),
      manualMinutesOffset: isCycle5Active
        ? (Number(m.cycle5ManualMinutesOffset) || 0)
        : isCycle4Active
        ? (Number(m.cycle4ManualMinutesOffset) || 0)
        : (Number(m.manualMinutesOffset) || 0)
    });
  };

  const handleSaveMemberEdit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMemberId) return;
    const basePath = `artifacts/${appId}/public/data`;
    const nextBonusXp = Number(editMemberForm.bonusXp) || 0;
    const nextMinsOffset = Number(editMemberForm.manualMinutesOffset) || 0;
    const existingMem = membersLiveRef.current.find(m => m.id === editingMemberId) || members.find(m => m.id === editingMemberId);
    const prevBonus = existingMem
      ? (isCycle5Active
          ? (Number(existingMem.cycle5BonusXp) || 0)
          : isCycle4Active
          ? (Number(existingMem.cycle4BonusXp) || 0)
          : (Number(existingMem.bonusXp) || 0))
      : 0;
    const xpDiff = existingMem ? nextBonusXp - prevBonus : 0;
    const updatedFields: Record<string, any> = {
      name: editMemberForm.name.trim(),
      institute: editMemberForm.institute.trim(),
      passcode: editMemberForm.passcode.trim(),
      ...(isCycle5Active
        ? { cycle5BonusXp: nextBonusXp, cycle5ManualMinutesOffset: nextMinsOffset }
        : isCycle4Active
        ? { cycle4BonusXp: nextBonusXp, cycle4ManualMinutesOffset: nextMinsOffset }
        : { bonusXp: nextBonusXp, manualMinutesOffset: nextMinsOffset })
    };
    try {
      membersLiveRef.current = membersLiveRef.current.map(m => m.id === editingMemberId ? { ...m, ...updatedFields } : m);
      setMembers(prev => prev.map(m => m.id === editingMemberId ? { ...m, ...updatedFields } : m));
      await updateDoc(doc(db, basePath, 'members', editingMemberId), updatedFields);
      if (xpDiff !== 0) {
        await pushActivity(
          xpDiff < 0 ? 'penalty' : 'admin_adjust',
          `Admin updated ${updatedFields.name}: Bonus XP set to ${nextBonusXp >= 0 ? '+' : ''}${nextBonusXp} XP`,
          'Squad Roster direct edit',
          editingMemberId,
          xpDiff
        );
      }
      setEditingMemberId(null);
      notify('Member Updated', `Saved changes for ${editMemberForm.name}`);
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/members/${editingMemberId}`);
    }
  };

