  const handleAddMember = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMemberName.trim() || newMemberPin.length !== 4) return;
    const basePath = `artifacts/${appId}/public/data`;
    const id = newMemberName.trim().toLowerCase().replace(/[^a-z0-9]/g, '') + '_' + Date.now().toString().slice(-3);

    let startingXp = 0;
    let baselineLabel = '0 XP Clean Slate';
    if (newMemberInitialXpMode === 'match_lowest') {
      startingXp = Math.max(0, lowestSquadXp);
      baselineLabel = `Matched lowest active member (${startingXp} XP)`;
    } else if (newMemberInitialXpMode === 'squad_avg') {
      startingXp = Math.max(0, avgSquadXp);
      baselineLabel = `Squad average catch-up baseline (${startingXp} XP)`;
    } else if (newMemberInitialXpMode === 'custom') {
      startingXp = Math.max(0, Number(newMemberCustomXp) || 0);
      baselineLabel = `Custom calibrated baseline (${startingXp} XP)`;
    }

    const newMemberDoc: Member = {
      id,
      name: newMemberName.trim(),
      institute: newMemberInst.trim() || 'Modulus',
      passcode: newMemberPin,
      bonusXp: (!isCycle4Active && !isCycle5Active) ? startingXp : 0,
      manualMinutesOffset: 0,
      cycle4BonusXp: (isCycle4Active && !isCycle5Active) ? startingXp : 0,
      cycle4ManualMinutesOffset: 0,
      cycle5BonusXp: isCycle5Active ? startingXp : 0,
      cycle5ManualMinutesOffset: 0,
      isGrinding: false,
      grindingSubject: '',
      grindingStartedAt: null
    };

    try {
      membersLiveRef.current = [...membersLiveRef.current, newMemberDoc];
      setMembers(prev => [...prev, newMemberDoc]);
      await setDoc(doc(db, basePath, 'members', id), newMemberDoc);

      await pushActivity(
        'admin_adjust',
        `👤 Welcomed ${newMemberName.trim()} to squad (${startingXp > 0 ? `+${startingXp} XP baseline` : '0 XP start'})`,
        `Fair entry calibration: ${baselineLabel}${startingXp === 0 ? ' • Underdog 1.25x boost active!' : ''}`,
        id,
        startingXp
      );

      setNewMemberName('');
      setNewMemberPin('');
      setNewMemberCustomXp('');
      notify('Member Added', `${newMemberName} added with ${startingXp} starting XP (${baselineLabel}).`);
    } catch (err) {
      handleFirestoreError(err, OperationType.CREATE, `${basePath}/members/${id}`);
    }
  };

  const handleApproveSignupRequest = async (member: Member) => {
    const basePath = `artifacts/${appId}/public/data`;
    const mode = approvalXpModeByMember[member.id] || 'match_lowest';
    const customRaw = approvalCustomXpByMember[member.id] || '0';

    let startingXp = 0;
    let baselineLabel = '0 XP Clean Slate';
    if (mode === 'match_lowest') {
      startingXp = Math.max(0, lowestSquadXp);
      baselineLabel = `Matched lowest active scholar (${startingXp} XP)`;
    } else if (mode === 'squad_avg') {
      startingXp = Math.max(0, avgSquadXp);
      baselineLabel = `Squad average catch-up baseline (${startingXp} XP)`;
    } else if (mode === 'custom') {
      startingXp = Math.max(0, Number(customRaw) || 0);
      baselineLabel = `Custom calibrated baseline (${startingXp} XP)`;
    }

    try {
      const approvalUpdates = {
        approvalStatus: 'approved' as const,
        ...(isCycle5Active
          ? { cycle5BonusXp: startingXp }
          : isCycle4Active
          ? { cycle4BonusXp: startingXp }
          : { bonusXp: startingXp })
      };
      membersLiveRef.current = membersLiveRef.current.map(m =>
        m.id === member.id ? { ...m, ...approvalUpdates } : m
      );
      setMembers(prev =>
        prev.map(m =>
          m.id === member.id
            ? { ...m, ...approvalUpdates }
            : m
        )
      );
      await updateDoc(doc(db, basePath, 'members', member.id), approvalUpdates);

      await pushActivity(
        'admin_adjust',
        `✅ Admin approved ${member.name} (${member.institute}) to join the Arena!`,
        `Starting calibration: ${baselineLabel}${startingXp === 0 ? ' • Underdog 1.25x boost active!' : ''}`,
        member.id,
        startingXp
      );

      notify(
        'Scholar Approved & Activated',
        `${member.name} can now log in with their 4-digit PIN (${startingXp} starting XP).`
      );
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/members/${member.id}`);
    }
  };

