  const handleAdminQuickAdjust = async (e: React.FormEvent) => {
    e.preventDefault();
    const basePath = `artifacts/${appId}/public/data`;
    const targetMem = membersLiveRef.current.find(m => m.id === quickAdjustMemberId) || members.find(m => m.id === quickAdjustMemberId);
    if (!targetMem) return;

    const xpDelta = Number(quickXpDelta) || 0;
    const minsDelta = Number(quickTimeDelta) || 0;
    if (xpDelta === 0 && minsDelta === 0) return;

    const updates: Record<string, any> = {};
    if (xpDelta !== 0) {
      if (isCycle5Active) {
        updates.cycle5BonusXp = (Number(targetMem.cycle5BonusXp) || 0) + xpDelta;
      } else if (isCycle4Active) {
        updates.cycle4BonusXp = (Number(targetMem.cycle4BonusXp) || 0) + xpDelta;
      } else {
        updates.bonusXp = (Number(targetMem.bonusXp) || 0) + xpDelta;
      }
    }
    if (minsDelta !== 0) {
      if (isCycle5Active) {
        updates.cycle5ManualMinutesOffset = (Number(targetMem.cycle5ManualMinutesOffset) || 0) + minsDelta;
      } else if (isCycle4Active) {
        updates.cycle4ManualMinutesOffset = (Number(targetMem.cycle4ManualMinutesOffset) || 0) + minsDelta;
      } else {
        updates.manualMinutesOffset = (Number(targetMem.manualMinutesOffset) || 0) + minsDelta;
      }
    }

    try {
      membersLiveRef.current = membersLiveRef.current.map(m => m.id === targetMem.id ? { ...m, ...updates } : m);
      setMembers(prev => prev.map(m => m.id === targetMem.id ? { ...m, ...updates } : m));
      await updateDoc(doc(db, basePath, 'members', targetMem.id), updates);

      const summaryParts: string[] = [];
      if (xpDelta !== 0) summaryParts.push(`${xpDelta > 0 ? `+${xpDelta}` : xpDelta} XP`);
      if (minsDelta !== 0) summaryParts.push(`${minsDelta > 0 ? `+${minsDelta}` : minsDelta} mins`);

      await pushActivity(
        xpDelta < 0 || minsDelta < 0 ? 'penalty' : 'admin_adjust',
        `Admin adjusted ${targetMem.name}: ${summaryParts.join(' & ')}`,
        quickAdjustReason.trim() || 'Admin manual adjustment',
        targetMem.id,
        xpDelta
      );

      setQuickXpDelta('');
      setQuickTimeDelta('');
      setQuickAdjustReason('');
      notify('Adjustment Applied', `Updated ${targetMem.name}: ${summaryParts.join(', ')}`);
    } catch (err) {
      handleFirestoreError(err, OperationType.UPDATE, `${basePath}/members/${targetMem.id}`);
    }
  };

  const handleAdminResetAllToZeroForCycle5 = async () => {
    if (!isAdminUnlocked && activeMemberId !== 'admin') {
      notify('Admin Access Required', 'Only the Administrator can reset cycle XP.', 'error');
      return;
    }
    const basePath = `artifacts/${appId}/public/data`;
    const nowTs = Math.max(Date.now(), getServerSyncedNow());
    const currentCycleNum = Math.max(5, Number(arenaSettings.currentCycle) || 5);
    const activeList = membersLiveRef.current.length > 0 ? membersLiveRef.current : members;
    try {
      const resetUpdates = {
        cycle5BonusXp: 0,
        cycle5ManualMinutesOffset: 0,
        unexcusedZero: false,
        unexcusedReason: '',
        unexcusedAt: null,
        isGrinding: false,
        grindingStartedAt: null,
        grindingAccumulatedSeconds: 0
      };
      membersLiveRef.current = activeList.map(m => ({ ...m, ...resetUpdates }));
      setMembers(prev => prev.map(m => ({ ...m, ...resetUpdates })));

      for (const m of activeList) {
        await updateDoc(doc(db, basePath, 'members', m.id), resetUpdates);
      }

      const arenaCleanUpdates = {
        currentCycle: currentCycleNum,
        currentCycleStartMs: nowTs,
        leaderboardHidden: false,
        simulateFridayBlackout: false,
        autoLocked: false,
        hiddenAt: null,
        manualAdminReveal: true,
        revealTimestamp: nowTs,
        scheduledBlackoutUnlockAt: null,
        scheduledBlackoutPreNotified: false,
        raidBossCurrentHp: Number(arenaSettings.raidBossMaxHp) || 3000,
        lastRaidDamageHit: null
      };
      isBlackoutActiveRef.current = false;
      setAdminPeekStandings(false);
      setArenaSettings(prev => ({ ...prev, ...arenaCleanUpdates }));
      await setDoc(doc(db, basePath, 'settings', 'arenaState'), arenaCleanUpdates, { merge: true });

      handleSetLeaderboardScope('current_week');
      await pushActivity(
        'admin_adjust',
        `🚀 Admin Reset All Scholars to 0 XP for Cycle ${currentCycleNum}!`,
        `Cycle ${currentCycleNum} Clean Slate active • Blackout disabled • All scholars starting at 0 XP.`,
        'admin',
        0
      );
      notify(`Cycle ${currentCycleNum} Reset Complete! 🚀`, `Every scholar is now at 0 XP for Cycle ${currentCycleNum} and Blackout is disabled.`);
    } catch (err) {
      handleFirestoreError(err, OperationType.WRITE, `${basePath}/settings/arenaState`);
    }
  };

  const handleAdminStartNewCycle = async (overrideTargetCycle?: number) => {
    if (!isAdminUnlocked && activeMemberId !== 'admin') {
      notify('Admin Access Required', 'Only the Administrator can start a new cycle.', 'error');
      return;
    }
    const currentCycleNum = Math.max(5, Number(arenaSettings.currentCycle) || 5);
    const nextCycleNum = overrideTargetCycle || (currentCycleNum + 1);
    const nowTs = Math.max(Date.now(), getServerSyncedNow());
    const basePath = `artifacts/${appId}/public/data`;

    try {
      const sprintRecord = buildLiveWeeklySprintRecord(currentCycleNum);
      const updatedHistory = mergeSprintHistory([
        ...mergedSprintHistory,
        sprintRecord
      ]);

      const activeList = membersLiveRef.current.length > 0 ? membersLiveRef.current : members;
      const resetUpdates = {
        cycle5BonusXp: 0,
        cycle5ManualMinutesOffset: 0,
        unexcusedZero: false,
        unexcusedReason: '',
        unexcusedAt: null,
        isGrinding: false,
        grindingStartedAt: null,
        grindingAccumulatedSeconds: 0
      };
      membersLiveRef.current = activeList.map(m => ({ ...m, ...resetUpdates }));
      setMembers(prev => prev.map(m => ({ ...m, ...resetUpdates })));

      for (const m of activeList) {
        try {
          await updateDoc(doc(db, basePath, 'members', m.id), resetUpdates);
        } catch (e) {
          console.error('Error resetting member for new cycle:', m.id, e);
        }
      }

      isBlackoutActiveRef.current = false;
      const nextSleeperForNewCycle = pickNextWeeklySleeperAgent(
        arenaSettings.weeklySleeperAgent || DEFAULT_WEEKLY_SLEEPER_AGENT,
        activeList,
        nextCycleNum,
        getIsoWeekKey(new Date(nowTs))
      );
      const newCycleSettings = {
        currentCycle: nextCycleNum,
        currentCycleStartMs: nowTs,
        leaderboardHidden: false,
        simulateFridayBlackout: false,
        autoLocked: false,
        hiddenAt: null,
        manualAdminReveal: true,
        revealTimestamp: nowTs,
        lastAutoLockDate: new Date(nowTs).toISOString().split('T')[0],
        scheduledBlackoutUnlockAt: null,
        scheduledBlackoutPreNotified: false,
        reigningSprintId: sprintRecord.id,
        sprintHistory: updatedHistory,
        raidBossCurrentHp: Number(arenaSettings.raidBossMaxHp) || 3000,
        lastRaidDamageHit: null,
        weeklySleeperAgent: nextSleeperForNewCycle
      };

      setAdminPeekStandings(false);
      setActiveRevealSprintId(sprintRecord.id);
      lastRevealTimestampRef.current = nowTs;
      setArenaSettings(prev => ({ ...prev, ...newCycleSettings }));

      const settingsRef = doc(db, basePath, 'settings', 'arenaState');
      await setDoc(settingsRef, newCycleSettings, { merge: true });

      triggerKahootRevealSequence(sprintRecord.id);
      handleSetLeaderboardScope('current_week');

      await pushActivity(
        'reveal',
        `🚀 CYCLE ${nextCycleNum} IS LIVE! Winner: ${sprintRecord.winnerName} (#1, ${sprintRecord.winnerXp} XP) for Cycle ${currentCycleNum}!`,
        `Cycle ${currentCycleNum} standings archived. All scholars start at 0 XP for Cycle ${nextCycleNum}!`,
        sprintRecord.winnerId || 'admin',
        sprintRecord.winnerXp
      );
      notify(
        `🚀 Cycle ${nextCycleNum} Started!`,
        `Cycle ${currentCycleNum} winner ${sprintRecord.winnerName} crowned & archived! All scholars reset to 0 XP for Cycle ${nextCycleNum}.`
      );
    } catch (err) {
      handleFirestoreError(err, OperationType.WRITE, `${basePath}/settings/arenaState`);
    }
  };

  // Squad Bounty Creation & Task Editing
