              {/* Live Recalculated Percentile Preview */}
              {(() => {
                const tot = Number(editExamForm.totalStudents) || 0;
                const rnk = Math.max(1, Number(editExamForm.overallRank) || 1);
                const maxSubj = (editExamForm.subjects || []).reduce(
                  (max: number, s: any) => Math.max(max, Number(s.rank) || 0),
                  0
                );
                const highestRnk = Math.max(rnk, maxSubj);
                if (tot < highestRnk) {
                  return (
                    <div className="p-3.5 rounded-2xl bg-rose-500/15 border border-rose-400/40 flex items-center justify-between gap-3">
                      <div>
                        <div className="text-[11px] font-bold text-rose-300">⚠️ Total Students Smaller Than Rank</div>
                        <div className="text-[10px] text-rose-200/90">
                          Total Students ({tot}) must be at least #{highestRnk} to calculate a valid percentile.
                        </div>
                      </div>
                      <button
                        type="button"
                        onClick={() => setEditExamForm({ ...editExamForm, totalStudents: Math.max(highestRnk, 473) })}
                        className="px-2.5 py-1.5 rounded-xl bg-rose-500/25 hover:bg-rose-500/40 border border-rose-400/50 text-white font-bold text-[11px] font-mono-num cursor-pointer shrink-0"
                      >
                        Set {Math.max(highestRnk, 473)}
                      </button>
                    </div>
                  );
                }
                const previewPct = calcPercentile(rnk, tot).toFixed(2);
                return (
                  <div className="p-3.5 rounded-2xl bg-amber-500/10 border border-amber-400/30 flex items-center justify-between gap-3">
                    <div>
                      <div className="text-[11px] font-bold text-white">Normalized Standing Preview</div>
                      <div className="text-[10px] text-slate-300">
                        Rank #{rnk} out of {tot} students ({editExamForm.overallMarks}/{editExamForm.overallMaxMarks})
                      </div>
                    </div>
                    <div className="text-base font-extrabold text-amber-400 font-mono-num">
                      {previewPct}%ile
                    </div>
                  </div>
                );
              })()}

